window.__D("text/sefer-hasichot-rayatz/c007",{"p":[[4301600457,"ווערט געשאַפן ענינים בסדר והנהגה בעניני תורה ומצות לפי אופן ומצב הזמן, האָט אַ שרש, והראי' מורינו הקדוש הבעש\"ט נ\"ע האָט מגלה געווען אַ אור חדש, מורינו המגיד ממעזריטש ותלמידיו הצדיקים הקדושים נ\"ע האָבן געעפנט דרכי אורחות חיים.\nרבינו הגדול נ\"ע האָט געלייגט דעם יסוד פון דעם בנין הענקי חב\"ד יצ\"ו און במשך פון די זיבן און דרייסיק יאָר פון זיינע נשיאות<sup data-n=\"1742\">3</sup> מיט זיינע באַוואוסטע מסירת נפשו הקדושה והטהורה האָט ער אויס געבויט דעם היכל הוי', און די הייליקע רביים, כ\"ק אבותינו רבותינו הק' נ\"ע, כל אחד בדורו פעל ועשה במסירת נפשו להגדיל ולהאדיר את ההתעסקות בתורה ועבודה.\nיע, אמת אַז בכל עת ובכל זמן לפי מעמד ומצב העולם מוז געשאַפן ווערן בעזרתו ית' ענינים ודרכים באיזה אופן לחזק ההתעסקות בתורה ועבודה. עס שטייט<sup data-n=\"1743\">4</sup> מה טובו אהליך יעקב משכנותיך ישראל, שטייט לשון רבים, ער רעדט דאָך איבער דעם כלל ישראל האָט ער דאָך געדאַרפט זאָגן מה טוב אהל יעקב ומשכן ישראל, פאַרוואָס זאָגט ער מה טובו אהליך יעקב משכנותיך ישראל, ריבוי אהלים און ריבוי משכנות, נאָר דער אמת איז ווייל אין דעם איז פאַראַן כמה מדריגות, אָבער מען טאָר ניט פאַרגעסן איף אַ רגע און מען מוז אַלע מאָל געדענקען אַז די אַלע זיינען אהלי יעקב ומשכנות ישראל.\nעס זיינען פאַראַן באַזונדערע נוסחאות, ווי עס איז ידוע<sup data-n=\"1744\">5</sup> ענינם של י\"ב שבטים, והשערים שהיו במקדש, אָבער וואָס געהערט אין דעם ענין פון סור מרע ועשה טוב איז כולם שוים.\nמען רעדט דאָ ניט פון דעם ועשה טוב וואָס דער היפוך דערפון איז סור מרע, מכח אַזעלכע זאַכן רעט מען ניט, נאָר מען רעט מכח דעם ועשה טוב ווי ע\"פ חסידות איז, וואָס אין דעם איז אויך ניטא קיין שינוי הזמן, אדרבה עס איז נשתנה המצב לטוב, עס איז דאָך עקבות משיחא מיר גייען ב\"ה נעענטער צום שליאך, וואָס אַ טאָג, וואָס אַ וואָך וואָס אַ חודש ווערן מיר נעענטער צום בעתה און מכל שכן צום אחישנה<sup data-n=\"1745\">*5</sup>.\nתורה ומצות זיינען נצחים שינוי הזמן איז ניטאָ, וואָס מען האָט אַמאָל ניט געמעגט מעג מען היינט אויך ניט, וואָס מען האָט אַמאָל געדאַפרט טאָן מוז מען היינט טאָן.\nנאָר אין דער צייט, דאָס הייסט אין די לעצטע צען פופצען יאָר, וואָס בא סנחרב ובלבל את העולם<sup data-n=\"1746\">6</sup>, און אידן זאָלן געזונט זיין האָבן זיך צושפרייט איבער סיבות שונות אין פערשידענע לענדער, וואָס דאָס אַליין איז דאָך על פי סדר ההשגחה העליונה ווי עס שטייט<sup data-n=\"1747\">7</sup> כי בארבע רוחות השמים פרשתי אתכם, די השגחה עליונה פירט אין מעקסיקע און אין אורוגוואיי והדומה בכדי ער זאָל דאָרטן מאַכן אַ שול ברענגען אַ רב, מאַכן אַ מקוה אַ חדר און בעלייכטן דעם געגנט מיט תורה ומצות און מדות טובות.",[["1742","3","ראה רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 231. מאמר \"אבות החסידות\" ב\"התמים\" חוברת ב ע' נ [עב, ב] ואילך."],["1743","4","בלק כד, ה."],["1744","5","ראה לקוטי אמרים להרב המגיד סימן קלג. מאמרי אדה\"ז הקצרים ע' תקפא ואילך. שער הכולל בהקדמה. וראה גם לעיל ע' 163."],["1745","*5","ראה ישעי' ס, כב. סנהדרין צח, א."],["1746","6","ראה ברכות כח, א."],["1747","7","זכרי' ב, י (ושם: כארבע)."]]],[4301600458,"די אַרבעט איז זייער אַ שווערע עס קומט אַ איד מיט אַ פאמיליע זאָל געזונט זיין אַ נע­ונד'ניק, דורך געגאַנגען אַזאַ שווערע ביטערע וועג, פרעמד פון תנאי המקום און ער אָט דער צובראָכענער איד, דאַרף אויס פירן די כונה העליונה, להאיר מחשכי ארץ<sup data-n=\"1748\">8</sup> הלזו הגשמי' באור תורה ומצות ומדות טובות און וואו אין אַמעריקא יאפאן און חינא.\nעס איז ניט קיין גרינגע שטיקל אַרבעט אפילו אין וואַרשע אין אין ווילנא וואו ב\"ה מען טוט זיך אַ קער איז אָן ע\"ה עוסקים בתורה ועבודה כן ירבו, ובפרט די וואָס זיינען עלול צו זיין בעזה\"י עוסקים בתורה ועבודה, איז די אַרבעט אַ שווערע, היינט מכש\"כ אין די ווייטע לענדער איז אין אַזאַ מצב איז פאַראַן זאַכן וואָס די עלטערן דאַרפן מעלים עין זיין פון די אינגערע.\nדי העלמת עין מיינט מען ניט העלמת עין פון גראָבע זאַכן, דאָס הייסט ח\"ו מעלים עין זיין פון דעם וואָס מען טאָר ניט, דאָס וואָס מען טאָר ניט, האָט מען אַמאָל ניט געטאָרט און מען טאָר איצטער ניט, מיט די גאַנצע האַרבקייט ווי עס איז געווען, אין דעם איז ניטאָ קיינע הנחות, נאָר אין ענינים פון הנהגה איז באַ געוויסע זאַכן דאַרף מען האָבן העלמת עין.\nדער העלמת עין מיינט ניט אַז דאָס איז אַ היתר וואָס מיא איז יענעם מתיר, אָדער אַ געוויסע קולא, ניין, און בפרט אין די מדינות די באָרד דאַרף מען ניט שערן, אין מיט אַ סם דאַרף מען ניט גאָלן, מען רעט דאָ ניט מכח דעם איסור והיתר פון דעם, אָדער פון אַנדערע אַזעלכע זאַכן, מען רעט מכח דעם אַז די זאַכן זענען פותח שערי טומאה ר\"ל.\nאַז מען גייט מיט אַ באָרד און פאות, מעט גייט מיט לבושים ווי עס דאַרף זיין, איז דאָס אַליין אַ געוויסע הגדרה, און אַ געוויסע הגבלה, אַז מען איז ניט שייך צו קיין אַנדערע סביבה, במילא איז מען שייך צו דער סביבה פון תורה ומצות. אָבער אַז מען שערט די באָרד<sup data-n=\"1749\">9</sup>, מען פוצט זיך אָדער מען נעמט אָראָפּ מיט אַ סם, נעמט מען אַראָפּ די הגבלה און די הגדרה, דאַן איז ער גלייך מיט אַלעמען.\nאָט דער גלייכער שנירל וואָס אַלע זיינען גלייך דאָס הייסט, דאָס וואָס מענטשן האָבן זיך אָנגעהויבן אויס­גלייכן, אַז יענער טוט דאַרף ער אויך טאָן האָט אָנגעמאַכט רוחניותדיקע חורבנות, און אין דעם גייט נאָך אַוועק די געוויסע פלפולים אויף דעם יסוד, אַז יענער טוט אַזוי מעג ער אויך טאָן אַזוי.\nדער העלמת עין וואָס מען מיינט דאָ איז אַ געוויסע סבלנות, זאָגן יענעם דעם אמת, דעם גאַנצן אמת ווי ער איז אָן קיינע הנחות און אָן קיינע קולות און נאָר יעדער זאַך זאָגן מיט אַ געוויסן אויסרעכענונג, מיט אהבה און מיט קירוב אָן נעמען יענעם פאַר אַ פינגער, און מקרב זיין צו זיך, נאָר אין דעם דאַרף מען זיין זהיר, עס זאָל ניט זיין ח\"ו עד\"מ ווי איינער טרינקט זיך ר\"ל און מען נעמט אים אָן פאַר אַ פינגער, וואָס לא די מען איז יענעם ניט מציל, אדרבה ח\"ו ער קען נאָך דעם אַנדערן אויך אַריינשלעפן, און אַז די כוונה איז בשביל הקירוב, און דער קירוב איז מיט אַ סדר ווי ע\"פ תורה, דאַן איז דורך דעם קירוב ווערט ער מיט דער צייט אין גאַנצן נתקרב צום טוב באמת.\nאח\"כ פנה כ\"ק אדמו\"ר שליט\"א",[["1748","8","לשון הכתוב — תהלים עד, כ."],["1749","9","ראה לעיל ע' 35."]]],[4301600459,"להתמימים תלמידי הישיבה ואמר: די תמימים ווייסן ניט דעם סדר ווי עס האָט זיך געפירט אין ליובאַוויטש, הגם מען קען אויף זיי מלמד זכות זיין, זיי זיינען פאַרטראָגן אין לערנען אין תורה הנגלית, אין חסידות און אין דאַוונען קענען זיי זיך ניט אָפּגעבן צו דעם סדר ווי עס איז געווען אין ליובאַוויטש, אָבער עס פעלט די לחלוחית.\nעד\"מ וואָס אַ בנין מאַכט מען פון עצים ואבנים, כדאי' בספר יצירה<sup data-n=\"1750\">10</sup> שתי אבנים בונות שתי בתים, וואָס אַ בנין מאַכט מען פון ציגל, אָבער פון בלויז ציגל אַליין קען מען נאָך קיין בנין ניט מאַכן, עס דאַרף אויך זיין חומר צו מחבר זיין די ציגל, און דער חומר דאַרף זיין מיט לחלוחית.\nמשא\"כ אַז איינער האָט בלויז ציגל, ער איז אַ גביר האָט מיליאָנען ציגל, אָבער קיין בנין קען ער דערפון ניט מאַכן, ער זאָל אַרויף שטעלן איין ציגל אויפן אַנדערן אָנשיטן זאַמד און מסדר זיין ווי אַ בנין, איז אַ סכנה דורך צוגיין אַרום דעם בנין, עס קען זיין ח\"ו עס זאָל אַראָפּ פאַלן אַ ציגל פון זעקסטן שטאָק, און יענער קען אַוועק גיין אָן אַ קאָפּ, מען מוז האָבן חומר ולחלוחית אויף מחבר זיין די לבנים זיי זאָלן האָבן אַ קיום. עס זאָל בלייבן די לחלוחית טויג אויך ניט, עס איז ניט קיין בית מושב, די לחלוחית מוז פאַרטריקנט ווערן און דאַן ווערט דאָס אַ בית מושב לאדם.\nאַזוי איז אויך אַז איינער לערנט גמרא, פוסק[ים], ער פאַרמאָגט אַ הון עצום, ער האָט מיליאָנען ציגל נאָר עס פעלט די לחלוחית און די התדבקות, פון אַזאַ דאַרף מען זיך היטן און אין זיינע ד' אמות טאָר מען ניט שטיין ווייל מען קען אַוועק גיין אָן אַ קאָפּ ח\"ו.\nעס איז זייער נויטיק צו לערנען מזמן לזמן די מאמרים החלצו רנ\"ט<sup data-n=\"1751\">11</sup>, ושבתה רס\"ב<sup data-n=\"1752\">12</sup>. די אַלע חסרונות פון שנאת חנם, פירוד לבבות, תערובות טוב ורע, וואָס אין יענע מאמרים ווערט אַרומגערעדט זיינען לדאבון לבבינו אַ סחורה מהלכת באַ חסידים שי', און די עצות צו די חסרונות פוילט מען זיך זוכן און מקיים זיין.\nעס זיינען צווישן אנ\"ש שי' פאַראַן גבירים אדירים, וואָס פאַרמאָגן אַ סאַך ציגל, אותיות פון תורת הנגלית, אותיות פון תורת החסידות, און ניט נאָר אותיות אַליין נאָר טאַקע אַ גאַנץ פיינע הבנה מיט טיפע הסברות, און אפילו אַזעלכע וואָס זיינען בקיאים אין היבש מאמרים, אָבער דאָס איז אַ בנין פון ציגל, דאָס איז ניט קיין בית מושב, דאָס גיט אין קאָפּ, ער איז מבטל את זולתו, דער אַנדערער האָט קיין אָרט ניט, ויש בזה ריבוי פרטים ואופנים שונים, והסבה העקרית היא שחסר הלחלוחית.\nדער ענין פון התדבקות און לחלוחית איז אַ חסידישער פאַרברענגען און עבודה שבלב.\nאַ חסידישער פאַרברענגען האָט אַמאָל געגעבן אַ יונגענמאַן אַ יסוד אין לעבן, באַ דעם חסידישן פאַרברענגען",[["1750","10","פרק ד משנה יב. ובקצת דפוסים — משנה טז."],["1751","11","נדפס בסה\"מ תרנ\"ט ע' נג ואילך. ועם הוספות וכו' ד\"ה נ\"ר חנוכה תרצ\"ד (נדפס בסה\"מ תרנ\"ט ע' ריא ואילך)."],["1752","12","נדפס בסה\"מ תרס\"ב ע' רצו ואילך. ועם הוספות ד\"ה ממושבותיכם תביאו תרפ\"ג. ד\"ה כי ישרים תרפ\"ד. ד\"ה הבונה בשמים מעלותיו תרפ\"ה. ד\"ה אני חומה תר\"ץ. תרצ\"ב."]]],[4301600460,"האָט מען געזען וואָס ידידות איז, וואָס אהבה וחבה איז, און וואָס מען רופט אמת, וואָס איז ענו, און ווי מען דאַרף זיין איבערגעגעבן עלטערע חסידים.\nר' שמואל מונקעס<sup data-n=\"1753\">13</sup>, דעם אלטן רבי'ס אַ חסיד, נאָך גאָר פון די ערשטע, אַ הצנע לכת, איינמאָל<sup data-n=\"1754\">14</sup> באַ אַ פאַרברענגען האָט ער געהאַלטן דעם פאַרבייסן. פערשידענע פליישיקע מאכלים וואָס דער שו\"ב האָט געבראַכט. אַז מען האָט געבעטן פאַרבייסן האָט ער ניט געגעבן, פאַרוואָס ער גיט ניט האָט ער ניט געזאָגט.\nדער עולם האָט גוט פאַרבראַכט, און מען האָט געוואָלט פאַרבייסן, און ער גיט ניט, האָט דער עולם געוואָלט נעמען בחזקה, און מען האָט זיך גענומען אַמפּערן מיט אים, ער האָט דערזען אַז עס איז שלעכט באַלד וועט מען אים גובר זיין האָט ער גענומען דעם גאַנצן פאַרבייסן און אַריינגעוואָרפן אין דער כלי פון די אומריינע וואַסער.\nאַז דער עולם האָט דאָס דערזען איז מען געוואָרן פאַרוואונדערט אָבער פאַרפאַלן מען האָט אים געוואָלט געבן קאָרקעס, דערווייל איז מען געקומען צולויפן פון שוחט זאָגן אַז מען זאָל דעם פאַרבייסן ניט עסן, ווייל עס איז אַ גרויסע שאלה און אַלץ איז טריפה.\nדאַן ערשט האָבן זיך די עלטערע חסידים גענומען צו ר\"ש מונקעס מאָנען באַ אים ווי קומט ער צו אַזעלכע הויכע דרכים, וויסען רוח הקדש זאַכן. צום סוף נאָך אַ סאך ריידעניש האָט ער געזאָגט אַז ער האָט געדאַרפט דעם ערשטן מאָל אַריינגיין צום רבי'ן אויף יחידות האָט ער מחליט געווען אַז אַ ענין גשמי וואָס עס ווילט זיך זאָל ער ניט טאָן<sup data-n=\"1755\">15</sup>.\nאון אַז ער האָט גענומען דעם פאַרבייסן אין האַנט האָט זיך אים זייער געוואָלט דאָס עסן, האָט ער דאָס ניט געגעסן, און אַז ער האָט געזען אַז דער עולם וויל שטאַרק דעם פאַרבייסן האָט ער אים אַרויס געוואָרפן.\nיעדער תנועה פון איין אַלטן חסיד איז אַ ליכט אין לעבן, אַ יסוד מוצק אין דרך החיים. הערט זיך צו חסידים און תלמידי התמימים די ערשטע טרעפּ אַריין גיין צום רבי'ן אויף יחידות איז מיט אַ החלטה און הגדרה אין אַ הידור דבר. עס רעדט זיך ניט וועגן סו\"מ ועש\"ט בפו\"מ מכח אַזאַ זאַך איז גאָר ניטאָ צו ריידן, אַ מדה לא טובה האָט מען אויסגעברענט מיטן וואָרצל, ידידות און אהבה וחבה יתירה האָט מען באַגעגנט אויף יעדער טריט.\nאַמאָל איז געזעסן ר' משה ווילענקער<sup data-n=\"1756\">16</sup>, דעם אלטען רבי'ס אַ חסיד און האָט דערציילט וואָס פאַר אַ קירוב און הדרכה ער האָט געהאַט פון חסידים בעת ער איז דעם ערשטן מאָל געקומען אין ליאָזנע צום רבי'ן, פינף חדשים איז ער געזעסן און געהערט און געלערנט ביז ער האָט געפילט אַז ער מאָג און קען אַריין גיין צום רבי'ן אויף יחידות.",[["1753","13","ראה אודותו בהנסמן לעיל ע' 67."],["1754","14","ראה גם ספר השיחות תש\"ג ע' 175 ואילך."],["1755","15","ראה קונטרס העבודה ספ\"ב: כבר סיפרתי מא' מהחסידים הגדולים אשר בהכניסה הראשונה לכ\"ק אדמו\"ר [הזקן] זצוקללה\"ה נ\"ע זי\"ע פעל בעצמו שכל מה שרוצה מצד הטבעי לא יעשה (אז וואס ער וויל זאל ער ניט טאן). וראה גם לעיל ע' 17."],["1756","16","ראה אודותו לעיל ע' 244. וש\"נ."]]],[4301600461,"יעדער וואָרט וואָס מען האָט געהערט פון אַ חסיד האָט מען עס געלערנט, געחזרט, אַריין גענומען אין קאָפּ און אין האַרצן, אַז מען האָט געקוקט אויף דעם רבי'ן איז דאָס ביי זיך געווען ווי גילוי שכינה, און אַז מען האָט געהערט אַ תורה פון רבי'ן (ניט מער ווי איין מאָל אין חדש, די איבעריקע מאָל האָט מען ניט אַריינגעלאָזן), האָט מען געחזרט פופציק זעכציק מאָל אַז איינער איז געווען אויף יחידות איז מען געווען בתשוקה גדולה וויסן וואָס דער רבי האָט אים געזאָגט.\nאַמאָל איז געזעסן ר' הלל פאַריטשער<sup data-n=\"1757\">17</sup>, ר' זלמן זעזמער<sup data-n=\"1758\">18</sup> און ר' פסח מאלאסטאווקער<sup data-n=\"1759\">19</sup> און מען האָט פאַרבראַכט, מען האָט זיך געטראָפן אין ליובאוויטש אומגעריכטערהייט, האָט מען זיך געפרייט איינער מיט דעם אַנדערן באהבה וידידות נפלאה, דערוויילע איז אַריין געגאַנגען ר' אייזיק האָמליער<sup data-n=\"1760\">20</sup> איז געוואָרן די שמחה גרעסער, און מען האָט זייער גוט פאַרבראַכט.\nכידוע איז ר' זלמן געווען אַ משכיל נפלא און אַ גרויסער עמקן, פלעגט ריידן זייער קורץ און זייער טיף (דער אלטער רבי האָט געזאָגט, זלמנ'ס אַ וואָרט מעג מען לערנען. הוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע באחד המאמרים מביא בשמו<sup data-n=\"1761\">21</sup>, גולל אור מפני חשך וחשך מפני אור<sup data-n=\"1762\">22</sup>, גולל אור שלפני הצמצום, מפני חשך הצמצום וחשך הצמצום מפני שיתגלה אור העצמי<sup data-n=\"1763\">23</sup>), און ער האָט געמאַכט ר' הלל פאַריטשער פאַר אַ חסיד.\nר' פסח איז געווען אַ גרויסער עובד און אַ בעל מדות תרומיות, בעת דעם פאַרברענגען האָט זיך ר' פסח מאלאסטאווקער שטאַרק צו וואַרעמט און האָט אַרום גענומען ר' זלמן זעזמער און האָט אים האַרציק געקושט און האָט זיך שטאַרק צו וויינט. ואמר זלמן, זלמינקע, אַך ווען דיין האַרץ וואָלט געווען אַ כלי אמיתית צו דיין קאָפּ וואָלט געווען באופן אחר לגמרי, וואָס פאַר אַ רחמנות אויף דיר איז. האָט ר' הלל פאריטשער געזאָגט אַז ער איז נתפעל געוואָרן פון ר' זלמן זעזמערס מדת חסידות און ר' פסח מאלאס­טאווקער'ס מדת האמת.\nזיי אַלע דריי, ר' זלמן, ר' הלל און ר' פסח זיינען געווען שטאַרק פאַרמאַטערט פון דעם פאַרברענגען און האָבן אָנגעהויבן איינצושלאָפן, ר' אייזיק איז דאָך געקומען שפעטער איז ער נאָך געווען בכח פאַרברענגען, ר' אייזיק איז דאָך געווען אַ בעל חושים וכשרונות",[["1757","17","ראה אודותו לעיל ע' 30. וש\"נ."],["1758","18","ראה אודותו לעיל ע' 244. וש\"נ."],["1759","19","ראה אודותו לעיל שם. וש\"נ."],["1760","20","ראה אודותו לעיל שם. וש\"נ."],["1761","21","ראה שיחת מוצאי חה\"פ שנה זו (לעיל ע' 216)."],["1762","22","ברכות ק\"ש דערבית (ברכות יא, ריש ע\"ב)."],["1763","23","ראה עד\"ז מאמרי אדה\"ז ענינים ע' שיז. תקס\"ז ע' רמה. מאמרי אדמו\"ר האמצעי במדבר ח\"ה ע' א'תשנד. סה\"מ תרנ\"ט ע' עח. המשך תער\"ב ח\"א ע' תקנד. ד\"ה ויקח ה\"א תרצ\"ה פרק כט. שיחות אור לוא\"ו תשרי תשמ\"ה. ד\"ה וישמע יתרו תשמ\"ה. וראה גם תו\"ח תולדות קסא, סע\"ג ואילך. וישלח קפה, ב. תו\"ח שמות תסד, ב. שערי אורה ד\"ה בכ\"ה בכסלו פנ\"ז. סה\"מ תרע\"ח ע' שעח.\nוברשימת הרה\"ח ר' הלל מפאריטש — תלמידו של הרה\"ח ר' זלמן זעזמיר — בענין יום ולילה (לא נדפס לע\"ע): \"שמעתי ממורי נבג\"מ בענין אור מפני חושך, היינו אור העצמי שקדם לחושך ונתעלם בחושך וצמצום, וחושך מפני אור היינו בקיעת הקו הנקרא נהורא שבוקע מן ההעלם הנקרא חושך\"."]]],[4301600462,"נפלאים און אַ בעל ציור בדבור יפה ומסודר, ופה מפיק מרגליות.\nהאָט ר' אייזיק געזאָגט<sup data-n=\"1764\">24</sup>, שלמה המלך איז דאָך געווען נעלה בחכמה וכמ\"ש<sup data-n=\"1765\">25</sup> וה' נתן חכמה לשלמה, החכמה נתונה לך<sup data-n=\"1766\">26</sup>, איז וואָס קען זיין גרעסער, העכער און בעסער ווי חכמה, און נאָך עצם החכמה, מ\"מ האָט ער קיין רבי'ן ניט געהאַט, אַז ער וואָלט פאָרן צו אַ רבי'ן, איז אַ חוץ דעם וואָס די חכמה וואָלט געווען באופן אחר, וואָלט ער האָבן חסידישע חברים, און זיין אויף חסידישן פאַרברענגען, דאַן וואָלט ער אַלע הפלאות פון אוהב ואהוב געמאָלט אויף חסידים און רביים.\nזייענדיק די ערשטע מאָלן אין ליאזנע — זאָגט ר' אייזיק — אַז איך בין נאָך גאָר געווען אַ יונגערמאַנטשיק, האָב איך גענעכטיקט אין קליינעם מנין ביין רבי'ן, און איך האָב זיך אויפגעכאַפּט אין מיטן נאַכט, ערשט זלמן, דעם רבינ'ס משרת<sup data-n=\"1767\">27</sup>, גייט מיט אַ ליכט אין האַנט און דער רבי אַליין גייט, בין איך געוואָרן צומישט, און האָב ניט געהאַט בכח אַ ריר צוטאָן מיט אַ אבר, אָט אַזוי האָט אַ רבי ליב חסידים מער ווי אַ מאַמע אַ קינד.\nאַמאָל האָבן די עלטערע חסידים מקרב געווען יונגע לייט מיט אַ קירוב פנימי, באמת מען האָט ליב געהאַט אַ יונגן מאַן, מען האָט געזען זיינע חסרונות און פאַרשטאַנען זיינע מעלות, און מען האָט אים געהאָלפן אַרויס קריכן פון בלאָטע, און אַוועק שטעלן זיך במקום אורה, אָבער די יונגע לייט האָבן געוואוסט אַז זיי דאַרפן האָבן דרך ארץ.\nדער אַמאָליקער חסידישער דרך ארץ איז געווען מיט אַ ביטול פנימי, מען האָט געפילט דעם עלטערען חסיד'ס מעלה און די אייגענע קליינקייט, אויף יעדער שריט און טריט האָט מען געלערנט ווי ווערט מען פטור פון די מומי בני אדם, און ווי מען נעמט זיך אין האַנט אויף אָן הויבן ווערן אַ מענטש, און מזמן לזמן איז מען אַלץ געגאַנגען העכער און העכער.\nדער חסידישער פאַרברענגען האָט געגעבן די ריכטיקע לחלוחית און דבקות, עס האָט געגעבן אַזעלכע זאַכן אין סור מרע ועשה טוב וואָס עס גייט ניט אונטער, אונטער דעם ענין פון מצוה והיפוכו, נאָר עס איז אַלץ אין העכערע פעל. דאָס הייסט אַז דקות דדקות פון אַ מדה לא טובה, איז דאָך אויך רע, און אַז מען איז מקיים אַ מצוה כתיקונה בהידור איז דאָס נאָך אויך ניט טוב באמת, און אַזוי אַרום איז פון די אַלע ציגל, אותיות התורה ואותיות החסידות געוואָרן אַ בנין חזק באמת.\nנאָר אַזוי ווי אין משל אויב די הויז איז נאַס, אויב דער חומר המדביק את הלבנים האָט זיך ניט אויסגעטריקנט, איז דאָס ניט קיין בית מושב, כמו\"כ איז אין עבודה לחלוחית אַליין איז קיין עבודה ניט. מיט פאַרברענגענס אַליין קען מען ניט יוצא זיין. מען דאַרף האָרעווען און לערנען, מען דאַרף לערנען חסידות, מען דאַרף האָרעווען אין דאַוונען און די התיבשות החומר איז ע\"י מרירות נאָר עס דאַרף זיין אַ מזיגה נכונה בין קו",[["1764","24","הובא בשיחת יום שמח\"ת תשט\"ז."],["1765","25","מלכים­א ה, כו."],["1766","26","דברי הימים­ב א, יב (ושם: החכמה והמדע נתון לך). וראה שהש\"ר פ\"א, א (ט)."],["1767","27","ראה אודותו: ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 209. וש\"נ."]]],[4301600463,"המרירות און קו השמחה וכו'. עס דאַרף זיין עבודה בכח עצמו, אָט כשם ווי דער כללות ענין הצמצום הראשון דהכוונה בשביל הגילוי כמו\"כ בכל או\"א בפרט הכוונה שיהי' הגילוי אור ע\"י עבודה בכח עצמו.\nאיך וואָלט וועלן, שכאו\"א מהתמימים שחפץ להיות מתלמידינו, און וויל זוכה זיין שיאיר עליו אור רבותינו הק', זאָל ער לערנען איין שעה מכ\"ד שעות היום בחבורה מיט נאָך איינעם אַלע טאָג בקביעות, דער רצון פון הוד כ\"ק אבותינו רבותינו הק' איז אַז יעדערער זאָל האָבן אַ חבר<sup data-n=\"1768\">28</sup> און אַ תלמיד, תורת החסידות מאָנט אַז יעדערער דאַרף וויסן אַז אויף אים ליגט אַ חוב פון האָבן אַ חבר און שאַפן זיך אַ תלמיד.\nאַמאָל אין אַ חסידישן פאַרברענגען האָט איינער געזאָגט<sup data-n=\"1769\">29</sup>, אויף תורה שטייט<sup data-n=\"1770\">30</sup> דרכי' דרכי נועם כו', דער סדר פון תורה איז הייליג ווי די תורה אַליין, דער ערשטער ציווי איז פרו ורבו<sup data-n=\"1771\">31</sup>, די ערשטע מדה טובה איז אַז איין איד דאַרף וועלען עס זאָל זיין נאָך אַ איד.\nיעדער איד, אפילו גאָר אַ פּשוטער וואָס קען ווייניק לערנען קען בעזה\"י זייער פיל אויף טאָן אין הרבצת התורה און חיזוק היהדות. מכח דעם איז אויסגעקומען עטלעכע מאָל צוריידן באַרוכה, אַז אפילו גאָר די פּראָסטע אידן, האָבן אונז געבראַכט גרויסע ישיבות און גאוני ישראל, און בפרט חסידישע אידן וואָס זיי זיינען מזמן לזמן בחנות של בושם<sup data-n=\"1772\">32</sup>, איז געוויס אַז יעדער קען בעזה\"י גאָר אַ סאַך אויף טאָן.\nפאַראַן אַזעלכע וואָס זאָגן אַז זיי האָבן ניט קיין סביבה, עס איז ניט פאַראַן מיט וועמען צו ריידן אַ וואַרעמען וואָרט. ווי שעמען זיי זיך ניט אַזוי צו זאָגן, זיי זיצן בע\"ה אין אַ מדינה וואו עס איז ניטאָ קיין מניעות בעזה\"י אויף לימוד התורה, היינט ווי האָט ער דאָס ניט קיין סביבה דאָס איז אַ הוראה אַז עס איז גאָר קיין ער ניטאָ.\nידידינו אנ\"ש בכלל און תלמידים התמימים בפרט פאַרגעסן אַז יעדער פון זיי דאַרף זיין אַ משפיע, ער דאַרף און מוז ווירקן אויף דעם זולת, היינו לבד זאת וואָס ער אַליין מיט זיין הנהגה הן תפלה און קביעות עתים לתורה, און הן במדותיו לדרוש בטובת זולתו, מוז יעדער זוכען און ליגען אין דעם ווי אַרום צו ווירקען על הזולת לקרבו לתפלה, לתורה למדות טובות.\nמען דאַרף זיין אַ משפיע אויף דער סביבה און מאַכן אַ סביבה, ניט זיין אַ מושפע פון דער פּראָסטער בעלי­בתי'שער סביבה. און די וועלכע זאָגן אַז זיי האָבן ניט קיין סביבה וואָס זיי זאָלן קענען ריידן אַ תורה וואַרעמען וואָרט, איז דאָס אַ הוראה אַז עס איז קיין ער ניטאָ, ער איז ניט ווי עס בעדאַרף זיין.\nדי דעה און דער קוק אַז עס פעלט אַ סביבה, איז ניט ווייל דאָס איז אַ חסרון אין חינוך אָדער אין יסוד העבודה. דער חינוך און דער יסוד איז אַ גוטער, נאָר עס פעלט אַ סדר אין עבודה. חסידות מאָנט זעהן אַ מעלה באַ יענעם, אָבער אַז די עבודה איז בלתי מסודרה, דאַן זעט מען די מעלה באַ זיך און דעם חסרון",[["1768","28","ראה אבות פ\"א מ\"ו."],["1769","29","ראה ספר השיחות: תר\"פ­תרפ\"ז ע' 56. שם ס\"ע 81 ואילך; תרצ\"ו — חורף ה'ש\"ת ע' 119. וש\"נ (בהערה 5; 11)."],["1770","30","משלי ג, יז."],["1771","31","בראשית א, כח. נח ט, א."],["1772","32","להעיר מרע\"ב אבות פ\"א מ\"ד."]]],[4301600464,"באַ יענעם, די רפואה צו דעם איז אַ חסידישער פאַרברענגען.\nעס דאַרף זיין דער ענין פון פרוטה לפורטה. אין גשמיות זעהן מיר אַז מען קען זיין אַ גרויסער גביר האָבן גרויסע הייזער און ניט האָבן אויף קיין ברויט, אין קראָם קען מען קיין הייזער ניט טראָגן, אויף קויפן ברויט דאַרף מען האָבן אַ מזומענע מטבע. כמו\"כ אין רוחניות, מען קען לערנען תורה הנגלית, און חסידות, און ניט האָבן דעם פרוטה לפורטה מיט וואָס צו גיין אין גאַס, זיין אַ סור מרע, עוצם עיניו מראות ברע ואוטם אזניו משמוע<sup data-n=\"1773\">33</sup>, און זעהן וואָס מען דאַרף זעהן, און וואָס מען דאַרף הערן.\nאיך וועל אייך דערציילן אַ מעשה. אַמאָל בין איך געווען באַ דעם טאַטן, און עס איז געווען אַ זמן וואָס תומכי תמימים איז געשטאַנען אין אַ מצב מרומם, וואָס מען קען דאָס זעהן פון דעם קונטרס וואָס איז דאַן אַרויס<sup data-n=\"1774\">34</sup>. אויף דעם מיטעלן רבי'ן איז ידוע<sup data-n=\"1775\">35</sup> אַז ער פלעגט אַרויסגעבן די קונטרסים נאָך די סוגים פון חסידים וואָס דאַן איז געווען, איז אויב מיר וועלן זאָגן אַז ביין טאַטן איז אויך אַזוי געווען קען מען זעהן אין וואָס פאַר אַ מצב די תמימים זיינען געשטאַנען, נאָר זיי זיינען געווען אָן אַ משמעת, מען מיינט ניט אַז זיי זיינען ניט געווען גאַנץ אין משמעת החיצוני, נאָר יעדערער האָט פאַרשטאַנען אַז נאָך זיין מצב דאַרף ער לערנען דעם ענין, און דער דאַרף לערנען יענעם ענין<sup data-n=\"1776\">36</sup>. איך בין דאָך געווען דער מנהל האָב איך געפרעגט, וואָס ווילסטו פון זיי? האָט דער טאַטע געענטפערט, זיי דאַרפן זיין די גבורי כח עושי דברו לשמוע בקול דברו<sup data-n=\"1777\">37</sup>. אין פינף יאָר אַרום און בפרט אין דעם אַנדער דור האָט מען געזען ווי זיי זיינען ב\"ה די גבורי כח, השי\"ת יהי' בעזרם בגו\"ר.\nעס איז דאָ נטיעה און זריעה, ויש בזה מעלה וחסרון, ובזה מעלה וחסרון. אין זריעה איז די מעלה שאין צריכים ע\"ז יגיעה גדולה, והחסרון שבכל שנה ושנה דאַרף מען אַקערן און זייען. ובנטיעה יש יגיעה עצומה בהכנת האדמה ואח\"כ לחרוש ולנטוע לעדר ולנכש, אָבער אַז מען פאַרפלאַנצט איז דאָס בעזה\"י אַ דבר של קיימא רק שבאילני הכרם יש תולעים, דער תולעת שבכרם אין לו סגולה ועצה אלא צריכים לשרשם ולרחקם.\nתומכי תמימים איז ע\"ד נטיעה שבכרם און עס דאַרף זיין פירות און עס איז פאַראַן ב\"ה פירות. טאָמער איז ח\"ו פאַראַן אַזעלכע וואָס זיי האָבן תולעים, וואָס אין דעם איז פאַראַן מינים ממינים שונים ובאופנים שונים, דאַרף מען די תולעים מרחיק זיין.\nרבינו הגדול נ\"ע האָט געזאָגט קומענדיק פון פעטערבורג \"מובטחני בהקב\"ה אַז אַ חסידישער שטיקל ברויט וועט פאַרפאַלן ניט גיין\"<sup data-n=\"1778\">38</sup>, דאָס הייסט",[["1773","33","ע\"פ ישעי' לג, טו."],["1774","34","ראה גם לעיל ע' 100 ואילך."],["1775","35","ראה אגרות­קודש ח\"ג ע' שסז (\"היום יום\" טו אדר שני). שיחת יט כסלו תרצ\"ג סעיף יח. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 141."],["1776","36","ראה ספר השיחות תורת שלום ע' 75 ואילך. וראה \"כרם חב\"ד\" גליון 3 ע' 152."],["1777","37","תהלים קג, כ."],["1778","38","ראה ספר השיחות תר\"פ­תרפ\"ז ע' 58. וש\"נ."]]],[4301600465,"אַ חסידישע הדרכה און הנהגה וועט עקבערן און עקבערן ביז עס וועט פועלן לטובה ולברכה.\nדער חסידישער דברי הימים אין משך פון הונדערט און צוואַנציק יאָר (תקע\"ב — תרצ\"ב) מיט די פערשידענע פּאַסירונגען פון די חסידישע הייזער האָט אונז געוויזן אַז אויב אפילו אין אייניגע הייזער האָט די חסידישע ליכטיקייט אָנגעהובין טונקלען, און דער חסידישער ברען אויסצוקילען, דאָך איז געבליבן בע\"ה גרויסע פונקען פון חיבת הקדש, און עס איז צו האָפן להשי\"ת אַז די להבה זאָל ווירקן קערן זיך צום שרש, השי\"ת זאָל אויף זיי רחמנות האָבן בגשמיות וברוחניות.\nאין חסידות רעט זיך אַז מוחין ומדות זיינען בדרך עו\"ע, די עילה איז מחייב דעם עלול, הגם מוחין איז אַ פרצוף בפ\"ע, מ\"מ איז די שלימות פון דער עילה וואָס ער איז מחייב דעם עלול. וואָס מיט דעם ווערט דאָך רעכט אַ קשי' וואָס דער מעזריטשער מגיד נ\"ע פרעגט<sup data-n=\"1779\">39</sup> ווי אַזוי קען מען מאָנען אויף אהבה, עס איז דאָך אַ מדה שבלב. נאָר דער תירוץ איז<sup data-n=\"1779\">39</sup> אַז דורך התבוננות קען מען צוקומען צו אהבה, און דער ציווי איז אויף דער התבוננות.\nאון דאָס איז דער פירוש ואהבת כו' סופך לבוא לידי אהבה<sup data-n=\"1781\">40</sup>, איז דאָך די עילה מחייב דעם עלול פונדעסטוועגן זעט מען אַז הגם ער איז זיך מתבונן און ער פאַרשטייט און פונדעסטוועגן ווערט ער ניט נתפעל. דער תירוץ איז אַז עס איז פאַראַן טמטום הלב, וואָס לבו אטום מלקבל אור אַז ער זאָל נתפעל ווערן פון דעם ענין וואָס ער האָט פאַרשטאַנען במוחו.\nדי עצה איז דערצו חקיקה מבחוץ<sup data-n=\"1782\">41</sup>, דאָס איז דער לזמר עריצים<sup data-n=\"1783\">42</sup> וואָס איז די עבודה אין תפלה, ווי עס איז מבואר ענינו בקונטרס התפלה תר\"ס, און לעורר ר\"ר על נפשו, גוט דורך וויינען זיך און בעטן השי\"ת בתפלה ותחנונים אַז ער זאָל צו לאָזן אַז מען זאָל נתקרב ווערן לאלקות. באַ אַמאליקע חסידים פלעגט זיין אַ וואונטש וואָרט איינער דעם אַנדערן, השי\"ת זאָל זיך מרחם זיין אַז עס זאָל זיך דאַוונען.\nעס איז פאַראַן אויך טמטום המוח ר\"ל, דער ענין הטמטום איז וואָס באַ עם לייגט זיך ניט אָפּ קיין ענין אלקי, וואָס דאָס איז פאַראַן באופנים שונים, און אויך בדקות, און אין חסידות איז פאַראַן עצות ווי אַראָפּ צונעמען דעם טמטום המוח, און איינע פון די עצות איז דורך זיעה של מצוה בכלל, וזיעה של הידור מצוה בפרט.\nדער רבי האָט געזאָגט<sup data-n=\"1784\">43</sup>, אבוך במה הוה זהיר טפי<sup data-n=\"1785\">44</sup>, זהיר הייסט לייכטען, עס שטייט<sup data-n=\"1786\">45</sup> כי נר מצוה, אַ מצוה לייכט, יעדער נשמה האָט אַ מצוה פרטי' וואָס די נשמה איז איר עבודה אין דער מצוה, דאָס הייסט אַז די מצוה איז כמו שער",[["1779","39","הובא בספר שני המאורות (למהרי\"א הלוי עפשטיין מהאמיל תלמיד רבינו הזקן) חלק ב ס\"ב (ל, ב). הועתק בהערת כ\"ק אדמו\"ר בספר המאמרים תש\"א ע' 116."],["1779","39","הובא בספר שני המאורות (למהרי\"א הלוי עפשטיין מהאמיל תלמיד רבינו הזקן) חלק ב ס\"ב (ל, ב). הועתק בהערת כ\"ק אדמו\"ר בספר המאמרים תש\"א ע' 116."],["1781","40","ראה תו\"א תשא פו, ג. לקו\"ת סוכות פ, סע\"ד. סהמ\"צ להצ\"צ קצט, א. סה\"מ תש\"א שם. ועוד."],["1782","41","ראה לקו\"ת בחוקותי מז, ג."],["1783","42","ע\"פ ישעי' כה, ה."],["1784","43","ראה אגה\"ק סו\"ס ז. סה\"מ תרפ\"ח ע' קנד ואילך. ספר השיחות קיץ ה'ש\"ת ע' 22. אגרות­קודש ח\"ג ע' קכט."],["1785","44","שבת קיח, ב."],["1786","45","משלי ו, כג."]]],[4301600466,"וואָס על ידה גייען דורך כל המצות וואָס ער טוט, כמו שמצינו דאחד מהדר במצות תפילין, שבת, פדיון שבוים, לימוד התורה, הכנסת אורחים, היינו שמקיים כל המצות, רק שבמצוה זו הוא מהדר ביותר, וזהו אבוך במה הוה זהיר טפי, אין וואָס פאַר אַ מצוה האָט ער געשיינט מעהר.\nדי סבה פון דקות'דיקן טמטום המוח, איז ווייל עס קרישמעט זיך ניט. אַז מען לייגט זיך שלאָפן ווי אַ איד, ער באחשבונט די ענינים פון טאָג, און מאַכט אָפּ אַ החלטה טובה אַז מאָרגן זאָל זיין אַנדערש, און מען זאָל זיך טאַקע פאַרנעמען מיט עבודה, און פאַר דעם שלאָף טראַכט מען דברי תורה, ביז מען ווערט אַנטשלאָפן, איז אַז מען ווערט אַנטשלאָפן ווי אַ איד, שלאָפט אַ איד, און עס שטייט אויף אַ איד, מיט אַ חיותדיקן מודה אני. אָבער אַז מען פאַלט צו שלאָפן אָן אַ חשבון, שלאָפט מען פּראָסט, און אַ פּראָסטער שלאָף איז פּראָסט, און מען שטייט אויף אַ פאַרשלאָפענער.\nכאן נתבאר בקצרה ענין עמוק בדא\"ח על יסוד מאמר כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בשנת תרס\"ז<sup data-n=\"1787\">46</sup>, בענין אור המשפיע ואור המקבל דישנו אור שכל אשר בו וע\"י מבארים ענין השכלה, וישנו אור שכל שהוא מקבל ביאורי ההשכלה.\nמען דאַרף טאָן אין אַ ענין אַ משך זמן, עס איז ידוע אַז די אַלטע חסידים האָבן מצליח געווען אין דעם וואָס זיי האָבן געטאָן, וויילע זיי האָבן געטאָן אויף אַ ענין אַ משך זמן. מען דאַרף ניט זיין אַ אץ להעשיר<sup data-n=\"1788\">47</sup>, מיט אַמאָל קען מען ניט אַריין כאַפּן, מען דאַרף זיין מסור ונתון ומשועבד בכל לבו ומאודו.\nדער רבי האָט געזאָגט כתית למאור<sup data-n=\"1789\">48</sup>, שע\"י הכתיתה קומט מען צו צו מאור<sup data-n=\"1790\">49</sup>. אָבער מיר דאַרפן אַ יגיעה רבה ועצומה מיט אַ סאך תהלים און טרערן בכדי עס זאָל זיין דער כתית.\nאח\"כ עמד כ\"ק אדמו\"ר שליט\"א על רגליו ואמר להתמימים, יעדער פון די תמימים דאַרף וויסן אַז תומכי תמימים האָט מייסד געווען דער טאַטע, ער איז אַ טאַטע פון אַ סאַך צענדליקער טויזנטער אידן, זאָלן געזונט זיין. אין דער ישיבה תו\"ת איז אויף יעדער טראָט האָט זיך געגאָסן פנימי', און זיי דאַרפן וויסן אַז זייערע חברים יחיו, אין איין אַנדער מדינה שטייען דורך מיט מסירת נפש אַקעגן די וואָס ווילן צוברעכן מערכת אל חי, דאַרפן זיי זיך מתאחד זיין צוזאַמען מיט זיי ווי אחים לדעה, והשם יתברך יאר פניו אלינו בתוך אחינו בני ישראל ד' עליהם יחיו. סלה.",[["1787","46","ספר השיחות תורת שלום שבהערה 36."],["1788","47","לשון הכתוב — משלי כח, כ. וראה סהמ\"צ להצ\"צ קז, ב."],["1789","48","ר\"פ תצוה."],["1790","49","כ\"ה בד\"ה וקבל היהודים תרפ\"ז סט\"ו (סה\"מ תרפ\"ז ע' קכד). נתבאר בד\"ה ואתה תצוה תשמ\"א סעיף ד ואילך (סה\"מ מלוקט ח\"ו ע' קלא ואילך)."]]],[4301600467,"<h3>בס\"ד<sup data-n=\"1791\">1</sup>. </h3>\n<b>יום ה' ז' תמוז ס\"ג<sup data-n=\"1792\">2</sup>.</b>\nהנחה.\nבסעודת שחרית הרבה דיבר אודות הבעש\"ט, וספרתי מאשר ראיתי הסידור שלו<sup data-n=\"1793\">3</sup> אשר כתב בכתי\"ק בכמה מקומות, וא\"ל אשר הבעש\"ט הי' מכנה א\"ע בשם הזה, כאשר ראה מכתב כתי\"ק<sup data-n=\"1794\">4</sup> — הנמצא אצל ר' אלטער זלאטיפּאלסקי<sup data-n=\"1795\">5</sup> אשר כתב להרב בעל התולדות וחותם \"בעש\"ט\" ולכאו' ענין השמות הוא בעצם אינו דבר גבוה כ\"כ.\nדכללו' ענין השם הוא גילוי' ולפ\"ז א\"מ מהו\"ע השם דבעש\"ט, וי\"ל שהוא מדרי' דשמות עצמיים<sup data-n=\"1796\">6</sup>, שהם למעלה ממדרי' הגילויים כידוע. ויש לי סמך ע\"ז מאשר שמע מכ\"ק אביו אדמו\"ר — אאזמו\"ר — זצוקללה\"ה נבג\"מ זי\"ע שהעולם מספרים<sup data-n=\"1797\">7</sup> על כ\"ק אדמו\"ר האמצעי זצוקללה\"ה נבג\"מ זי\"ע שהי' כותב דא\"ח בהשבעת השם, כי ידוע אשר הי' כותב מהר אשר בלתי אפשרי להבין כ\"ז אופן המהירות בשכל אנושי, כשהי' כותב עמוד בעל הרבה שורות קרוב לס', וכשהי' כותב בסופו הי' חציו למעלה עוד לח. ואני איני מאמין בסיפור העולם ואיני חושב כן. כי ודאי אצלי אשר לא ישמש בשמות קדושות. ועוד פעם סיפר בשם כ\"ק אאזמו\"ר בעל צ\"צ זצוקללה\"ה נבג\"מ זי\"ע, שהי' מרגלא בפומי' אז דער רבי — הכוונה על כ\"ק אדמו\"ר הזקן זצוקללה\"ה נבג\"מ זי\"ע ועכ\"י — פלעגט לייבין חסידות, הי' אומר שחסידות למעלה מקבלה, דקבלה הם רק שמות, וחסידות נאמר עלי' נגילה ונשמחה בך. בך היינו עצמות א\"ס ב\"ה, שהוא למעלה משמות עכ\"ל<sup data-n=\"1798\">8</sup>.",[["1791","1","רשימת רבינו בגוכי\"ק."],["1792","2","ראה לעיל ע' 27."],["1793","3","ראה רשימת רבינו משנת תרס\"ו — אודות סידור הבעש\"ט (כפ\"ח גליון 910­906), ושם: \"אני הנני רואה את הסידור הזה ת\"ל פעם שלישי. הראי' הראשונה הית' בשנת תר\"ס, בנסעי חזרה מקעשינוב הייתי באקמינקע וראיתי שם את הסידור אצל הרי\"ל [{6}ר' יצחק ליפסאן]. . (בעל הסידור)\"."],["1794","4","נדפס ב\"התמים\" חוברת א ע' ז [ה, א]. וראה שם ע' ו [ד, ב]; מכתב רבינו אודות המכתב של הבעש\"ט."],["1795","5","במכתב רבינו שבהערה הקודמת: \"בשנת תרי\"ג בערך קנה מכתב זה הגביר הנודע החסיד ר' יהודא ליב זלאטאפאלסקי. . החסיד רי\"ל ז\"ל הורישו לבנו ר' אלטער ז\"ל, והחסיד ר' אלטער נתנו במתנה להוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע\"."],["1796","6","ראה רשימת רבינו משיחת י\"ט תרס\"ד (ספר השיחות תורת שלום ע' 45 ואילך): \"אין פלוג איז שם בעש\"ט היא מדרי' קטנה מאד. . נאר לפי\"ד איז מורה אויף שמות עצמיים. . ע' ברשימותיי דס\"ג ותמצא בענין בעש\"ט ותצרף לכאן ושם מבואר בהרחב יותר\"."],["1797","7","ראה גם רשימת היומן של רבינו י' כסלו תרס\"ז (\"התמים\" חוברת ב ע' עח (פו, ב] ואילך. רשימת חורף תרצ\"ה (\"רשימות\" חוברת קעט ע' 14). ספר השיחות תש\"ב ע' 122."],["1798","8","ראה גם שיחת י\"ט כסלו תרס\"ט (ספר השיחות תורת שלום ע' 256): \"סיפר לו הרש\"ג מה ששמע מר' אברהם'קע מזעמבין ששמע מר' זלמן מקורעניץ שהוא הי' תובע מאדמו\"ר הזקן חסידות על ע\"ח [{6}עץ חיים] (ושמע פעם) ואמר אדמו\"ר הזקן בדביקות, זלמינקע מאנט ביי מיר חסידות אויף ע\"ח, וואס רעדט ע\"ח, השתל', און איך ב\"ה רעד העכער און נאך העכער. . ואמר אדמו\"ר. . אז דער רבי פלעגט וועלן הייבין חסידות פלעגט ער זאגן אז קבלה איז שמות און גילויים און חסידות איז נגילה ונשמחה בך בך אין עצמות\"."]]],[4301600468,"מובן מזה שיש מדרי' שלמעלה משמות, וי\"ל שהוא מדרי' שמות עצמיים, שהוא מדרי' נעלה ביותר, ומה שנק' בעל שם, שהוא בעל השם י\"ל ע\"ד שנת'<sup data-n=\"1799\">9</sup> לפעמים בענין בעל תשובה שהוא מרא ורבון דתשובה, כן הוא אשר חשבתי בזה פעמי' רבות שמה שקרא א\"ע בעש\"ט הוא מדרי' שמות עצמיים כו'.",[["1799","9","בד\"ה זכור תרפ\"א (סה\"מ תרפ\"א ע' קעז): \"ויא דער רבי זאגט (כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע, הכ\"מ, ע' ברשימת רס\"ג, ובמכ') דבעל שם, הוא שהשם שלו\". וראה לעיל ע' 27: \"בשנת תרס\"ג בש\"ק חזון ערב ת\"ב. . שאל ר' יצחק גרשון מהו השם שקורין בעל שם. . והשיב כ\"ק אאמו\"ר נ\"ע הפי' בעל על השם. . מאותו ש\"ק יש אצלי הנחה על ב' ענינים על ענין הנ\"ל ועל ענין בריך שמי'\"."]]],[4301600469,"יאיר נתיב<sup data-n=\"1800\">1</sup>\nלד\"ה איתא במד\"ת,\nורשימת זכרוני זמני החינוך והבר מצוה שלי<sup data-n=\"1801\">2</sup>\nהדרוש הזה כי\"ק הוד כ\"ק אאזמו\"ר הרה\"ק אדמו\"ר מוהרר\"ש זצוקללה\"ה נבג\"מ זי\"ע, אשר כתבו ביחוד בשביל שיחזור אותו הוד כ\"ק אאמו\"ר הרה\"ק ביום הבר מצוה שלו<sup data-n=\"1802\">3</sup>.\nכך הי' דרכו בקדש, אשר כתב דרוש מיוחד בשביל הבר מצוה, וכן עשה לבנו דודי כבוד הרב החסיד ובעל מדות תרומיות המשכיל הנפלא מוהר\"ר זלמן אהרן נ\"ע<sup data-n=\"1803\">4</sup>, וכפי שהגיד לי הוד כ\"ק אאמו\"ר הרה\"ק הוא הדרוש צדקתך כהררי אל כו' אדם ובהמה תושיע שבספר תרל\"ב דף ק\"פ<sup data-n=\"1804\">5</sup>.\nבתחלת חדש תמוז תרנ\"ג למד הוד כ\"ק אאמו\"ר הרה\"ק עמי את הדרוש הזה, ואת הדרוש הוא הי' אומר בן חמש שנים למקרא<sup data-n=\"1805\">6</sup>.\nויצוני לאמר<sup data-n=\"1806\">7</sup> את השני דרושים האלה תהי' בקי בהם, תחזורם<sup data-n=\"1807\">8</sup> בינך לבין עצמך רבות פעמים, נוסף על הדרוש מה רבו מעשיך<sup data-n=\"1808\">9</sup> אשר אתה בקי בו מכבר, ואיש לא ידע מזה. הדרוש איתא במד\"ת תחזור ברבים אי\"ה ביום הבר מצוה שלך למזל טוב, הדרוש הוא הי' אומר תחזור בעת ולפני מי שאגיד לך, והדרוש מה רבו עוד נראה מה יהי' עמו. אבל אתה תחזור אותו בינך לבין עצמך הרבה פעמים.",[["1800","1","נדפס בקונטרס בר מצוה תרנ\"ג (קה\"ת, תש\"ס) ע' טו ואילך — מגוכי\"ק רבינו."],["1801","2","לכמה ענינים הבאים לקמן — ראה לעיל ע' 221 ואילך."],["1802","3","כ\"ף מר­חשון תרל\"ד."],["1803","4","בשנת תרל\"ב. — ראה לקמן ע' 273."],["1804","5","בביכל גוכי\"ק 1106. נדפס לאח\"ז בסה\"מ תרל\"ב ח\"ב ע' תמח ואילך."],["1805","6","נדפס בקונטרס הנ\"ל ע' לד ואילך. הובא ברשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש דשנת תרל\"א (ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז. תשנ\"ז) ע' 43): \"פנחס, מאמר בנו רז\"א\"."],["1806","7","ראה גם שיחת כ' כסלו תרצ\"ד ס\"ו (לקו\"ד ח\"א קד, א ואילך)."],["1807","8","כ\"ה בגוכי\"ק. ואוצ\"ל: תחזרם."],["1808","9","דשנת תרמ\"ד. נדפס בקונטרס בר מצוה הנ\"ל ע' מד ואילך. — מועתק בזה רשימת רבינו ע\"ד המאמר (נדפס בקונטרס הנ\"ל ע' מב):\nמה רבו מעשיך הוי'\nכי\"ק הוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע אשר כתבו בשנת תרמ\"ד.\nקבלתיו במתנה מאת הוד כ\"ק אאמו\"ר הרה\"ק ביום א' קודם הסעודה גדולה שהיתה בחתונת דודתי — אחותו — מ' חי' מושקא תי' עם ב\"ג ר' משה שי' הכהן הארינשטיין<sup data-n=\"e62\">*</sup>, בחדש אלול תרנ\"ב.\nסיבת המתנה הוא, כי לכל עת אמירת חסידות ודיבורי פארבריינגען שהיו בכל משך ימי החתונה, אשר הותחלו בערך כשבוע קודם החתונה, הייתי נוכח כחסיד זקן. ובליל מוש\"ק אשר סיים הדרוש הנודע \"כל הנהנה\"<sup data-n=\"e63\">**</sup> אשר דיבר במוש\"ק — עם הפסקות של אמירת לחיים — עמדתי כל הלילה על רגלי אצל השולחן ושמעתי, אף כי גם לא הבנתי.\nולמחר קודם המנחה קרא אותי, ויתן לי דרוש בתור מתנה, ויאמר לי בזה\"ל: \"דאס איז א חסידות ואס נעמט זעך פון א חסידות'ן קוש (נשיקה), דיא מעשה ועל איך דיר א מאהל דער ציילין, און דעם מאמר ועל איך אי\"ה מיט דיר לערנען אין סליחות צייט\".\nבימי הסליחות למד אתי המאמר כולו שני פעמי', ובעשי\"ת למד אתי מאמר זה שני פעמי', ובין יו\"כ לסוכות למד אתי רק פעם א'. ויצוני ללמוד אותו בעצמי בחגה\"ס ובחוה\"מ.\nבקיץ תרנ\"ו, באחד הטיולים סיפר לי הוד כ\"ק אאמו\"ר הרה\"ק, כי באחד הלילות בחורף תרמ\"ד, ישב ולמד עם הרה\"ג רי\"מ נ\"ע מפאלטוע<sup data-n=\"e64\">*</sup>, ומגורו הי' בב' חדרי' בבית אמו (כי בקיץ העבר עשה תיקון בביתו ולא הי' אפשר לדור שם בחורף ההוא) ואנכי ישנתי בחדר שלמדו. ובלילה כאשר שכבתי במטתי הייתי נאה במאד, וחפץ במאד לנשקני, כתשוקת אב. ומנע א\"ע מזה, ותמורת ענג זה החליפו כי כתב המאמר, והחליט במחשבתו כי כאשר יעזור השי\"ת ואגדל, הנה בהזדמנות ראשונה שאעשה לו קורת רוח בהנהגה של חסידות, א חסידות'ן פי[הרונג] יתן לי הכתב הזה במתנה. ולכן נתן לי בשנת תרנ\"ב המתנה טובה."],["e62","*","ראה אודותם — ספר התולדות אדמו\"ר מהר\"ש ע' 22."],["e63","**","נדפס בסה\"מ תרנ\"ב ע' צא ואילך."],["e64","*","ראה לקמן ע' 276. וש\"נ."]]],[4301600470,"כחמשה ששה ימים חזרתי את השני המאמרים איתא במד\"ת, הוא הי' אומר הנ\"ל, עד אשר הייתי בקי בהם לחזור אותם בעזה\"י בסדר מסודר, ויצוני לחזור אותם לפניו.\nמשנת תרנ\"א בערך ציוה עלי לשאת חגורה לכל הג' תפלות, ובתנאי אשר החגורה מתחת לבגד העליון הנק' סורטוק, ושלא ידע איש שהנני נושא חגורה. ובעצמו נתן לי חבל דק של משי שחור ותכלת שהייתי יכול לחגור בו פעמיים. ואיש לא ידע. וכאשר התחלתי להניח תפילין בגלוי ר\"ח אייר<sup data-n=\"1809\">10</sup> תרנ\"ג —\nהנני אומר בגלוי, כי משנת תרנ\"ב בחדש תמוז ציוה עלי להניח תפילין<sup data-n=\"1810\">11</sup>, ויצוני כי איש לא ידע מזה, גם אמי תי' לא תדע מזה, ואשר אלך להתפלל לביהכ\"נ כנהוג. אמנם קודם הילוכי לבית הכנסת שהיתה בכל יום בשעה קבועה חצי התשיעית, הנה עשרה מינוט על שעה התשיעית הייתי נכנס לחדרו, והי' סוגר את הדלת, והי' נותן לי תפילין, והייתי מניחם.\nכשבועים הנחתי בלא ברכה, ואח\"כ הייתי מניח בברכה. ועד חדש אלול תרנ\"ב הייתי מתפלל בהם ק\"ש (<sup data-n=\"1811\">12</sup>הגם כי בקומי כבר התפללי עד הודו, כי סדרי הי' (עפ\"י פקודתו לעמוד לא יאוחר מרבע השמינית להיות מוכן) לאמר ברכת השחר עד הודו. והתפללתי פעם ב' ק\"ש כל הג' פרשיות ובפרשיות ציצית לאחוז הציצית ולנשקם, ואח\"כ לאמר ג' קאפיטלעך תהלים על הסדר. ובחדרו ציוה עלי לחגור בחגורתי ממעל לבגדי כנהוג. ופעם הדקתי הרצועות של יד ביותר והיו ניכרים רשמי הכריכות על קנה היד, ויצו עלי לחכות עד אשר יעברו הרושמים.\nובתחלת אלול ציוה כי אתפלל כל התפלה בחדרו. והייתי בא לחדרו רבע שעה לפני השמינית. ובביהכ\"נ הייתי אומר פסוד\"ז כעין אמירת מזמורי תהלים, ובק\"ש הייתי אוחז הציצית, ועומד תפלת שמו\"ע למראה עינים, ועפ\"י פקודתו הייתי חוזר משניות בע\"פ.\nכאשר התחלתי להניח תפילין בגלוי נצטויתי לשאת חגורה כנהוג, וזה הי' מתנת כבוד אמי זקנתי הרבנית הצדקנית מרת רבקה זצוקללה\"ה נבג\"מ זי\"ע<sup data-n=\"1812\">13</sup>. ובעת שנתנה לי המתנה אמרה לי: שאל את אביך מה אמר לו אביו בעת שקרא אותו לחדרו קודם הבר מצוה שלו, ואנחנו שנינו נתנו לו מתנה כזו.",[["1809","10","כ\"ה בגוכי\"ק. ואוצ\"ל: בחודש אייר. — ראה לקמן ע' 276 דהתחיל להניח תפילין בגלוי \"ביום ה' בקר [יא אייר]\". וראה שיחה שבהערה 35."],["1810","11","במק\"א מסופר שהתחיל להניח תפילין בלא ברכה ביום ו' עש\"ק י\"א תמוז תרנ\"א, ומיום א' י\"ג תמוז — בברכה (רשימת רבינו בספר השיחות קיץ ה'ש\"ת ע' 152; ספר השיחות ה'שי\"ת ע' 398). וראה רשימות היומן מיום אחש\"פ תש\"ב (\"רשימות\" חוברת קנו ע' 6). אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' קלז)."],["1811","12","בכי\"ק חסר סיום המוסגר."],["1812","13","ראה אודותה — לעיל ע' 26 הערה 31."]]],[4301600471,"יראה גדולה פנימית לפי ערך שנותי הי' לי מפני הוד כ\"ק אאמו\"ר הרה\"ק בעת ההיא, והגם כי הי' מקרבני וכבר נתן לי שני מתנות גדולות, הדרוש ת\"ר נר חנוכה תרמ\"ג<sup data-n=\"1813\">14</sup> (כמבואר בההערה שם<sup data-n=\"1814\">15</sup>) והדרוש מה רבו מעשיך, וגם למד אתי דברי חסידות מלבד שני המאמרים הנ\"ל, בכל זה הייתי זהיר מבלי לכנוס לחדרו בלי הכנה, והייתי מונע את עצמי מלילך לחדרו גם בענין של שליחות, כמו בהובאת הפוסט או טע\"ג. לעתים הייתי מוזג לו בבקר את כוס הספעציעס שהי' שותה (כי הי' זמן של איזה שנים אשר תמורת טיי' היה שותה ספעציעס, מין עשב ירוק) עם חלב בבקר קודם התפלה, וכאשר הייתי יוצא מחדרו אחר הנחת תפילין כנ\"ל, הייתי לוקח הכוס שהי' שותה בו החלב (כי דרכו הי' לשתות ב' או ג' וחצי כוסות חלב) קודם התפלה. והייתי מוצ]יא[ גם הספעציעס. ובאמצע היום לעת סעודת הצהרי' על הרוב הייתי אוכל בעצמי, וכן סעודת הלילה, כי סדר היום שלי לא התאים עם סדר זמני האוכל. ורק בש\"ק בלילה וביום הייתי סועד אתו עמו בבית כ\"ק א\"ז הרבנית הצדקנית נ\"ע.\nזה תודה לאל עליון כשלשים ושבעה שנים מני אז<sup data-n=\"1815\">16</sup>, הנני זוכר כל הענין בצורתו בדמותו כאשר הי' אז כל אורחי ונתיבותי בהנוגע ביחס חרדת היראה ואופן הכבוד פנימי להוד כ\"ק אאמו\"ר הרה\"ק.\nברגע ראשונה אשר כבוד אמי זקנתי נ\"ע נתנה לי המתנה הנ\"ל חפצתי תומ\"י ללכת להוד כ\"ק אאמו\"ר הרה\"ק ולספר לו את כל הדברי' אשר סיפרה לי, אח\"כ התבוננתי כי לא אמהר בזה. והמלמד שלי הי' ר' ניסן נ\"ע<sup data-n=\"1816\">17</sup>, אותו אהבתי במאד, וספרתי לו כי כבוד אמי זקנתי נתנה לי מתנה, חגורת משי (והדברים אשר סיפרה לי לא הגדתי לו, כן על דבר שאמרה לי אשר אשאל מהוד כ\"ק אאמו\"ר הרה\"ק כנ\"ל לא הגדתי לו).\nכשמוע רבי ר\"נ נ\"ע הנ\"ל מהמתנה הנ\"ל, אמר לי כי זוכר הוא הבר מצוה של כבוד דודי הרז\"א נ\"ע שהי' בחדש תמוז בשנת תרל\"ב (כבוד דודי הרז\"א, נולד י\"ט תמוז תרי\"ט<sup data-n=\"1817\">18</sup>), והי' סעודה גדולה בגן אשר אחורי בית הוד כ\"ק אאזמו\"ר הרה\"ק אדמו\"ר מוהרר\"ש נ\"ע, ובאו הרבה אורחים, ובעלי בתים הרבה מהסביבה מוויטעבסק, ארשע, מאהילוב ועוד.\nוזוכר הוא הבר מצוה של הוד כ\"ק",[["1813","14","נדפס בסה\"מ תרמ\"ג ע' לה ואילך."],["1814","15","כנראה הכוונה לרשימת רבינו על המאמר:\n\"ת\"ר נר חנוכה תרמ\"ג.\nהמאמר כתב ידו של ר' שמואל כותב, וההגהות כי\"ק הוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע.\nמאמר זה קבלתיו במתנה חנוכה תרנ\"ג<sup data-n=\"e65\">*</sup> ולמדו עמי שלשה פעמים\"."],["1815","16","ועפ\"ז — כתב רבינו רשימה זו בשנת תר\"צ."],["1816","17","ראה אודותו — ספר השיחות תר\"פ­תרפ\"ז ע' 71. וש\"נ."],["1817","18","כ\"ה גם (שנולד בשנת תרי\"ט) בספר השיחות תרצ\"ו ע' 56. ע' 113. ע' 239. ב\"שלשלת היחס\" ב\"היום יום\" בתחילתו. ספר השיחות תש\"ג ע' 154 הערה 29. סה\"מ תשי\"א ע' 125 הערה 3. וראה אגרות­קודש ח\"ז ע' עב: \"רז\"א. . איז געווען עלטער פון הוד כ\"ק אאמו\"ר הרה\"ק מיט א יאהר און פיר חדשים\".\nבספר התולדות אדמו\"ר מהר\"ש (הנ\"ל) ע' 22, שנולד בשנת תרי\"ח. וב\"רשימת מאמרי דא\"ח\" של אדמו\"ר מהר\"ש דשנת תרל\"א (ספר התולדות שם ע' 34) נרשם: \"פנחס, בר מצוה של בנו רז\"א\". וראה ספר השיחות תש\"ו ע' 14. וש\"נ."],["e65","*","ובספר השיחות תש\"ב ע' 29: \"שבת פרשה לך לך (תרנ\"א). דער פאטער האט מיר פארהערט און האט מיר געשענקט דעם מאמר ת\"ר נר חנוכה, רמ\"ג\"."]]],[4301600472,"אאמו\"ר הרה\"ק שהיתה בחדש מרחשוון תרל\"ד, והסעודה היתה בזאל הגדול, והיו הרבה אורחים, גם מרחוק באו ממאלי ראסיע, והיו גבירים וחסידים.\nחותנו המלמד דרדקי ר' פסח ז\"ל<sup data-n=\"1818\">19</sup> הי' המלמד אשר אצלו למדו כל בני רבינו בקטנותם, היינו לימוד אל\"ף בי\"ת, וגם בני הוד כ\"ק אאזמו\"ר הרה\"ק, היינו כבוד דודי הרז\"א והוד כ\"ק אאמו\"ר הרה\"ק למדו אצל ר' פסח הנ\"ל בקטנותם, היינו הלימוד דאל\"ף בי\"ת. ובשמחת הבר מצוה של הבנים, הגם שכבר למדו אצל מלמדים אחרים, ניתן מתנה להמלמד הראשון לר' פסח הנ\"ל עשרה רוכ\"ס.\nר' פסח הנ\"ל הי' חסיד גדול מחסידי הוד כ\"ק אאזמו\"ר הרה\"ק אדמו\"ר צ\"צ, והי' מקושר אח\"כ להוד כ\"ק אאזמו\"ר הרה\"ק אדמו\"ר מוהרר\"ש.\nבעת אשר הוד כ\"ק אאזמו\"ר הרה\"ק נתן המתנה הנ\"ל לר\"פ הנ\"ל, אמר לו: דאיין תלמיד האב איך גישיינקט א מתנה א גארטיל. אמר לו ר' פסח: אט אזיי ויא דער רבי<sup data-n=\"1819\">20</sup> האט אייך גישיינקט, איך גידיינק (המשיך ר\"פ הנ\"ל את דבריו) דיא חסידות ואס דער רבי האט אייך גיזאגט חגרה בעוז וכו'<sup data-n=\"1820\">21</sup>, און האט מבאר גיוען אז חגורה איז שייך לנוק' וכו'. איז אז עס איז גיקומען בא רז\"א'ס בר מצוה, האב איך גירעכינט אז גיויס ועט איהר עם אייך שיינקען א חגורה, נאר אז איהר האט דאס ניט גיטאן מן הסתם דארף אזיי זאיין, און איך האב גאר נישט גיפרעגט. אבער אז רש\"ב'ן שיינקט איהר, איז דאך א קושיא.\nוענה לו כ\"ק אדמו\"ר (כן סיפר לי המלמד ר\"נ הנ\"ל) פסח, בא אונז פרעגט מען קיין קושיות ניט, און אף אונז פרעגט מען קיין קושיות ניט. אז מיא פארשטייט איז גוט, און אייב ניט, פארשטייט מען ניט.\nהתבין (אמר לי מלמדי הר\"נ ז\"ל), האדמו\"ר זקינך ראה ברוה\"ק ההפרש בין האחים. ועתה, כאשר זקנתך נתנה לך מתנה כזו אל תספר זאת, ולמי נוגע מי נתן לך את זאת.\nהשמועה האמורה, אם כי לא הבנתי עומקה כלל, ובכל זה עשתה עלי רושם עז. והחלטתי אשר בהלכי מביהכ\"נ אחר תפלת ערבית (בימי הספירה הי' הולך לביהכ\"נ להתפלל, כן דודי הרז\"א (בהזמנים שהי' בליובאויטש) הי' הולך לביהכ\"נ), אספר להוד כ\"ק אאמו\"ר הרה\"ק דבר המתנה.\nמאורע הי' ביום ההוא, ומה הי' לא ידעתי, אך זאת כי מחלוקת וכעין קטטה נפלה בין ר' יעקב אליעזר הראש ישיבה<sup data-n=\"1821\">22</sup>, ר' אהרן חוזר<sup data-n=\"1822\">23</sup>, ונפתלי צבי",[["1818","19","ראה אודותו — רשימת היומן של רבינו מיום כ' אייר תרנ\"ו (לקו\"ד ח\"ג תקכח, ב. הוספות לספר השיחות תש\"ו­ה'שי\"ת ע' 422 ואילך). ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 120. ע' 160. קיץ ה'ש\"ת ע' 69."],["1819","20","אדמו\"ר הצמח צדק."],["1820","21","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 114. ובספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז. תשנ\"ז) ע' 12: \"בלילה קודם הבר מצוה [מספר אדמו\"ר אדמו\"ר מהר\"ש] ישנתי כשתי שעות בחדר כ\"ק אאמו\"ר, ואז אירע מה שסיפרתי לך, גם הלבשת החגורה קודם התפלה ואמר חגרה בעוז מתני', מאמר קצר בענין חגור חרבך על ירך גבור\". — ראה ד\"ה חגור חרבך על ירך גבור באוה\"ת לתהלים (יהל אור) ע' קעא ואילך. סה\"מ תרל\"ג ח\"ב ע' תד ואילך."],["1821","22","אולי הוא הנזכר בשיחת חה\"פ תרצ\"ד ס\"א (לקו\"ד ח\"א קיג, ב)."],["1822","23","ראה אודותו — ספר השיחות תר\"פ­תרפ\"ז ע' 17. תש\"ה ס\"ע 19 ואילך. וראה רשימת רבינו בלקו\"ד ח\"ג תקכט, ב ואילך (נדפס בהוספות לספר השיחות תש\"ו­ה'שי\"ת ע' 424 ואילך). לעיל ע' 96. אגרות­קודש ח\"ג ע' שצג. תיב. ח\"ד קפא. ח\"ו ע' רסט."]]],[4301600473,"מייטין מעבר מזה, ור' דובער קאצינעלינבייגין<sup data-n=\"1823\">24</sup>, ור' אהרן ביינש הסטארעסטע ושלום יחזקאל פורש<sup data-n=\"1824\">25</sup> מעבר מזה. ושמשון העב (שמשון דער גראבער) ור' דוב ב\"ר דוד<sup data-n=\"1825\">26</sup> צערקעס ור' דוד המ\"ץ<sup data-n=\"1826\">27</sup> היו הדיינים. וכאשר הבעלי דין לא קבלו פסק הב\"ד הנ\"ל, הנה כולם באו (ואתם עמהם קהל רב) לביהכ\"נ שלנו. וקודם תפלת ערבי' ואחרי' היו מריבים ביניהם, וההחלט הי' כי רק האחים יגידו דעתם בזה, וכאשר יפסקו כן יהי'. וזה הפריע את מחשבתי בסיפור הדברי' הנ\"ל.\nבבקר עמדתי שעה אחת קודם הרגיל, וכיונתי את הזמן אשר הוד כ\"ק גמר קריאת שמע שחרית ופתח את דלת חדרו לאמר איזה דבר להמשרת ר' מענדיל<sup data-n=\"1827\">28</sup>, וכאשר ראה אותי שאלני מה אני עושה פה. ואזרתי כח ואמרתי לו כי יש לי סוד לגלות לו. ונכנסתי לחדרו והראיתי לו המתנה, ואמרתי לו את אשר הגידה לי כבוד א\"ז, כי קודם הבר מצוה שלו נכנסה לחדר הוד כ\"ק אאזמו\"ר הרה\"ק ותאמר לו, כי כבוד חותנתה הרבנית חי' מושקא נ\"ע סיפרה לה, אשר בהגיע עונת הבר מצוה של הוד כ\"ק אאזמו\"ר הרה\"ק, אמר לה אישה הוד כ\"ק אאזמו\"ר אדמו\"ר צ\"צ, בדעתי לתת לבנינו זה מתנה כאותה המתנה אשר נתן לי כאאזמו\"ר נ\"ע (הכוונה על רבינו הגדול אדמו\"ר הזקן), והסכימה על זה. וכאשר ספרתי לזקינך מה שסיפרה לי חותנתי צחק ואמר, טוב, צריכים לעשות כן.\nכאשר גמרתי לספר את זאת נשתנה הוד כ\"ק אאמו\"ר הרה\"ק בפניו הקדושים ויבט אלי ויתבונן בי, והכיר בי כי עוד לא גמרתי את הסיפור כולו, ויאמר לי: ומה אמרה לך עוד? אמרתי, כי אחרי אשר נתנה לי המתנה אמרה לי: ושאל את אביך מה אמר לו זקינך.\nכאשר הגדתי לו הדברים האלו, התלהבו פניו הקדושים וכשתי אגלי טל ירדו מעיניו הקדושים. ולקח את החגורה ויחגור אותי בו, ויאמר לי<sup data-n=\"1828\">29</sup>: כתיב חגרה בעוז מתני' וכו', וכתיב חגור כו', זאלסט זאיין א גבור, דער רבי האט גיגעבין דעם זיידין א גארטיל גשמי, וזה הספיק, דער זיידע האט גיגעבין דעם טאטין א זיידענעם גארטיל והספיק, דער טאטע האט מיר גיגעבין א גארטיל האט ער גידארפט זאיין שטארק ויא א רימען (עור). בתורתו של ר' מאיר כתיב כתנות עור<sup data-n=\"1829\">30</sup> באלף<sup data-n=\"1830\">31</sup>. אז מיא האט א רימענער גארטיל, ניט נתפעל וערין פון קיין זאך און דינען השי\"ת באהוי\"ר כפשוטו, יעמולט קאן מען בעזה\"י מאכין",[["1823","24","נזכר בספר השיחות תש\"ד ע' 27. תש\"ח ע' 172."],["1824","25","תיבה זו אינה ברור בצילום הכי\"ק שתח\"י."],["1825","26","בן החסיד ר' אברהם קרולער (מחסידי אדמו\"ר הזקן) — ראה אגרות­קודש ח\"ג ע' שדמ. ע' תקסח. וראה \"התמים\" חוברת א ע' עו [לט, ב]."],["1826","27","הר\"ר דוד יעקבסאן. ראה ספר השיחות תר\"פ­תרפ\"ז ע' 253. וש\"נ."],["1827","28","ר' מנחם מענדל קאנטאר. ראה אודותו ספר השיחות תש\"ז ע' 142. וש\"נ."],["1828","29","ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת שם."],["1829","30","בראשית ג, כא."],["1830","31","ב\"ר פ\"כ, יב. וראה אור תורה להה\"מ ס\"פ בראשית. מאמרי אדה\"ז פרשיות ח\"א ע' מה. ע' נ. שער היחוד לאדמו\"ר האמצעי פמ\"ה ואילך (קמ, א ואילך). סהמ\"צ להצ\"צ ח, סע\"א. ועוד."]]],[4301600474,"פון דעם עו\"ר א או\"ר. און דאיין גארטיל דארף זאיין שטארק ויא א אייזין (ברזל), דער אייבערשטער זאל דיר שטארקין דיא הארץ זאלסט זאיין א ירא שמים, א חסיד און א למדן, וחזקת והיית לאיש<sup data-n=\"1831\">32</sup>. וינשק אותי במצחי.\nכל זה הי' בהב' ימים, יום ג' ויום ד'<sup data-n=\"1832\">33</sup>. יום ג' קבלתי המתנה ויום ד' בקר הייתי אצל הוד כ\"ק אאמו\"ר הרה\"ק כמסופר לעיל. וביום ה' בקר<sup data-n=\"1833\">34</sup> היתה ההתחלה הגלוי'<sup data-n=\"1834\">35</sup>, ובו ביום אחר התפלה היתה סעודה קטנה בבית הוד כ\"ק אאמו\"ר הרה\"ק, ואמר הדרוש וחזקת והיית לאיש<sup data-n=\"1835\">36</sup>, ביאור הד' ענינים אדם איש אנוש גבר<sup data-n=\"1836\">37</sup>.\nכאמור, בתחלת חדש תמוז למד הוד כ\"ק אאמו\"ר הרה\"ק אתי המאמרי' אי' במד\"ת, הוא הי' אומר, וביום א' י\"א תמוז אחר תפלת הבקר קרא אותי לחדרו, ויצוני לחזור לפניו ב' המאמרים הנ\"ל, ויצוני לחזור בו ביום השני סדרים משניות זרעים מועד שהייתי בקי בהם היטיב. סדר זרעים הייתי חוזר במשך של ס\"ה­ע' מינוט כל הסדר<sup data-n=\"1837\">38</sup>, וסדר מועד במשך שעה וחצי בערך. וקודם המנחה קרא אותי ויצוני להגיד לפניו המאמר מה רבו מעשיך הוי', ואח\"כ ציוני כי תומ\"י אחר מעריב אלך לישן, ולעמוד ביום המחרת השכם בקר.\nביום ב' פ' בלק י\"ב תמוז עמדתי בשעה הששית בקר, ובשעה חצי השביעית לקחני ללכת לבית הטבילה, ובשעה השביעית בערך נסע ויקח גם אותי עמו להשתטח על ציוני אהלי הוד כ\"ק אאזמו\"ר הרה\"ק אדמו\"ר צ\"צ ואדמו\"ר מוהרר\"ש. כאשר נכנס למקום הציונים בירך ואמר איזה קאפיטלעך תהלים, ויקרא אותי ויעמידני בין ב' הקברים, ויאמר: היום בני, נכדך, ובן נכדכם, יוסף יצחק בן שטערנא שרה נעשה בר מצוה, עוררו רחמים בעד כולנו ובעדו. וקרא הפ\"נ הכתוב, ויאמר לי לחזור המאמר הוא הי' אומר, והוא עמד והקשיב לכל אשר דברתי. ובגמרי לחזור את המאמר אמר בזה\"ל: אנא אאמו\"ר ואנא אאזמו\"ר, ברכו את בני שיהי' ירא שמים חסיד ולמדן, יהי' בריא ומצליח בעבודת השי\"ת. ויבט אלי, והבנתי מהבטתו כי גם אני צריך לבקש ברכה, ואמרתי: הייליקע זיידעס בענטשט מיך. ואח\"כ רמז לי לצאת, ויצאתי, והוא נשאר שם עוד כחצי שעה.\nבשעה כחצי העשירית באנו חזרה, ובשעה העשירית היתה התחלת התפלה. ובאו הרבה אורחים, גם מהמפורסמים, רד\"ץ מטשערניגוב<sup data-n=\"1838\">39</sup>, רד\"ז מיעקאטערי­נאסלאוו<sup data-n=\"1839\">40</sup>, רי\"מ מפאלטאווע<sup data-n=\"1840\">41</sup>, ר' אשר מניקאל'<sup data-n=\"1841\">42</sup> [.. ] מקרעמענטשוג, כי זמן הב\"מ, היינו שנת תרנ\"ג, היתה עיקר",[["1831","32","מלכים­א ב, ב. וראה לקו\"ש חט\"ו ע' 289 ואילך. ד\"ה וחזקת והיית לאיש תשכ\"ח (סה\"מ מלוקט ח\"ג ע' רכא ואילך)."],["1832","33","ט­י אייר."],["1833","34","יא אייר."],["1834","35","ראה גם שיחת כ' כסלו תרצ\"ד ס\"ח (לקו\"ד ח\"א קז, ב). אגרות­קודש ח\"י ע' קלו. וראה לעיל הערה 10."],["1835","36","ראה שיחת כ' כסלו שם. \"מפתח מאמרי ודרושי אדמו\"ר מהורש\"ב\" ע' סג."],["1836","37","תוכן המאמר הועתק בשיחת כ' כסלו שם."],["1837","38","ראה גם רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 248."],["1838","39","הרה\"ח ר' חיים דוד צבי בן הרה\"ח ר' פרץ חן. ראה אודותו — לעיל ע' 223. וש\"נ."],["1839","40","הרה\"ח ר' דוב זאב קאזעווניקאוו. ראה אודותו — ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 231 ואילך (וש\"נ). ע' 349."],["1840","41","הרה\"ח ר' יעקב מרדכי בעזפאלאוו. ראה אודותו — לעיל ע' 92 הערה 30. וש\"נ."],["1841","42","הר\"ר אשר ב\"ר מאיר גראסמאן שו\"ב מניקוליעב. ראה אודותו — ספר השיחות קיץ ה'ש\"ת ע' 28. ספר השיחות תש\"ו ע' 45. וש\"נ."]]],[4301600475,"התחלת נשיאותו של הוד כ\"ק אאמו\"ר הרה\"ק<sup data-n=\"1842\">43</sup>. ובשעה כחצי הי\"ב גמרו התפלה, וכל האורחים הלכו לבית הוד כ\"ק אאמו\"ר הרה\"ק וישבו מסביב להשולחנות, וחזרתי המאמר אי' במד\"ת.\nהוד כ\"ק אאמו\"ר הרה\"ק אמר הדרוש תפילין דמארי עלמא<sup data-n=\"1843\">44</sup>, דיבר בערך שעה וחצי, ושתו הרבה משקה. וברבות האורחים נעשה דוחק גדול בבית, וערכו את השולחנות בהגן. וכאשר נכנסו לגן זה הי' בערך שעה השלישית, אמר הוד כ\"ק אאמו\"ר הרה\"ק מאמר אנת הוא דאפיקת עשר תיקונין (המשך)<sup data-n=\"1844\">45</sup>, בעת הסעודה בשעה הששית בערך אמר מאמר וקשרתם וכו' והיו לטוטפת (המשך)<sup data-n=\"1844\">45</sup>. אח\"כ התפללו מנחה מעריב.\nולמחר ביום ג'<sup data-n=\"1846\">46</sup> עשתה כבוד אמי זקנתי הרבנית הצדקנית סעודה גדולה, ערוכה בגן מפני גודל החום. בשעה הרביעית בערך אמר מאמר בן פורת יוסף (המשך)<sup data-n=\"1844\">45</sup>, ואז אמר כי הוד כ\"ק אאזמו\"ר הרה\"ק אמר כי על כל שמחה מבניו הגיד מאמר בן פורת, ואמר על עצמו שהוא במדרי' יוסף, וסיים הוד כ\"ק אאמו\"ר והבטחתו נאמנה עד ביאת גואל צדק.\nביום הרביעי<sup data-n=\"1848\">47</sup> קרא אותי הוד כ\"ק אאמו\"ר הרה\"ק ויצוני לאמר, בהיות כי כעת נמצאים הרבה מזקני אנ\"ש, הנה חופש יותן לי מלימוד עד אחר הש\"ק, ואשר אשתדל להיות אצלם בהיותם יושבים יחד לשוחח, ולהזהר מלדבר ורק לשמוע. ואם יבקשו אותי לחזור עוד הפעם את המאמר איתא במד\"ת אחזור, וגם מותר לי לחזור המאמר הוא הי' אומר גם אם לא יבקשו אותי. אבל מהמאמר מה רבו לא ידע איש, ואשר גם",[["1842","43","ראה שיחת שמע\"צ ושמח\"ת תרצ\"ה ס\"ב (לקו\"ד ח\"א קעט, סע\"א ואילך)."],["1843","44","נדפס קונטרס בפ\"ע (קה\"ת, תשכ\"ח). ולאח\"ז — בסה\"מ תרנ\"ג ע' רלג ואילך.\nברשימת רבינו (נדפסה ב\"מפתח מאמרי ודרושי אדמו\"ר מהורש\"ב\" ע' סד): \"דעם מאמר האט דער טאטע געזאגט מיט הפסקות במשך פון דער גאנצער וואך — מיט א אנהויב פון א פסוק אדער מאמר חז\"ל און א סיום אויף דעם אנהויב. אין כתב זיינען די התחלות מיט די סיומים ניט פאראן, עס איז מער ניט וואס עס זיינען דא די הפסק­ענינים, וואס יעדער הפסק איז געווען, אין אמירה, א מאמר בפני עצמו. דער מאמר תפלין דמארי עלמא ווי ער איז אין כתב איז א קיצור פון דעם ווי ער איז געווען בדיבור.\nדי הפסקות אין דעם מאמר תפלין דמארי עלמא, וואס יעדער הפסק איז געווען א מאמר:\nא) תפלין דמארי עלמא. ב) ואתה מרבבות קודש. מתחיל בכי\"ק בעמוד ג': והנה כעין ההפרש בין אותיות החקיקה לאותיות הכתיבה. ג) אנת הוא דאפיקת עשר תיקונין. מתחיל בעמוד ה: ושרש הענין מה שהע\"ס נק' תיקונין. ד) הנחמדים מזהב ומפז רב. מתחיל בעמוד ו': אך הענין הוא דבאמת. ה) לעולם יהא אדם רך כקנה. מתחיל בעמוד ז': ומעתה יובן בבחינת התיקון. ו) בן פורת יוסף. מתחיל בעמוד ט': והנמשל מכל זה יובן למעלה בעולם התיקון. ז) והיו לטוטפות בין עיניך. מתחיל בעמוד יו\"ד: וע\"פ כל הנ\"ל יובן מה שהתפלין נקראים טוטפות. ח) מגיד דבריו ליעקב, מה שהוא עושה מצוה לישראל לעשות. מתחיל בעמוד י\"א: ועוד י\"ל מה שהתפלין נק' טוטפות. ט) תפלין דמארי עלמא. מתחיל בעמוד י\"ב: ומעתה צ\"ל מארז\"ל תפלין. י) כי נר מצוה ותורה אור ודרך חיים תוכחת מוסר. מתחיל בעמוד י\"ד. יא) כל המניח תפלין מאריך ימים. מתחיל בעמוד ט\"ו. יב) וחזקת והיית לאיש. מתחיל בעמוד ט\"ז: והנה בשל\"ה פ' ויחי.\nדעם מאמר וחזקת והיית לאיש האט דער טאטע געזאגט דעם זיבעטען טאג פון די שבעת ימי המשתה — יום ב' י\"ט תמוז. — ווייל יום א' איז געווען דער תענית (נדחה), האט מען דערום מוסיף געווען דעם יום ב' י\"ט תמוז\"."],["1844","45","ראה רשימת רבינו שבהערה הקודמת."],["1844","45","ראה רשימת רבינו שבהערה הקודמת."],["1846","46","יג תמוז."],["1844","45","ראה רשימת רבינו שבהערה הקודמת."],["1848","47","יד תמוז."]]],[4301600476,"לא אדבר מהמבואר שם אפילו לא בהתחלת התחל' הדרוש.\nובמשך הג' ימים ד, ה, ו<sup data-n=\"1849\">48</sup> בקרתי את כל האורחים הגדולים על האכסניאות שלהם, ובו ביום, היינו ביום ד', חזרתי עוד הפעם המאמר אי' במד\"ת. ביום ה' אחר התפלה בביהכ\"נ אמרתי למלמדי ר\"נ נ\"ע כי יכול הנני לחזור עוד מאמר של חסידות, וגם ר' אשר שו\"ב מניקאלאייעוו נ\"ע שמע את אשר אמרתי למלמדי ר\"נ הנ\"ל, ובו ביום בהיותי אצל ר' אבא נ\"ע פערסאן<sup data-n=\"1850\">49</sup>, והוא בחן אותי במשניות (כי הוא הי' בקי בששה סדרי משנה באורח נפלא, והי' חוזר בע\"פ עם כל הנוסחאות והגירסאות שונות)<sup data-n=\"1837\">38</sup>, ונכנס ר' אשר שו\"ב ואמר כי החסיד הגביר ר' ישעי' ז\"ל ברלין<sup data-n=\"1852\">50</sup> קרא את כל האורחים להאכסניא שלו אייף א גלעזיל אַריק על שעה 4 (זה הי' בערך שעה חצי הרביעית), והוא רא\"ש הנ\"ל לקח על עצמו חלק מהשמשות לאסוף את הקרואים וכמה כבר הלכו, וגם ר' מנחם מאניש ז\"ל מאנעסזאהן<sup data-n=\"1853\">51</sup> כבר הלך, ע\"כ בא לקרוא את הר' אבא נ\"ע, וגם אותי קרא.\nובבואינו לשם הושיבוני בראש השולחן בין הרה\"ג רש\"ז ניימארק נ\"ע<sup data-n=\"1854\">52</sup> מנעויל ובין הרה\"ח רד\"ץ נ\"ע, והתחילו לנגן, ושתו משקה. ובתוך כך התחיל רא\"ש הנ\"ל לאמר לי: שמעתי כי אמרת למלמדך ר' ניסן שאתה יודע מאמר של חסידות מלבד המאמר איתא במד\"ת, חזור המאמר שאתה יודע. ואמר הרה\"ג רש\"ז ניימארק: יע, ער האט גיהערט דעם מאמר \"כל הנהנה\"<sup data-n=\"1855\">53</sup> א גאנצע נאכט<sup data-n=\"1856\">54</sup> (כוונתו על אודות המבואר בהרושם שבמאמר מה רבו<sup data-n=\"1857\">55</sup>), אבער אז ער קאן חזרין חסידות דארפמען הערין. ועוד כמה הביעו חפצם זה שאחזור מאמר חסידות, ור' צבי הענדיל נ\"ע הסיר חגורתו ונתנה לי, ואחגור, ואתחיל המאמר הוא הי' אומר, וחזרתי בסגנון טוב ושלא במהירות.\nוהמחזה ההיא לא אשכח, קיבוץ אנשים כאלו, והחוש של ביטול פנימי אל השרש, נראה אז. המאמר שהה לדברו יותר על שעה. הרה\"ג רש\"ז ניימארק, הרה\"ג רד\"ץ, הרה\"ג רד\"ז, נזכרו על ששמעו מאמר זה מאת הוד כ\"ק אאזמו\"ר הרה\"ק והתפעלו במאד. ואח\"כ כולם שאלו מדוע לא חזרתי מאמר זה ברבים, ועניתי כי לא אדע, הוד כ\"ק אאמו\"ר הרה\"ק למדני שני מאמרים אלו, ויצוני לחזור המאמר איתא. וישאלוני: אפשר אתה יודע עוד מה? וכפסע הי' כי",[["1849","48","יד­טז תמוז."],["1850","49","ראה אודותו \"התמים\" חוברת ו ע' ח [רעא, ב] ואילך. ספר השיחות קיץ ה'ש\"ת ע' 32. ע' 42. ספר השיחות שבהערה 38. ועוד."],["1837","38","ראה גם רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 248."],["1852","50","מריגא. חתן אחות כ\"ק אדמו\"ר מהר\"ש (הרבנית ראדע פריידע). נפטר בקיץ תרס\"ח. ראה אודותו: אגרות­קודש אדמו\"ר מהורש\"ב ח\"ב ע' תשא­תשב (ובהנסמן במפתח שמות אנשים לאגרות­קודש שם ח\"ה). ספר השיחות תש\"ה ע' 28 ואילך. ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז. תשנ\"ז) ע' 76 ואילך."],["1853","51","ראה אודותו אגרות­קודש ח\"ד ע' קפ. לעיל ע' 235. ספר השיחות קיץ ה'ש\"ת ע' 17. תש\"ה ע' 30 ואילך. ספר התולדות אדמו\"ר מהר\"ש ע' 17. ע' 77."],["1854","52","הגה\"ח ר' חיים משולם זלמן ניימארק מ\"ץ סטרדוב, וויטעבסק ונעוויל. ראה אודותו לעיל ע' 238. וש\"נ."],["1855","53","נדפס בסה\"מ תרנ\"ב ע' צא ואילך."],["1856","54","ראה רשימת המאסר (ספר השיחות תר\"פ­תרפ\"ז ע' 227): \"נזכרתי בהיותי ילד בן י\"ב שנה — תחלת שנת השלש עשרה, אלול תרנ\"ב — חתונת דודתי. . ו[במוצאי ש\"ק] בחצי שעה השתים עשרה התחיל הוד כ\"ק אאמו\"ר הרה\"ק לאמר הדרוש כל הנהנה\"."],["1857","55","הועתק לעיל בהערה 9.\n<hr>"]]],[4301600477,"אגלה גם אודות המאמר מה רבו, אבל עצרתי כח ולא הגדתי מאומה. ואח\"כ ישבתי ושמעתי מה ששוחחו ביניהם בעניני חסידות וסיפורים.\nבש\"ק בקר קרא אותי הוד כ\"ק אאמו\"ר הרה\"ק לחדרו ויצוני לחזור המאמר מה רבו, וחזרתיו בדיוק ובמתינות. וא\"ל כי מעתה נהיית לאיש, והתחזק ללמוד היטיב ולהתפלל בדיוק, והשי\"ת יחוננך דעת ותהי' י\"ש חסיד ולמדן כפי רצון אבותינו רבותינו הקדושים זצוקללה\"ה נבג\"מ זי\"ע.\nבש\"ק אחר מנחה קרא אותי הוד כ\"ק אאמו\"ר הרה\"ק לחדרו, ועמד מכסאו והלך אל האלמער שבו היו הכתבים, ולקח את המאמר איתא במד\"ת כי\"ק הוד כ\"ק אאזמו\"ר הרה\"ק הזה וא\"ל הנני נותן לך במתנה גמורה, ואותן הברכות אשר בירכוני כאאזמו\"ר וכאאמו\"ר יחולו גם עליך. ויתן לך האלקים חכמה בינה ודעת לעבדו ית' בתורה תפלה במצות ובמדות טובות בלבב שלם.\n<hr>"],[4301620154,"<h3>דף השער</h3>\nקובץ\nשלשלת האור\nהיכל שער\nשמיני שלישי\nספר השיחות\nתש\"ו­ה'שי\"ת\nמכבוד קדושת\nאדמו\"ר יוסף יצחק\nזצוקללה\"ה נבג\"מ זי\"ע\nשניאורסאהן\nמליובאַוויטש\nיוצא לאור על ידי מערכת\n\"אוצר החסידים\"\n770 איסטערן פּאַרקוויי ברוקלין, נ.י.\nשנת חמשת אלפים שבע מאות ששים ואחת לבריאה"],[4301620155,"<h3>פתח דבר</h3>\nלקראת ט' אדר הבע\"ל — היום שבו הועבר המרכז של חסידות חב\"ד לחצי כדור התחתון, בבוא כ\"ק אדמו\"ר מהוריי\"צ נ\"ע לארצות­הברית באופן של קביעות (בשנת ה'ש\"ת)<sup data-n=\"1\">1</sup> —\nמדפיסים אנו בזה<sup data-n=\"2\">2</sup>, את \"ספר השיחות תש\"ו — ה'שי\"ת\" לכ\"ק אדמו\"ר מהוריי\"צ נ\"ע, הכולל שיחות שאמר ורשימות שכתב באותן שנים<sup data-n=\"3\">3</sup>, שהן סיום התקופה השלישית<sup data-n=\"4\">4</sup> של שנות נשיאותו<sup data-n=\"5\">5</sup>.\nוזאת למודעי: חלק חשוב מהשיחות שבספר זה לא הוגה ע\"י כ\"ק אדמו\"ר מהוריי\"צ, ולכן א\"א לדעת עד היכן מדוייקים הדברים בכל פרטיהם, אבל בנוגע לכללות השיחות, אולי אפשר לומר ע\"ד מ\"ש כ\"ק אדמו\"ר (בהקדמה לספר השיחות תורת שלום), אשר \"בשים לב לזה, אשר כותבי הרשימות כולם, היו חסידים ותיקים אשר כל דבור והגה של רבם קדוש הי' להם, אין כל ספק, אשר השתדלו ככל יכולתם לשמור על לשון הרב שלא להוסיף עליו ולא לגרוע ממנו\".\nולענין סגנון השיחות, כותב במקום אחר<sup data-n=\"6\">6</sup>: \"אף שהשיחות (הנדפסות), ברובם המכריע, מובנות אף לאלו שלא עסקו בתורת חסידות חב\"ד, בכל זה יש",[["1","1","ראה ספר השיחות תש\"נ ח\"א ע' 326 ואילך. ובכ\"מ."],["2","2","בהמשך לספרי השיחות: תר\"פ­תרפ\"ז (קה\"ת, תשנ\"ב). תרפ\"ח­תרצ\"א (קה\"ת, תשנ\"ה). תרצ\"ו=חורף ה'ש\"ת (קה\"ת, תשמ\"ט). קיץ ה'ש\"ת (קה\"ת, תש\"ז). תש\"א (קה\"ת, תשכ\"ד). תש\"ב (קה\"ת, תשכ\"ד). תש\"ג (קה\"ת, תשכ\"ה). תש\"ד (קה\"ת, תשכ\"ז). תש\"ה (קה\"ת, תשכ\"ז)."],["3","3","תודתינו נתונה להרה\"ת ר' שמעון אהרן הכהן שי' ראזענפעלד שמסר לידינו כמה שיחות ורשימות מעזבון זקנו הרה\"ח הרה\"ת ר' אליהו ייאכיל ע\"ה סימפסאן. ולמשפחת וויינגארטען שי' שמסרו לידינו כמה מרשימות אביהם הרה\"ת ר' אברהם ע\"ה וויינגארטען.\nובזה הננו פונים בבקשה נמרצה לכל מי שיש תח\"י מאמרים, שיחות ורשימות מכ\"ק אדמו\"ר מהוריי\"צ נ\"ע שעדיין לא נדפסו, שיואיל נא להמציאם לנו ע\"מ שנוכל להדפיסם, ויהי' בזה ממזכי הרבים."],["4","4","תקופת נשיאותו של רבינו (תר\"פ — תש\"י) נחלקת בד\"כ לשלש: (א) תקופת רוסיא (תר\"פ — ראשית שנת תרפ\"ח). (ב) תקופת ריגא ופולין (תרפ\"ח — ת\"ש). (ג) תקופת ארה\"ב (ת\"ש — תש\"י) — ראה לקו\"ש חי\"ח ע' 303 ואילך. חל\"ג ע' 168."],["5","5","להעיר ממכתב ה' חשון תשי\"א (אגרות­-קודש ח\"ד ע' כד): \"והלואי היו מדקדקים אנ\"ש, ובפרט התמימים, בדברי כ\"ק מו\"ח אדמו\"ר הכ\"מ אפילו בשיחותיו ובפרט אלו משנת השי\"ת והשנה שקדמה לה\"."],["6","6","מכתב אייר תש\"ד (אגרות­-קודש חלק א ע' רפז. ועד\"ז שם ע' רעט)."]]],[4301620156,"בהם כמה ענינים, ובפרט מאלו שלא בא בשיחה אלא דרך אגב, אשר אי אפשר להבינם, כי אם אחרי הקדמת לימוד תורת החסידות, או, עכ\"פ, ידיעת יסודי שיטה זו. ובמאמרי דא\"ח או בשיחה אחרת מתבאר בודאי ענין זה כדי צרכו, כי דברי<sup data-n=\"7\">7</sup> תורה עניים במקום אחד ועשירים במקום אחר\".\n* * *\nלתועלת הלומדים והמעיינים ניתוספו הערות בשולי הגליון<sup data-n=\"8\">8</sup> ובהן: א) מראי מקומות לפסוקים ומרז\"ל וכו'. ב) ציונים לשיחות וכתבי כ\"ק אדמו\"ר מהוריי\"צ שבהם הובא אותו ענין. ג) מראי מקומות למקומות אחרים שבהם נתבאר הענין בפרטיות יותר. ד) רשמים ביוגרפיים על אישים המוזכרים בשיחות.\nבסוף הספר — מפתח שמות, מקומות, מוסדות וארגונים<sup data-n=\"9\">9</sup>.\nכל הנ\"ל נערך ע\"י הרה\"ת ר' אהרן לייב (ברש\"ב) שי' ראסקין.\nמערכת \"אוצר החסידים\"\nכ\"ב שבט, ה'תשס\"א\nיום ההילולא הי\"ג של הרבנית הצדקנית\nמרת חי' מושקא נ\"ע ז\"ל\nברוקלין, נ.י.\n<hr>\n<b>הערה כללית:</b>\nבכל מקום שצויין בהערות לאגרות­-קודש (סתם), הכוונה לסדרת אגרות-קודש כ\"ק אדמו\"ר מהוריי\"צ.",[["7","7","ברייתא דל\"ב מדות מדה ט\"ו. ועי' ג\"כ ירושלמי ר\"ה פ\"ג סוף ה\"ה."],["8","8","ראה שיחת ש\"פ חו\"ב, י\"ב תמוז תשמ\"ט (חלקה הועתק בספר השיחות תשמ\"ט חלק ב ע' 572 ובהערה 92):. .. ישנו ענין עיקרי שעדיין לא נזכר — להוסיף בלימוד תורתו של בעל הגאולה, מאמריו ושיחותיו, ובפרט אלה שיצאו­לאור לאחרונה — כולל ובמיוחד הספר שהגיע מבית הדפוס (בהשגחה פרטית) לכבוד חג הגאולה — ספר השיחות תרצ\"ו­חורף ה'ש\"ת, שניתוספו בהם שיחות שלא נתפרסמו עד עתה, וגם בהשיחות שנתפרסמו כבר, ניתוספו מראי מקומות וציונים כו' ונעשה דבר השלם — והגיע לכאן באופן שאפשר ללמוד בתוכו בשבת זה, י\"ב תמוז.\nובטבע האדם — הרי ספר חדש מעורר חיות חדשה בלימוד תורתו. . ויהי רצון שזה יזרז עוד יותר הגאולה, ו\"הקיצו ורננו שוכני עפר\", ונשיא דורינו בראשם, ביחד עם דוד מלכא משיחא, ובאופן ד\"מראה באצבעו ואומר זה\". . וימשיכו ההתוועדות דחג הגאולה. . ביחד עם בעל הגאולה, נשמה בגוף, וביחד עם משיח צדקנו, בארצנו הקדושה, בירושלים עיר הקודש ובבית המקדש."],["9","9","נערך ע\"י התמים צבי אפרים שי' בראנשטיין."]]],[4301620157,"<h3>י\"ב תשרי תש\"ו</h3>\n<h4>להבחורים קודם נסיעתם לשיקאַגאָ<sup data-n=\"10\">1</sup></h4>\nאיר פאָרט אין שיקאַגאָ, איר דאַרפט זיין איבערגעגעבן צום לערנען. דער אויבערשטער זאָל העלפן איר זאָלט מצליח זיין אין לערנען, אין יר\"ש, און אין מדות בני אדם טובים.\nפאָרט געזונט און זייט געזונט בגשמיות וברוחניות.",[["10","1","בקובץ ליובאַוויטש שנה שני' חוברת ד ע' 87: \"בין כסא לעשור<sup data-n=\"e3\">*</sup> ה. י. זיינען געפאָהרען אַ גרופּע תלמידים מובחרים פון דער ישיבה ומתיב­תא תו\"ת אין ברוקלין קיין שיקאַגאָ פאָרטצוזעצען זייערע לימודים אין דער דאָרטיגער ישיבה\". ע\"ד הישיבה בשיקאַגאָ ונסיעת בחורים לשם — ראה אגרות­-קודש ח\"ח ע' שכט. ע' תב. וש\"נ. ספר תולדות חב\"ד בארצות הברית ע' רסג ואילך."],["e3","*","ברשימת השיחה שתח\"י (וכן ע\"פ זכרון כמה מהתלמידים שנסעו אז) התאריך הוא י\"ב תשרי.0"]]],[4301620158,"<h3>ליל א' דחג הסוכות תש\"ו</h3>\nא. כ\"ק אדמו\"ר שליט\"א ציוה לנגן ואמר:\nאַ פנימיות'דיגען ניגון; עס זאָל דורכנעמען די פנימיות, עס באַדאַרף ניט ניכר זיין אין די חיצוניות, עס דאַרף דערנעמען די פנימיות. אין חיצוניות באַדאַרף ניט ניכר זיין.\nב. עס איז ידוע באַ חסידים אַז דער אַלטער רבי האָט געהאַט מסירת נפש בפועל אויף מנהגי קודש הקדשים מורנו הבעש\"ט נ\"ע.\nאיינער פון די מנהגי קודש של מורנו הבעש\"ט נ\"ע איז געווען די עבודה בשמחה בחג הסוכות מיט גאָר פּשוטע אידן.\nעס איז ידוע דער מאמר קדש וואָס דער אַלטער רבי האָט געזאָגט בשם הבעש\"ט, אַז דעם פּשוט'ן אידנ'ס קיום המצות מצד אמונה אין עצמות, איז אַ כלי צו עצמות און איז גורם אַ נחת רוח אין עצמות. די פשיטות העצמות איז שורה אין דער כלי פון קיום המצות בפשיטות<sup data-n=\"11\">1</sup>.\nג. מורנו הבעש\"ט האָט געהאַט אַ געבויטע וואַרעמע סוכה<sup data-n=\"12\">2</sup>.\nדער בעש\"ט האָט געזאָגט, אַז זיין נוי סוכה<sup data-n=\"13\">3</sup> זיינען פּשוט'ע קבלת עול אידן, וואָס זיינען גורם אַ שמחה למעלה מיט זייער שמחה של מצוה מצד אמונה פשוטה.\nד. אַ אזן שומעת<sup data-n=\"14\">4</sup> איז וואָס מען",[["11","1","ראה גם סה\"מ תרצ\"ו ע' 13. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 228. לקמן ע' 64. ע' 69. ע' 119. ע' 136. ע' 154. ע' 161. ע' 203. ע' 248. ע' 383."],["12","2","ע\"ד סוכתו של הבעש\"ט — ראה גם שיחת יום ב' דחג הסוכות תשכ\"ה. תשכ\"ז."],["13","3","ע\"ד נוי סוכה — ראה גם ספר השיחות תש\"ד ע' 12. שיחת יום שמח\"ת תש\"ל."],["14","4","ע\"פ לשון המשנה — אבות פ\"ב מ\"א."]]],[4301620159,"הערט אָט דאָס וואָס מען דערציילט, אָבער אַ אזן מלין תבחן<sup data-n=\"15\">5</sup> איז צו דער­הערן ווי מען דערציילט<sup data-n=\"16\">6</sup>.\nדער חילוק פון הערן וואָס מען דערציילט און הערן ווי מען דערציילט איז, אַז אין הערן וואָס מען דערציילט הערט מען דעם גוף הסיפור און אין הערן ווי מען דערציילט הערט מען די נשמה פון דעם סיפור.\nאויף צו האָבן אַ אזן שומעת באַדאַרף מען אויך האָבן אַ ריבוי יגיעה און בפרט אויף צו האָבן אַ אזן מילין תבחן באַדאַרף מען אַ רצון פנימי און אַ עונג אין דער יגיעה אויף צו דערהערן אָט דאָס וואָס מען הערט.\nה. דער מיטעלער רבי האָט דער­ציילט, אַז החסיד ר' פנחס שקלאָווער<sup data-n=\"17\">7</sup> האָט איהם דערציילט דעם וואָרט וואָס דער אַלטער רבי האָט געזאָגט אין שקלאָוו, דורכפאָרענדיק פון מעזריטש אין יאָר תקל\"א<sup data-n=\"18\">8</sup>:\nעס איז אַ סך גרינגער פועל צו זיין מוחין דגדלות אויף מחדש זיין אין תורה, ווי פועל זיין דעם תיקון המדות.\nאון האָט מסיים געווען: פאָרט אין מעזריטש וועט איר מקבל זיין דעם סדר עבודה ווי מען מאַכט אַז די מדות זאָלען זיין ווי על פי התורה איז, דעמאָלט וועט מען דערהערן דעם אור פנימי וואָס איז מאיר אין גליא שבתורה.\nו. דער עלטער זיידע, דער רבי צמח צדק, האָט געזאָגט דעם זיידען, דעם רבי'ן מהר\"ש נ\"ע:\nביי דעם זיידן — כ\"ק אדמו\"ר הזקן — איז געווען דער עיקר עבודת הלב, ביי דעם שווער — כ\"ק אדמו\"ר האמצעי — איז געווען דער עיקר עבודת המוח<sup data-n=\"19\">9</sup>.\nדער טאַטע האָט מיר דערציילט אויף יחידות, אלול תרנ\"ט, וואָס דער זיידע, דער רבי מהר\"ש, האָט געהערט פון זיין פאָטער, אדמו\"ר צמח צדק, וואָס ער האָט געהערט פון זיין זיידן אדמו\"ר הזקן פאַר זיין בר­מצוה<sup data-n=\"20\">10</sup>.\nפאַר בר מצוה האָט אים דער אַלטער רבי אַריינגערופן און האָט אים געזאָגט:\nאין אהבת השם זיינען פאַראַן שלשה אופני אהבה: בכל לבבך, בכל נפשך ובכל מאדך<sup data-n=\"21\">11</sup>. בכל לבבך איז פאַראַן ביי אַלע אידן; בכל נפשך איז פאַראַן ביי מביני מדע; ובכל מאדך איז ביי דעם וואָס האָט מסירת נפש אויף מקנה צו זיין אין אַ אידען אַ מדה טובה.",[["15","5","ע\"פ איוב יב, יא. שם לד, ג. וראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 169. לקמן ע' 249."],["16","6","ראה ספר השיחות שם ע' 343 ואילך. שיחת ל\"ג בעומר תש\"ח ס\"ג (לקמן ע' 225)."],["17","7","ר' פנחס רייזעס בן הגאון הרב חנוך העניך שיק משקלאָוו. ראה אודותו בהוספות למאמרי אדמו\"ר הזקן — הנחות הר\"פ ז\"ל ע' קצא. וש\"נ. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 55. שם ע' 126. לקמן ע' 74. ע' 154. ע' 245 ואילך. ע' 258. ועוד."],["18","8","ראה ספר השיחות שם ע' 66­60. וש\"נ."],["19","9","ראה ספר השיחות תש\"ג ע' 114."],["20","10","עוד ענינים שאמר אדה\"ז לאדמו\"ר הצ\"צ בקשר להבר­מצוה שלו — ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 87. תרצ\"ו­חורף ה'ש\"ת ע' 114."],["21","11","ואתחנן ו, ה."]]],[4301620160,"<h3>יום א' דחג הסוכות תש\"ו </h3>\nא. עס איז פאַראַן אַן אַלטער חסידישער וואָרט: דעם פאַרשטאַנד פון חסידות באַקומט מען אין לערנען חסידות. דעם געפיל אין עבודה באַקומט מען ווען מען דאַווענט מיט דעם וואָס מען האָט געלערנט.\nב. שמחת תורה ביינאַכט צו קידוש — פאַר הקפות — שנת תרנ\"ג, האָט הוד כ\"ק אדמו\"ר הרה\"ק געזאָגט:\nעס זיינען פאַראַן דרכי החסידים און עס זיינען פאַראַן דרכי החסידות<sup data-n=\"22\">1</sup>. די דרכי החסידות האָבן געמאַכט אַ חסידישן לעבן. די דרכי החסידים האָבן געמאַכט באַ חסידים אַ חסידישע היים.\nאיינע פון די דרכי החסידים איז עבודת התפלה. דער חסידישער דאַוונען איז דער חסידישער דבר המעמיד. עס שטעלט אַוועק דעם דאַוונער אין אַ ליכטיגן ווינקל. עס באַלייכט איהם זיין עבודה וועג, ער זעהט קלאָהר דעם מהות עצמו, הן די מעלות וואָס ער פאַרמאָגט און הן די חסרונות וואָס ער דאַרף אויסראַמען.\nג. החסיד הרב ר' גרשון דוב נ\"ע<sup data-n=\"23\">2</sup> איז געווען מורגל צו זאָגען נאָך אַ עבודה'דיגער קריאת שמע שעל המטה: עס לײַגט זיך, עס ווילט זיך ניט לײַגן, נאָר עס לײַגט זיך<sup data-n=\"24\">3</sup>. מען באַדאַרף אויפשטיין גאָר אַן אַנדערער<sup data-n=\"25\">4</sup>.\nנאָך אַזאַ עבודה אין ק\"ש שעל המטה שלאָפט מען אַנדערש און מען שטייט אויף אַנדערש. און בפרט אין די זמנים ווען די האַרץ איז פאַרמאַכט און דער קאָפּ פאַרשטאָפּט, וואָלטן די חסידישע עבודה פתגמים עפענען די האַרץ און באַלייכטן דעם קאָפּ.\nד. דער פעטער רז\"א<sup data-n=\"26\">5</sup> האָט גע­פרעגט באַ הוד כ\"ק אאמו\"ר הרה\"ק שמחת תורה תרנ\"ג:\nפאַרוואָס איז זינגען אין דאַוונען איינער פון די דרכי החסידות.",[["22","1","ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 181."],["23","2","החסיד ר' גרשון דובער מפּאַהאַר (תקפ\"ה (לערך)<sup data-n=\"e4\">*</sup> — תרנ\"ח<sup data-n=\"e5\">**</sup>). תלמידו של ר' הלל מפּאַריטש. — ראה אודותו במאמר אבות החסידות — \"התמים\" חוברת ה ע' לח [רלא, ב] ואילך: חוברת ח ע' לז [שצה, א] ואילך. ספר השיחות: תר\"פ­תרפ\"ז ס\"ע 81 ואילך; תרצ\"ו­חורף ה'ש\"ת ע' 24 ואילך; קיץ ה'ש\"ת ע' 26. תש\"א ע' 54 ואילך. שיחת ש\"פ נח שנה זו. ליל א' דחה\"ש תש\"ח (לקמן ע' 9. ע' 235)."],["24","3","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 119."],["25","4","ראה אגרות­-קודש חי\"ג ריש ע' תלו. שיחת עש\"ק פ' שופטים תש\"ו. ליל שמח\"ת תש\"ז ס\"ב. ליל שביעי של פסח תש\"ז סי\"ב. יום שמח\"ת תש\"ח ס\"ד. ז' אדר תש\"ט. כ\"ח אייר תש\"ט. ליל א' דחג השבועות תש\"ט ס\"ד. ליל א' דחג הסוכות ה'שי\"ת סי\"ג (לקמן ע' 55. ע' 72. ע' 117. ע' 179. ע' 305. ע' 327. ע' 328. ע' 364). שיחת ל\"ג בעומר ה'שי\"ת. יום א' דחוה\"מ סוכות תשי\"א. וראה לקמן ע' 99. ע' 290."],["26","5","ר' שניאור זלמן אהרן. ראה אודותו: ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז. תשנ\"ז) ע' 22. שיחת יט כסלו תרצ\"ג ס\"ו ואילך (לקו\"ד ח\"א טו, ב ואילך). ספר השיחות תר\"פ­תרפ\"ז ע' 41. תרפ\"ח­תרצ\"א ע' 227­226. תרצ\"ו­חורף ה'ש\"ת ע' 55 ואילך. ע' 113. ע' 239. לקמן ע' 14. ע' 83­82. ס\"ע 107 ואילך. ע' 168. ע' 193. ע' 218. ע' 254. ע' 272. קונטרס בר מצוה תרנ\"ג (קה\"ת, תש\"ס) ע' טו. ע' יז."],["e4","*","ראה מאמר אבות החסידות דלקמן."],["e5","**","ראה לקמן ע' 9. וש\"נ."]]],[4301620161,"הוד כ\"ק אאמו\"ר הרה\"ק האָט גע­ענטפערט: זינגען איז אַ מעמד הנפש וואָס ווערט אַרויסגעזאָגט אין דעם ניגון. פאַראַן אַ ניגון וואָס קומט פון די געגועים וואָס דער מנגן איז זיך מתגעגע, פאַראַן האָפנונגס ניגונים און עס זיינען פאַראַן התמרמרות ניגונים, און אַזוי זיינען פאַראַן פאַרשיידענאַרטיגע ניגונים, וואָס זיינען מתאר דעם מעמד הנפש פון דעם מנגן.\nחסידים<sup data-n=\"27\">6</sup> זינגען אין דאַוונען, ווייל קול מעורר הכוונה<sup data-n=\"28\">7</sup>. בכדי צו פאַרשטיין אַ ענין פנימי באַדאַרף מען זינגען, און אַז באַ אַ חסיד לייגט זיך אָפּ אַ ענין אין דאַוונען — זינגט זיך.",[["27","6","ראה ספר השיחות תש\"ד ע' 95."],["28","7","ראשית חכמה שער הקדושה ספט\"ו. של\"ה שער האותיות אות ק (פב, ב). שו\"ע אדה\"ז או\"ח סס\"א ס\"ה. סק\"א ס\"ג."]]],[4301620162,"<h3>יום ב' דחג הסוכות תש\"ו </h3>\nא. בשם האדמו\"ר צמח צדק:\nדי דריי חדשים פון ח\"י אלול ביז י\"ט כסלו זיינען די ימי רצון פון תורת החב\"ד און דעמאָלט איז דער זמן המוכשר אויף עבודת התפלה על פי תורת החסידות<sup data-n=\"29\">1</sup>.\nח\"י אלול איז דער גליקליכער טאָג וואָס דער זיידע — כ\"ק אדמו\"ר הזקן נ\"ע — איז געבאָרען געוואָרען. דער זיידע וואָס איז אַ נשמה דאצילות<sup data-n=\"30\">2</sup> וואָס האָט מגלה געווען און מייסד געווען עבודת החסידות, וואָס איז מרומז אין די ווערטער ח\"י אלול. אלול איז ר\"ת אני<sup data-n=\"31\">3</sup> לדודי ודודי לי<sup data-n=\"32\">4</sup>. ח\"י איז לעבען, דאָס מיינט אַז חסידות שאַפט דעם חיות אין דער ירידת הנשמה בגוף<sup data-n=\"33\">5</sup>.\nב. בשם אדמו\"ר הזקן:\nמען באַדאַרף ניט זיין גענאַרט און וויסן וואו מען האַלט אין עבודת השי\"ת. דער וואָס ווייס ניט וואו ער האַלט און מיינט אַז ער איז אַ ירא שמים, איז אַ שוטה. אַ קונץ אַ נאַר אָפּצונאַרן<sup data-n=\"34\">6</sup>?",[["29","1","ראה גם ספר השיחות תש\"ה ע' 123. שיחת י\"ט כסלו שנה זו (לקמן ע' 17. ע' 88). שיחת ש\"פ וישב, כ\"א כסלו תשח\"י."],["30","2","ראה ספר השיחות תורת שלום ע' 166. מאמר אבות החסידות — \"התמים\" חוברת ב ע' מג [סט, א]. ספר השיחות תרפ\"ח­תרצ\"א ע' 175. שיחת ש\"פ וישב כ\"ו כסלו שנה זו. רשימה ש\"פ נצבים תש\"ז. יום אחש\"פ תש\"ח (לקמן ע' 22. ע' 150. ע' 223). ד\"ה לויתן תשי\"ב (סה\"מ תשי\"ב ע' 210). ועוד. וראה לקמן ע' 27: חכמה דאצילות."],["31","3","שה\"ש ו, ג."],["32","4","פרי עץ חיים שער ר\"ה פ\"א. ב\"ח לטואו\"ח סתקפ\"א. ראשית חכמה שער התשובה פ\"ד (ד\"ה עוד יש). ועוד."],["33","5","ראה גם ספר השיחות תש\"ה ע' 122. לקו\"ש חי\"ט ע' 250 ואילך. חכ\"ד ע' 177 ואילך. חכ\"ט ע' 161 ואילך. ועוד."],["34","6","ראה בשם אדמו\"ר האמצעי: ספר השיחות תר\"פ­תרפ\"ז ע' 79. תש\"א ע' 79. אגרות­-קודש חי\"ד ע' קלה. ובשם אדמו\"ר מהר\"ש: אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"י ס\"ע כט ואילך. שם ס\"ע צט. ובכ\"מ."]]],[4301620163,"<h3>יום שבת קודש חול המועד סוכות תש\"ו </h3>\nא. באַ חסידים, איז ניגון ניט נאָר מגלה דעם מהלך הנפש פון דעם זינגער, נאָר איז אויך מעורר דעם זינגער אויף דער עבודה וואָס ער באַדאַרף האַלטן...\nב. הוד כ\"ק אאמו\"ר האָט אַמאָל געזאָגט:\nקול מעורר הכוונה<sup data-n=\"35\">1</sup>. דעם אַלטן רבי'נס חסידים, דעם מיטעלן רבי'נס און זיידענס חסידים, האָבען אויף יעדער ענין פון עבודת החסידות והחסידים געהאַט אַ ניגון מיוחד, אַ התעוררות ניגון פאַר חסידות און נאָך חסידות הערען, פאַר יחידות און נאָך יחידות<sup data-n=\"36\">2</sup>...\nאין דעם ניגון וואָס חסידים האָבען געזונגען פאַר יחידות האָט זיך געהערט מיט וואָס פאַר אַ געמיט און האָפנונג מען גייט אויף יחידות, און אין דעם נאָך יחידות ניגון האָט זיך געהערט דער שמחת הנפש וואָס דער חסיד האָט פון די הוראות פון יחידות, וואָס וועלען אים בריינגען אַ פעולה אין עבודה.",[["35","1","ראשית חכמה שער הקדושה ספט\"ו. של\"ה שער האותיות אות ק (פב, ב). שו\"ע אדה\"ז או\"ח סס\"א ס\"ה. סק\"א ס\"ג."],["36","2","ראה גם שיחת ליל שביעי של פסח תש\"ז (לקמן ע' 110)."]]],[4301620164,"<h3>ליל שמיני עצרת תש\"ו </h3>\nא. אין עבודה לעבען איז דער הפרש פון דער עבודה דשמיני עצרת און די עבודה דשמחת תורה אין דעם, אַז שמיני עצרת איז מלך בהיכלו, אַז ניט אַלע קענען אַריינגיין בהיכל מלך, און ווען מען גייט אַריין אין היכל מלך ווערט אפילו דער שר אויך בטל אַזוי ווי דער עבד. דער ביטול פון דעם שר איז מער ניט \"ווי\" דער ביטול פון דעם עבד. אַז מען זאָגט \"ווי\", מיינט מען כמו, וואָס דאָס איז נאָך ניט דער ביטול בכל עצמותו. באַ דעם עבד אָבער איז דער ביטול בכל עצמותו. אַ שר האָט שכל, אַ עבד האָט קיין אייגענעם שכל ניט, גיט איהם דער מלך זיין שכל. דער ביטול פון אַ עבד און דער שכל פון אַ מלך זיינען אַ שיינע פּאָר. און דאָס איז דער הפרש צי דער אָנהויב איז עבודה מיט קבלת עול און נאָכדעם פאַרשטייט מען, צי דער אָנהויב איז פאַרשטיין און נאָכדעם טאָן. דער הפרש איז מובן לכל.\nשמחת תורה איז מלך בהתגלות, דע­מאָלט איז די עבודה שמחה בהתגלות<sup data-n=\"37\">1</sup>, דאָס מיינט וואָס די פיס הויבען דעם קאָפּ. עבודה בפועל הויבט אויף דעם שכל המשיג אין אַזאַ אָרט וואָס דער קאָפּ קען ניט דערגרייכען. מען טאַנצט און מען טאַנצט ביז מען דערטאַנצט זיך צו דעם רום עצמי, וואָס צו דעם קען צוקומען נאָר אַ עובד וואָס מעשיו מרובים מחכמתו<sup data-n=\"38\">2</sup>.",[["37","1","להעיר ממה שמצינו בהנהגת רבותינו נשיאינו שבשמיני עצרת היו רואים אצלם תנועה ומצב רציני, משא\"כ בשמחת תורה, שאז היו בתנועה של שמחה שלמעלה ממדידה והגבלה — שיחת ליל שמחת תורה תשד\"מ. ליל ה' דסוכות תנש\"א."],["38","2","ע\"פ אבות פ\"ג מ\"י."]]],[4301620165,"ב. עס איז בא מועד אַז מען זאָל זיך נעמען פאַר עבודת החסידות און עס איז באַ מיר זיכער קלאָר, אַז די וואָס וועלען זיך נעמען פאַר עבודה עפ\"י החסידות וועלען מצליח זיין."],[4301620166,"<h3>ליל שמחת תורה תש\"ו </h3>\nא. די עבודה אמיתית איז דער תכין לבם<sup data-n=\"39\">1</sup>, בעטען באַ השי\"ת, אַז ער, ברוך הוא, זאָל העלפען אין דער התחלת העבודה פון אַוועקשטעלען די האַרץ אויף דעם ריכטיגען עבודה פּלאַץ.\nב. חסידות האָט בעזה\"י דעם געטליכען כח איבערצואַרבעטען פון אַ בעל חסרון אין כחות הנפש פאַר אַ בעל מעלה ומדריגה אין עבודת ה', אָבער צו דעם מוז מען האָבען דעם ריכטיגען רצון חזק, צו וועלען באמת ווערען אויס בעל חסרון און ווערען אַ בעל מעלה.\nג. יעדער דאַרף זיך מאַכען אַ שיעור צו לערנען דעם פירוש המלות פון דאַוונען. מען דאַרף לערנען די פסוקים פון תורה פון מקור, רש\"י און רמב\"ן אָדער אבן עזרא און כמו\"כ פון נ\"ך פון מקור. דער רבי<sup data-n=\"40\">2</sup> האָט מחבב געווען דעם מצודת<sup data-n=\"41\">3</sup>.\nד. דער אויסטייטש פון דעם וואָרט \"לימוד\" איז ניט גלייך אין לימוד החסידות און אין לימוד הנגלה. דער באַגריף פון דעם וואָרט לימוד אין נגלה איז לערנען, אָבער אין תורת החסידות מיינט דער באַגריף פון וואָרט לימוד — איבערלעבונג.\nדאָס מיינט אַז כל זמן מען איבער­לעבט ניט דעם ענין פון חסידות וואָס מען לערענט, איז דאָס נאָך ניט פאַר­שטאַנען.\nדי נקודת ההשכלה פון דעם ענין איז: אין גלי' שבתורה מיינט פאַר­שטאַנד, אַז דער פאַרשטייער באַלעבט די השכלה, און אין פנימיות התורה מיינט פאַרשטאַנד, אַז די השכלה באַ­לעבט זיין פאַרשטאַנד.\nה. הוד כ\"ק אאמו\"ר הרה\"ק האָט מיר געזאָגט אַז ער האָט געהערט פון הוד כ\"ק אביו אאזמו\"ר הרה\"ק, אַז ער האָט מקבל געווען רבי מפי רבי, אַז אויף עבודה על דרך החסידות שטייט עמוק עמוק מי ימצאנו<sup data-n=\"42\">4</sup>. דער דרך החסידות איז אַ אין סוף עומק, און דער וואָס איז אַ עבודה'דיגער \"מי\", דעם גיט מען מלמעלה על פי הוראת בית דין של­מעלה, אַז ער זאָל מצליח זיין בעבודתו און אַז ער זאָל זיין אַ ימצאנו'דיגער.",[["39","1","ע\"פ תהלים י, יז."],["40","2","כ\"ק אדמו\"ר הזקן."],["41","3","ראה שיחת ש\"פ חיי שרה תשי\"א (לקו\"ש חט\"ו ע' 504): \"דער רבי האָט זייער געהאַלטן פון דעם מצודת — איך ווייס ניט מצד וועלכע סיבה — ער האָט אויך דערציילט אז דער שיעור תהלים פלעגט מען אַמאָל לערנען עם פי' המצודת\". ובספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 158 בשם אדמו\"ר מהורש\"ב: \"פירוש המצודת דוד בריינגט דער זיידע, און אז דער זיידע בריינגט דעם מצודת דוד דאַרף מען זיך אויף דעם אָפּשטעלן\"."],["42","4","קהלת ז, כד. וראה שיחת מוצאי יו\"כ ה'שי\"ת ס\"ג. רשימה מחורף ה'שי\"ת (לקמן ע' 346. ע' 355)."]]],[4301620167,"<h3>ר\"ד ש\"פ נח ה'תש\"ו, בסעודת הלילה<sup data-n=\"43\">1</sup> </h3>\nא. (הי' יאצ\"ט של הרג\"ד פּאַהאַ­רער<sup data-n=\"44\">2</sup>). תרנ\"ב בעת חתונת ר\"מ האָרענ­שטיין<sup data-n=\"45\">3</sup> הי' אז הרג\"ד בליובאַוויטש, א\"ל כ\"ק אאמו\"ר נ\"ע שאבקר אצלו ואסתכל במנהגיו ואשמע מה שיספר לי.\nסיפר לי: שמעתי מחסידים הרא­שונים (של אדה\"ז), שנתקרבו לחסידות ע\"י התפלה בנגינה — די חסידישע ניגונים האָט אויף זיי געפּועל'ט. וסיים (הרג\"ד): הנני מתמרמר על שאיני מנגן — אף שהנני ג\"כ כבד פה<sup data-n=\"46\">4</sup> אין זה נוגע לי כ\"כ — והנני חושב זה לי לעונש. וזלגו עיניו דמעות.\nסיים כ\"ק אדמו\"ר שליט\"א: בכלל בכי' שלו איז גיווען אַ בכי' פנימית.\nב. (הרש\"ל<sup data-n=\"47\">5</sup> סיפר שזקנו הרג\"ד התארח בהיותו בנעוועל אצל השו\"ב ר' חיים דוד ליין<sup data-n=\"48\">6</sup> — העיר כ\"ק אד\"ש: בנערותו למד בסלוצק ואח\"כ התקרב לעדת החסידים — בתחלה לא נשא חן בעיניהם בהיותו במרירות וכו' והם היו מורגלים בהתפשטות וכו', ואח\"כ שמעוהו קורא תהלים: עד<sup data-n=\"49\">7</sup> אנה תשכחני וגו' וזה עשה עליהם רושם גדול.\nאמר כ\"ק אד\"ש:) מזה מובן ג\"כ מה שנדבר בחה\"ס העבר אַז מיט אַ וואָרט חסידות קען מען לעבען אַ יאָר דאָס איז ווי אַ שוועבעלע מיט וועלכע מ'קען אָנצינדען אַ גרויסען פייער.\nג. מ'דאַרף זעהן מ'זאָל אָנהייבען דאַוונען. מ'דאַרף ניט דוקא אַ סך חסידות, וויפל מ'לערנט קען מען זיך צוטראָגען און דאַוונען דערמיט. כ\"ק אאמו\"ר נ\"ע אמר ע\"ז: דער הינטער גרונט פון חסידות.\nד. העיקר הוא שעבוד הלב. הרשד\"ב באָריסאָווער<sup data-n=\"50\">8</sup> [איז] געווען אָנגעלערנט דא\"ח של אדהאמ\"צ והצ\"צ בקי בלקו\"ת וכו'. פעם בא לליוב[אַוויטש] ושאל את הצ\"צ ענין מסובך בדא\"ח. ענהו: תשאל את ר' זלמן קאַראַבעלניק — איש בעל השגה קטנה אבל מאריך בתפלה באמירת תהלים בבכי' וכה\"ג.",[["43","1","צילום גוכי\"ק כ\"ק אדמו\"ר נשיא דורנו נדפס בספר ימי מלך (קה\"ת — אה\"ק — תנש\"א) ח\"ב ע' 603­601."],["44","2","הרה\"ח ר' גרשון דוב מעיר פּאַהאַר. נפטר בשנת תרנ\"ח (רשימת היומן תשרי תרצ\"ג (\"רשימות\" חוברת יד ע' 5)). — ראה אודותו לעיל ע' 5."],["45","3","הרה\"ח ר' משה הכהן האָרענשטיין עם מרת חי' מושקא בת אדמו\"ר מהר\"ש (החתונה התקיימה ביום ו' עש\"ק יו\"ד אלול תרנ\"ב — ראה סה\"מ תרנ\"ב ע')."],["46","4","ראה גם ספר השיחות תר\"פ­תרפ\"ז ריש ע' 82."],["47","5","ר' שמואל ב\"ר זאב וואָלף הלוי לעוויטין. תרמ\"ד­תשל\"ד. ראה אודותו ספר השיחות שם ע' 85 הערה 12. וש\"נ."],["48","6","החסיד ר' חיים דוד ב\"ר משה לייב ליין בנו של הרה\"ג הרה\"ח ר' פרץ חן. מחסידי אדמו\"ר מהר\"ש ואח\"כ מחסידי אדמו\"ר מהורש\"ב ואדמו\"ר מהוריי\"צ. נפטר [קיץ?] תרצ\"ט. נזכר באגרות­-קודש ח\"ג ע' תיא. ח\"ד ע' רצ. מכתבים אליו באגרות­-קודש חי\"א ע' רכג. ע' רלב. חי\"ג ס\"ע ס ואילך. ע' עא ואילך. חי\"ד ע' יד ואילך. ע' כב ואילך. ס\"ע כז ואילך."],["49","7","תהלים יג, ב."],["50","8","החסיד ר' שמואל דובער מבאָריסאָוו. ראה אודותו: \"התמים\" חוברת ה ע' צט [רסב, א] ואילך (ושם ע' קג [רסד, א]: \"נולד בשנת תקס\"ח לערך ונפטר בשנת תרמ\"ט\"). אגרות­-קודש ח\"ג ע' קנז ואילך. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 123. ע' 150. ע' 208. ע' 305. קיץ ה'ש\"ת ע' 137 ואילך. ועוד."]]],[4301620168,"הרשד\"ב איז געוואָרען אַראָפּגע­פאַלען באַ זיך ופעל שפלות גדולה. מתחלה לא הלך אל הרז\"ק אבל העיק עליו מענה הצ\"צ שאינו מקיימו. וכעבור כשבועיים הלך אל הרז\"ק ושאלו הענין, והלה התחיל לענות לו בהסברה טובה. ונתפעל הרשד\"ב במאד. וישאלהו: מאין לך ידיעות כאלו, ויענהו: כי נתחנך אצל דודו מחסידי אדה\"ז, שמע ממנו כי העיקר הוא שעבוד הלב ואח\"כ באה ההשגה מעצמה באופן אחר.\n— ויספר הרשד\"ב כל מאורע זה לכ\"ק אדנ\"ע בסיימו: מ'ווע[ר]ט באַ זיך אַראָפּגעפאַלען אַז אַ משכיל קען רעדען 5 שעה און מ'חאַפּט זיך אַז דאָס פּלוידערט מען.\nה. נשכחו כמה ענינים מתהלוכות החסידים. וגם מה שזוכרים הוא בהג­שמה.\nו. אמר כ\"ק אדנ\"ע: לכל חותם יש מפתח המיוחד לו. אבל אצל האומן יש כלי שע\"י יכול לפתוח כל החותמות וזהו ענין הנגינה<sup data-n=\"51\">9</sup>.\nז. צוה לנגן ואמר שכ\"ק אדנ\"ע אמר שאוהב הוא בכל ענין מתינות וגם בנגינה צ\"ל כן.\nח. קרה אצל כ\"ק אדנ\"ע שבאמצע כתיבת מאמר דא\"ח — שהי' כותב ביאַרמולקע — הי' מפסיק, מניח מטפחת על הכתב, לובש הכובע ומנגן. ואמר: דאָס איז צוליב דעם אָפּלייג פון ענין.\nט. (שאל השואל: המשך מים רבים תרל\"ו מתחיל מש\"ק<sup data-n=\"52\">10</sup> ולא מיו\"ט כמו רוב המכריע של ההמשכים. וענה כ\"ק אד\"ש שלא שמע בזה איזה מסורת).\nיוד. כ\"ק אדמו\"ר מהר\"ש נ\"ע איז געווען אויפגעלייגט פון חתונת כ\"ק אדנ\"ע<sup data-n=\"53\">11</sup> און האָט פאַרבראַכט ווען דער טאַטע<sup data-n=\"54\">12</sup> איז געווען אויף דער חתונה<sup data-n=\"55\">13</sup>. ואמר אז: אַז רש\"ב — כי כן הי' קורא לכל בניו וגם לחתנו הרמ\"ל<sup data-n=\"56\">14</sup> בר\"ת<sup data-n=\"57\">15</sup> — איז משיג אַ ענין לאמיתתו<sup data-n=\"58\">16</sup>. חסידים ווינשען זיך השגת המוחין ער ווייס אַז דער עיקר איז שעבוד הלב און אַז מ'האָט שעבוד הלב גיט מען השגת",[["51","9","בספר הניגונים ח\"א ע' לט הובא משיחת ש\"פ נח תש\"ו: \"כ\"ק אאמו\"ר הרה\"ק האָט געזאָגט: צו יעדער שלאָס איז פאַראַן זיין באַזונדער מפתח, אָבער ביי אַ אומן איז דאָ אַזאַ כללות'דיגער מפתח מיט וועלכין מ'קען עפענען אַלע שלעסער, און דאָס איז דער ענין פון נגינה\"."],["52","10","ש\"פ וירא תרל\"ו."],["53","11","החתונה התקיימה במוצש\"ק י\"א אלול תרל\"ה. — ראה ליקוט שיחות ורשימות בקשר להתונה בהוספות לסה\"מ תרל\"ה ח\"ב ע' תקנה ואילך."],["54","12","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["55","13","חתונתו של כ\"ק אדמו\"ר מהורש\"ב נ\"ע היתה בעיר אוורוטש מקום דירת חותנו הרה\"ק ר' יוסף יצחק. מפני סיבות שונות, והעיקר לסיבת חולשת הבריאות לא יכול כ\"ק אדמו\"ר מהר\"ש לנסוע על החתונה לאוורוטש (\"התמים\" חוברת ב ע' מה [ע, א]). קודם שחזר כ\"ק אדמו\"ר מהורש\"ב לליובאַוויטש, אמר אדמו\"ר מהר\"ש ל\"ב מאמרים מיום האופרופענעש עד אחר שבעת ימי המשתה (ספר השיחות תש\"ד ע' 173)."],["56","14","הרה\"ח ר' משה ארי' ליב גינזבורג מוויטעפסק (בעלה של הרבנית מרת דבורה לאה). נפטר יום א' דחג הסוכות, טו תשרי, תרצ\"ה."],["57","15","ראה גם ספר השיחות תרפ\"ח­תרצ\"א ע' 223."],["58","16","ראה ספר השיחות תש\"ד שם: \"איידער דער טאַטע [כ\"ק אדמו\"ר מהורש\"ב נ\"ע] איז געקומען פון דער חתונה האָט דער זיידע [כ\"ק אדמו\"ר מהר\"ש] געזאָגט אויף דעם טאַטן, ווייסט איר ווער ער איז — ער איז ווי דער רמב\"ם זאָגט [הל' יסוה\"ת פ\"ז ה\"א] הוא מתגבר בדעתו על יצרו תמיד והוא בעל דעה רחבה נכונה עד מאד\"."]]],[4301620169,"המוחין מלמעלה איז דאַמאָלס די השגה אַנ'אַנדערע און די מוחין אַנדערע.\nיא. שמעתי ממהרי\"ם<sup data-n=\"59\">17</sup> שאמר אאזמו\"ר מהרשנ\"ע: פון זיין חתונה האָב איך שמחת הלב און חסידים ועלען האָבען שמחת המוח, אַלס אַ אויפגאָב גיב איך זיי דעם מים רבים<sup data-n=\"60\">18</sup>. וסיים הרי\"ם: אַז מ'איז געווען פאַרזאָרגט פון די וערטער כי הבינו בזה שמרמז...\nיב. (שאל הרש\"ל במה הוא קוטב השינוי עתה. וענה כ\"ק אד\"ש:) כללות הציור הי' באו\"א. דעם טאַטען האָט מען געקענט פון ביהמ\"ד. אכו\"ש לא הי' להם תפיסת מקום, ברויט מיט ציבעלע, במילא איז מען געווען איידעלער.\nיג. (שאל השואל: מספרים כי הצ\"צ הי' יורד לפני התיבה ובפרט באמירת הלל<sup data-n=\"61\">19</sup>. וענה כ\"ק אד\"ש:) לא בימי הנשיאות כ\"א לפעמים, באמירת הלל בר\"ח. (שאל השואל: אם הטעם הוא מפני שרצה לברך בעצמו או רק אז כשהש\"ץ לא נשא חן בעיניו לצאת בברכתו, או ב' הטעמים. וענה:) רק טעם א' (לא רצה לאמר איזה, אבל נראה הי' שהוא הטעם הב')<sup data-n=\"62\">20</sup>.\nיד. כ\"ק אאזמו\"ר מהר\"ש נ\"ע אמר: דער טאַטע האָט מורא געהאַט פאַר דער ברכה (ברכת הלל בימים שאין גומרים<sup data-n=\"63\">21</sup>), איך נעם דאָס אַף זיך<sup data-n=\"64\">22</sup>.\nטו. (אמר הרש\"ל: בדא\"ח של מהרי\"א מהאָמיל<sup data-n=\"65\">23</sup> מובא שאמר אדה\"ז בשם הה\"מ שציווי ואהבת<sup data-n=\"66\">24</sup> הוא על ההתבוננות. וענה כ\"ק אד\"ש:) מובא זה בדא\"ח<sup data-n=\"67\">25</sup>. דאָס איז אויף זיך גרינגער מאַכען.",[["59","17","הרה\"ח הרה\"ג ר' יעקב מרדכי בעזפּאַ­לאָוו, רב בפּאָלטאַווע. מחסידי אדמו\"ר מהר\"ש ואח\"כ אדמו\"ר מהורש\"ב נ\"ע. י\"ב אייר תרט\"ו — ל' תשרי תרע\"ו. ראה אודותו: ספר השיחות תרפ\"ח­תרצ\"א ע' 92. וש\"נ. ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז. תשנ\"ז) ע' 81. וראה לקמן ע' 13. ע' 15. ע' 107. ע' 161. ע' 403."],["60","18","המשך מים רבים תרל\"ו."],["61","19","ראה גם רשימת היומן של רבינו מיום ט\"ו אייר תרס\"ד."],["62","20","ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 231: \"היו זמנים שהצ\"צ הי' אומר ביו\"ט הלל לפני העמוד, במקום הש\"ץ\"."],["63","21","אדה\"ז כותב בסידורו (לפני הלל) ש\"בימים שאין גומרין את ההלל יש לנהוג שהש\"ץ לבדו יברך בתחלה ובסוף והקהל יענו אמן ויצאו בברכתו\". משא\"כ ביחיד, \"נוהגים אשר היחיד מברך — בהלל — תחלה וסוף גם בימים שאין גומרים בהם את ההלל\" (\"היום יום\" ר\"ח טבת). ובהגהות כ\"ק אדמו\"ר מהורש\"ב נ\"ע לסידור ד\"ה הלל: \"ואני שאלתי מכ\"ק אאמו\"ר זצוקללה\"ה אם לברך תחלה וסוף ביחיד וא\"ל ששאל זאת מכ\"ק אאזמו\"ר זצוקללה\"ה והשיב לו שיכולים לעשות כמו שרוצים\"."],["64","22","ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 241 ע\"ד הנהגת כ\"ק אדמו\"ר מהורש\"ב נ\"ע: \"כן תמיד אמר הלל בברכה. על אמרו בברכה גם בהתפללו בצבור בימים שא\"ג את ההלל, ולא יצא ברכת הש\"ץ. . שאלתיו מפני מה לא יתפלל בעצמו לפני התיבה ויהי' טוב לדברי הכל, ויענה: מה לי לקחת הכל אַפן וואָגען\". ולהעיר משיחת ש\"פ מסעי תשמ\"א בנוגע לברכת הלל: מנהג חסידים אַז מ'כאַפּט אַריין אויך די ברכה בחשאי."],["65","23","בספרו שני המאורות ח\"ב סימן ב (ל, ב): \"שמעתי פא\"פ מאדמו\"ר נ\"ע בזה\"ל כך קבלתי מהה\"מ דמעזריטש וכך קבל הוא ז\"ל מהבעש\"ט שמצות ואהבת היא לתקוע מחשבתו ודעתו (ובל\"א אמר בזה\"ל מע זאָל זיך אַריין טאָן) בדברים המעוררים את האהבה, ומה שיבא מזה אין זה מעיקר המצוה\"."],["66","24","ואתחנן ו, ה."],["67","25","ד\"ה להבין מצות אהבה (נדפס בדרך מצותיך קצט, א). המשך והחרים תרל\"א ע' סו. בשם הרב המגיד ממעזריטש — סה\"מ תרצ\"ט ע' 8; תש\"א ע' 116; אגרות­-קודש ח\"ג ע' תכו."]]],[4301620170,"<h3>ליל ש\"ק פ' לך לך תש\"ו בסעודה </h3>\nא. בשנת תרנ\"ד האָט כ\"ק אאמו\"ר פאַרבראַכט שבת פ' לך לך, קוטב השיחה: אָנהייב עולם התיקון. בכלל פלעגט מען ניט אַלעמאָל פאַרבריינגען פ' לך לך. נאָך שבת האָט רשב\"ץ<sup data-n=\"68\">1</sup> פאַר­בראַכט און האָט געזאָגט אויף אאמו\"ר: בוצינא קדישא אור העצמי, אַז מיר וואָלטען געהאַט אַזאַ מדריך יונגער­הייט וואָלטען מיר גיווען אַנדערש.\nיענעם יאָר האָט רשב\"ץ פאַרבראַכט גאַנץ עשי\"ת, אויך די נאַכט פון ערב יוכ\"פ. פאַרטאָג האָבען זיי געזאָגט: מען דאַרף גיין צום האָן, צום שליח, צו דער תמורה.\nב. בשנת תרנ\"ב אויף דער חתונה פון ר' משה האָרענשטיין<sup data-n=\"69\">2</sup> האָט אאמו\"ר נ\"ע פאַרבראַכט און גערעדט<sup data-n=\"70\">3</sup>: אַז מ'לערנט חסידות און מען טוט נישט אין עבודה, איז דער עונש ווי פון דעם וואָס נעמט ראשו של מלך און בויגט איהם איין ווי עס שטייט אין תניא<sup data-n=\"71\">4</sup>, די שמיץ וואָס מען וועט געבען איז דער חלק האחרון צוגיוויינט דערצו, אָבער די חרפה דערפון.\nדאַמאָלסט איז דאָרטן געווען פתחי' חאַרסאָנער און ישעי' חאַרסאָנער<sup data-n=\"72\">5</sup>. איז פתחי' איז נתבטל געוואָרען, און ישעי' איז געשטאַנען און שווייס און טרערן האָבען זיך געגאָסען פון איהם. דער פעטער רז\"א האָט געזאָגט: ער ווערט בטל פאַר'ן אמת, פאַר דעם נפש'דיקען אמת.\nג. אדמו\"ר מהר\"ש האָט אַמאָל גע­לערנט מיט אאמו\"ר נ\"ע דעם מאמר פון פ' לך לך אין תורה אור<sup data-n=\"73\">6</sup>, איז אויף דער שורה \"אב רם הוא השכל הנעלם מכל רעיון\" האָט ער גערעדט הסברה פיר שעה.\nד. אאמו\"ר נ\"ע האָט געזאָגט תרנ\"ד אַ מאמר לך לך<sup data-n=\"74\">7</sup> אַ פרומער מאמר<sup data-n=\"75\">8</sup>: מען דאַרף צוקומען צום רצון למעלה מטעם ודעת, דורך אַוועק גיין \"מארצך וממו­לדתך ומבית אביך\" פון השגה, דאַ­מאָלסט קומט מען צו \"אל הארץ אשר אראך\"<sup data-n=\"76\">9</sup>.\nה. בכלל פלעגט אאמו\"ר אין די ערשטע יאָרען אַ סאַך פאַרבריינגען, אויך אדמו\"ר הצ\"צ אין די ערשטע יאָרען ובפרט בזמן הנשיאות של אדמו\"ר האמצעי<sup data-n=\"77\">10</sup>.",[["68","1","החסיד ר' שמואל בצלאל ב\"ר שלום שבתי שעפטל. ראה תולדותיו ב\"התמים\" חוברת א ע' סז [לה, א] ואילך. ספר השיחות קיץ ה'ש\"ת ע' 91 ואילך. שיחת יום א' דחה\"פ שנה זו. י\"ב תמוז תש\"ז ס\"ו רשימת חורף ה'שי\"ת (לקמן ע' 29 ואילך. ס\"ע 136 ואילך. ע' 350). וראה ספר השיחות תרפ\"ח­תרצ\"א ע' 95. לקמן ע' 161. ע' 163. ע' 215. ע' 246. ע' 332."],["69","2","עם ב\"ג הרבנית מרת חי' מושקא. החתונה התקיימה יום ו' עש\"ק יו\"ד אלול תרנ\"ב (ראה סה\"מ תרנ\"ב ע')."],["70","3","ראה גם אגרות­-קודש ח\"ד ס\"ע שא ואילך."],["71","4","סוף פרק כד."],["72","5","באגרות­-קודש שם (ע' שב): ר' יהושע שו\"ב דחערסאָן."],["73","6","יא, א."],["74","7","נדפס בסה\"מ תרנ\"ד ע' מח ואילך. ואוצ\"ל: תרנ\"ה (סה\"מ תרנ\"ה ע' יח ואילך). — ראה סה\"מ שם ע' בהערה ש\"בקופיר בראש המאמר נרשם: דער פרומער לך לך\"."],["75","8","ראה גם שיחת יום שמח\"ת ה'שי\"ת (לקמן ע' 377)."],["76","9","לך לך יב, א."],["77","10","ראה גם שיחת ליל שביעי של פסח שנה זו (לקמן ע' 38). וראה ספר השיחות קיץ ה'ש\"ת ע' 165."]]],[4301620171,"אַמאָל איז אנושיות, מענטשליכקייט, בכלל, געווען אַנדערש, ובפרט אין די קליינע שטעטלעך, און אַ חסיד בפרטי פרטיות.\nאַמאָליקע חסידים איז באַ זיי געווען די זריעה און זיי האָבן קולט גיווען. זיי האָבען גענומען די נקודה, ס'איז דאָך תן<sup data-n=\"78\">11</sup> לחכם ויחכם עוד<sup data-n=\"79\">12</sup>, זיי האָבען גענומען די נקודה.\nזיי וואָלטען נישט געקענט צונעמען ווי דאָס איז איצטער דאָ.\nו. כשהי' כ\"ק אדמו\"ר שליט\"א בן שמונה שנה — אמר ע\"ע שאז לא הבין עוד כ\"א קטעים קטעים ממה שאמרו — האָט ער געהערט אַ שיחה מכ\"ק אאמו\"ר נ\"ע וקוטבה אַז אָן חסידות קען מען נישט לעבען. ועוד שמע פתגם אחד...\nכשהי' בן י\"ג שנה הביאו את הרשב\"ץ נ\"ע ללמוד עמו<sup data-n=\"80\">13</sup>.\nז. אויף די משפיעים ליגט דער חוב צו לערנען דאַוונען די תלמידים, נישט מאמרים אויף דאַוונען, נאָר לערנען ווי צו דאַוונען. מען דאַרף זינגען אַ ניגון, נישט מיט חזנות, נאָר אַזוי זינגען. נישט דוקא אַ גאַנצען ניגון, אפילו איין תנועה נאָך אַמאָל און נאָך אַמאָל.\nאאמו\"ר נ\"ע פלעגט שבת דאַוונען אין זאַל, פלעגט קומען יוסף דער שניידער — שהי' אצל הצ\"צ — און דער בלעכער ואצלם הי' כבר נאָך דער סעו­דה, אאמו\"ר פלעגט זינגען אין דאַוונען און צוקלאַפּען באצבע, זיי פלעגען זאָגען תהלים און וויינען.\nח. (שאל הרמ\"ש שיחי': א\"כ איז דאָך לערנען חסידות אָן עבודה טויג נישט, מדוע לא יהי' כמו נגלה. והשיב כ\"ק אדמו\"ר שליט\"א:) יעקב מרדכי מפּאָל­טאַווע<sup data-n=\"81\">14</sup> כשהי' מבאר ענין בחסידות הי' מסבירו, ווען ער האָט שוין מער ניט גיהאַט קיין אותיות פלעגט ער זאָגן: אַזוי אַזוי איז דער ענין<sup data-n=\"82\">15</sup>.\nט. אַז אַ פּשוט'ער איד זאָגט ווי עס דאַרף זיין \"אלקי נשמה\" מיט אַ ניגון, און אַ צווייטער מיט גרעסטע כוונות, איז דאָס בהשוואה.",[["78","11","משלי ט, ט."],["79","12","ראה שיחת י\"ב תמוז תש\"ח (לקמן ע' 243). וש\"נ."],["80","13","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 185, שבין כסא לעשור שנת תרנ\"ד היו הימים הראשונים שהתחיל ללמוד עם הרשב\"ץ. וראה גם שם ע' 120. ספר השיחות קיץ ה'ש\"ת ע' 161. רשימה מחורף ה'שי\"ת סי\"ז (לקמן ע' 353)."],["81","14","ראה אודותו לעיל ע' 11. וש\"נ."],["82","15","\"לשון כמה מזקני החסידים לאחרי שקו\"ט עמוקה בעניני דא\"ח ובכ\"ז לא נחה דעתם בהבנת הענין לתכליתו, אלא שהונח (אָפּגעלייגט) אצלם הענין בודאות ובבהירות\" (לקו\"ש חלק כא ע' 334 הע' 88). וראה שיחות: י\"ב תמוז תשי\"א, אחש\"פ וכ\"ף מנ\"א תשי\"ג (תורת מנחם התוועדויות ח\"ג ע' 221. ח\"ח ע' 113. ח\"ט ע' 108). במק\"א (שיחת י\"ב תמוז תשכ\"ז. ועוד) הובא פתגם זה בשם החסיד רד\"ץ חן<sup data-n=\"e6\">*</sup>."],["e6","*","ראה אודותו לקמן ע' 425."]]],[4301620172,"<h3>ליל ש\"ק פ' וירא, כ' מר­חשון תש\"ו בסעודה </h3>\nא. כשאמי זקנתי הרבנית רבקה<sup data-n=\"83\">1</sup> הרתה עם כ\"ק אאמו\"ר נ\"ע<sup data-n=\"84\">2</sup> היתה חלושה, ולפני שנתיים<sup data-n=\"85\">3</sup> ילדה את הרז\"א<sup data-n=\"86\">4</sup>, ולפני שנה<sup data-n=\"87\">5</sup> ילדה<sup data-n=\"88\">6</sup> את ר' סענדער<sup data-n=\"89\">7</sup> שנסתלק בן חמשה­שמונה שנים<sup data-n=\"90\">8</sup>. — נכנס כ\"ק המהר\"ש אל הצ\"צ וסיפר לו אודות חולשתה. וציוה הצ\"צ שתיכנס אליו, ונכנסה ואמר לה: מז\"ט, עס וועט זיין אַ געזונטער קינד. ונתן לה סדר איך שתתנהג בימי עיבורה, וגם צוה להעלים את זה ככל האפשר<sup data-n=\"91\">9</sup>. ואח\"כ אמר להמהר\"ש: עס וועט זיין אַ אינגל, אָבער זאָלסט קיינעם ניט אויסזאָגן.\nפ' נח<sup data-n=\"92\">*9</sup> האָבן זיך אָנגעהויבען וויי­טאָגן, ונכנסה חמותה הרבנית מוסיא<sup data-n=\"93\">10</sup>",[["83","1","ראה אודותה ספר השיחות תרפ\"ח­תרצ\"א ע' 26 הערה 13. וש\"נ."],["84","2","בשנת תר\"כ."],["85","3","יום ה' פ' פנחס, י\"ט תמוז תרי\"ח (ראה ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז. תשנ\"ז) ע' 22. שם ע' 97 — בהוצאת תשנ\"ז. וש\"נ). ולהעיר שבכ\"מ הובא שנולד בשנת תרי\"ט (רשימת רבינו — קונטרס בר מצוה תרנ\"ג ע' יז. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 239. וש\"נ. וראה אגרות­-קודש ח\"ז ע' עב. לקמן ע' 168)."],["86","4","ראה אודותו לעיל ע' 5. וש\"נ."],["87","5","בשנת תרי\"ט [להעיר שברשימת מאמרי דא\"ח של הצמח­צדק (קה\"ת, תשנ\"ד) ברשימת מאמרי תרי\"ט מובא ב' מאמרים בענין המילה — ד\"ה חגור חרבך (שם ע' קלז) וד\"ה אני הנה בריתי אתך (שם ע' קמא)]. בנו\"א: \"ולפני זה ילדה את ר' סענדער\". דהיינו שנולד לפני הרז\"א. — ראה הערה הבאה."],["88","6","להעיר שברשימת בני אדמו\"ר מהר\"ש בספר התולדות שם (ע' 21) הסדר הוא: א) הר' אברהם סענדער. ב) הרז\"א. ג) אדמו\"ר מהורש\"ב. וב\"היום יום\" בתחילתו: א) הרז\"א. ב) אדמו\"ר מהורש\"ב. ג) הר' אברהם סענדער. וראה רשימת היומן מאריענבאַד, תרצ\"ד (\"רשימות\" חוברת קפא ע' 4): \"למהרשנ\"ע היו עוד ב' בנים. א' בין דבורה לאה ורז\"א. וא' בין אדמו\"ר נ\"ע ומנחם מענדל נ\"י. [הבן] שבין דבורה לאה ([ש]היתה בכורה) ורז\"א חי ח' שנים. . (הצ\"צ אמר עליו דאָס איז דער זיידע. מסופקני קצת. מ\"מ)\"."],["89","7","העילוי הגאון וצדיק ר' אברהם סענדער. — ספר התולדות שם ע' 21. ראה אודותו: רשימת היומן של רבינו מיום ה', כ\"ה תשרי תרנ\"ח — \"התמים\" חוברת ה ע' לח [רלא, ב]. ספר השיחות קיץ ה'ש\"ת ע' 99 (הועתק בספר התולדות שם)."],["90","8","ב\"התמים\", ספר השיחות (ו\"היום יום\" שם) שנסתלק בן שמונה שנה בחיי אדמו\"ר הצ\"צ<sup data-n=\"e7\">*</sup>. ועפמ\"ש כאן שנולד בשנת תרי\"ט אואפ\"ל שנסתלק כשנכנס לשנתו השמינית. ועצ\"ע."],["91","9","בנו\"א נוסף: כפי המנהג להעלים את ההריון בחדשים הראשונים, עד שהיו נשים שהיו נוהגות לילך לטבילה כדי שלא יהי' ניכר."],["92","*9","שנת תרכ\"א."],["93","10","הרבנית הצדקנית מרת חי' מושקא, בתו של אדמו\"ר האמצעי, אשת כ\"ק אדמו\"ר הצמח צדק. נולדה בעיר ליאָזנא בשנת תק\"ן. בחורף תרכ\"א נחלתה, ובאור ליום הששי שמיני לחודש טבת<sup data-n=\"e8\">**</sup> נסתלקה. ומ\"כ בעיר ליובאַוויטש באהל כבוד אמה זקנתה הרבנית הצדקנית מרת סטערנא [אשת כ\"ק אדמו\"ר הזקן] וכבוד אמה הרבנית הצדקנית מרת שיינא (ראה \"הקריאה והקדושה\" טבת תש\"ג ע' ג. ספר השיחות קיץ ה'ש\"ת ע' 95. שיחת י\"ג שבט תש\"ד (סה\"מ תש\"ט ע' 42. ספר השיחות תש\"ד ע' 63))."],["e7","*","להעיר: בקובץ יגדיל תורה נ.י. חוברת סא ע' שיג ואילך נדפס העתקה מפנקס חברת מלביש ערומים בליובאַוויטש, ושם ע' שטז: \"אור ליום ג' ר\"ח טבת תרל\"ג לפ\"ק נתקבלו האחים החכימין המופלגים בני אדמו\"ר שליט\"א ה\"ה החתן ר' אברהם סנדר שי' ואחיו בדומה לו ר' מנחם מענדל שי'\". וראה גם יגדיל תורה הנ\"ל חוברת סב ע' נו. ואכ\"מ."],["e8","**","ברשימת היומן של רבינו הנדפסת בסה\"מ תשי\"א ע' 301: \"ג', ה' טבת, תרנ\"ב. היום הוא יאָרצייט של כבוד אמי זקנתי הרבנית הצדקנית מרת חי' מושקא זצוקללה\"ה נבג\"מ זי\"ע, וכ\"ק אאמו\"ר הרה\"ק אומר קדיש\". וראה כרם חב\"ד גליון 2 ע' 66 הערה 3."]]],[4301620173,"להצ\"צ וסיפרה לו, ואמר: נח איז נישט קיין צייט, ס'איז אַ דוכט. ש\"ק לך לך, אמר מאמר<sup data-n=\"94\">11</sup> המדבר אודות חילוק שבין אברהם ובין יצחק, אברהם הי' הת­עוררות על ההמשכה וע\"י יצחק נמשכה אור הגילוי גם בעולמות. אח\"כ אמר: איך האָב זיך מחי' גיווען, בעסער וואָלט געווען אברהם אָבער דאָס איז שוין אויך גוט, עס וועט זיין אַ געזונטער קינד אָבער דער ברית וועט נישט זיין בזמנו<sup data-n=\"95\">12</sup>.\n(שאלה: אם נולד בשבת, וענה כ\"ק אדמו\"ר שליט\"א) ניין, אין מיט'ן וואָך<sup data-n=\"96\">13</sup>.\nב. אאמו\"ר נ\"ע לא הי' בוכה הרבה, און ער פלעגט שמייכלען, ווען ער פלעגט זען ליכטיקייט פלעגט ער לאַכען און שמייכלען. וסיפרה זאת הרבנית רבקה לאדמו\"ר מוהר\"ש ואמרה: ער איז אַ גע­באָרענער חסיד, אַ ביטול'דיגער. וסיפר מהר\"ש לאדמו\"ר הצ\"צ, ואמר: איר מאַכט אַ טעות, ער איז נישט קיין געבאָרענער חסיד, ער איז אַ געבאָרענער רבי<sup data-n=\"97\">14</sup>.\nכשהי' בן שלש או ארבע, שאל פעם את אחותו דבורה לאה<sup data-n=\"98\">15</sup> איזה ברכה לעשות על איזה מאכל, ואח\"כ נודע לו שהי' טעות, ובכה ואמר כי ישאל את אביו תיקון על זאת, וצחקה אחותו ואמרה עס איז אַ קלייניקייט, ואמר: ס'איז שוין גאָר ניט קיין קלייניקייט<sup data-n=\"99\">16</sup>, ומאז לא דיבר עמה.\nג. כ\"ק אאמו\"ר נ\"ע האָט ניט גיהאַל­טען פון לימוד ריבוי חסידות נאָר אפי' ווינציג נאָר דורכגעאַרבעט<sup data-n=\"100\">17</sup>, דאַוונען מיט דעם. די הזלה מלמעלה, איז אַ טראָ­פּען מלמעלה מער ווי אַ עמער מלמטה.\nהי' איש ממיקולענע שהי' מאריך בתפלתו בכ\"י אפילו ביום א' וד' שהיו ימי השוק. ואמר עליו כ\"ק אאמו\"ר נ\"ע: מלאכים זיינען מקנא זיין דאַוונען, ספי­רות עליונות האָבען ניט אַזאַ ליכטיקייט ווי עס ווערט פון זיין דאַוונען ווען עס איז עולה למעלה.\nפ\"א שאל הרי\"מ מפּאָלטאַווע<sup data-n=\"101\">18</sup>: ווי קומט מען צום אמת אין דאַוונען. וענה כ\"ק אאמו\"ר נ\"ע: ווי קומט מען נישט צו צום אמת אין דאַוונען, אַז מען דאַווענט קומט מען צום אמת, אַז מען קומט נישט צום אמת איז אַ סימן אַז מען דאַווענט נישט.\nד. כ\"ק אאמו\"ר נ\"ע איז געווען אַ צובראָכענער. ער איז געווען אַ צובראָ­כענער אין אינעווייניג, און פון אויס­ווייניג פלעגט מען נישט דערקענען. ער פלעגט וועלען אַז מען זאָל נישט מכיר זיין די צובראָכענקייט פון אויסווייניג<sup data-n=\"102\">19</sup>.",[["94","11","לא נזכר ברשימת מאמרי דא\"ח של אדמו\"ר הצ\"צ (קה\"ת, תשנ\"ד)."],["95","12","ראה רשימת היומן של רבינו מיום כ\"ד כסלו תרנ\"ו (\"התמים\" חוברת ג ע' ל [קלא, ב]. קונטרס \"חנוך לנער\" ע' 7 ואילך). מוצש\"ק שמות תרס\"ז (ספר השיחות תורת שלום ע' 78)."],["96","13","ביום השני פרשת חיי שרה בעשרים לחדש מרחשון שנת תרכ\"א בשעה התשיעית בוקר — יומן תרנ\"ו שם."],["97","14","ראה גם שיחת ערב ראש השנה אחר התרת נדרים תש\"ח (לקמן ע' 157)."],["98","15","ראה אודותה ספר התולדות אדמו\"ר מהר\"ש הנ\"ל ס\"ע 22 (ותמונתה שם מול ע' 23). ספר השיחות תרפ\"ח­תרצ\"א ע' 226. תרצ\"ו­חורף ה'ש\"ת ע' 139. וש\"נ."],["99","16","ראה קונטרס \"חנוך לנער\" ע' 9 ע\"ד כ\"ק אדמו\"ר מהורש\"ב: \"עוד בקטנותו הצטיין ביר\"ש שלו, והרבה סיפורים ספרו עד\"ז בני המשפחה\". וראה גם ספר השיחות תרפ\"ח­תרצ\"א שם."],["100","17","ראה גם שיחת פורים שנה זו ס\"ב (לקמן ע' 24)."],["101","18","ראה אודותו לעיל ע' 11. וש\"נ."],["102","19","ראה גם ספר השיחות תרפ\"ח­תרצ\"א ע' 148."]]],[4301620174,"ה. כ\"ק אאמו\"ר נ\"ע פלעגט מייקר זיין יענעם בהפלאה. און פּונקט אַזוי בהפלאה פון זיך מאָנען, אַזוי ווי איינער וואָס האָט נאָך גאָר ניט אָנגעהויבען.\nכ\"ק אאמו\"ר נ\"ע האָט באַ זיך גע­מאָנט אויף דעם וואָס ער האָט טוב טעם אין הבנה והשגה און האָט נישט טוב טעם אין הרגש.\nכ\"ק אאמו\"ר נ\"ע האָט מייקר גיווען חסידות און מחבב געווען אַ חסיד.\nמען דאַרף וויסען וואו מען האַלט, אַמאָל האָט מען געוואוסט וואו מען האַלט און וואו מען דאַרף האַלטען, פון וועלכע סטאַנציע איז מען אַוועקגע­פאָרען און צו וועלכע סטאַנציע מען פאָרט.\nו. שאל הרמ\"ש שיחי': האם כ\"ק אאמו\"ר נ\"ע התראה עם הרביים מפולין, והאם דיבר עמהם בדברי חסידות וקבלה?\nמענה כ\"ק אדמו\"ר שליט\"א: ער האָט זיך מיט זיי געזען אָבער ניט מאריך גיווען אין די ענינים.\nז. אמר: מען דאַרף מאָרגען פאַר­בריינגען. מען רופט דאָך אים רבי און מ'לערענט זיינע חסידות, איז נישט קיין בזיון פאַר אים אַז מען איז זיך מתייחס צו אים. אַז מ'וועט פאַרבריינגען קומט אַרונטער, עס קומט אַרונטער בפועל.\nח. פעם אחד שמעתי מכ\"ק אאמו\"ר נ\"ע אַז דורך צובראָכענקייט קומט מען צו גאָרנישט, ופעם שמעתי דורך צו­בראָכענקייט קען מען צוקומען צו אַלץ.\nט. איין זאַך געפּועל'ט: הרבי<sup data-n=\"103\">20</sup> תבע שלא יהי' כ\"כ הבנה רק ההרגש, ופעל על אחד. ויש לפרש שעל הרגש פעל ועל ההבנה שלא יהי' כ\"כ לא פעל וד\"ל.",[["103","20","אדמו\"ר הזקן."]]],[4301620175,"<h3>ש\"פ וישלח, י\"ט כסלו תש\"ו<sup data-n=\"104\">1</sup> </h3>\n(כשנכנסו אמר כ\"ק אדמו\"ר שליט\"א): גוט יום טוב.\nא. ביי דעם צ\"צ איז געווען דער ענין פון יו\"ט י\"ט כסלו בפרסום עד שנת תרט\"ז, ווען צוליב מורא פון מאסר איז דאָס גיוואָרען נאָר בחשאי<sup data-n=\"105\">2</sup>.\nב. היינט איז באַ מיר אַ יום טוב, עס",[["104","1","ע\"ד חגיגת י\"ט כסלו תש\"ו — ראה קובץ ליובאַוויטש שנה שלישית חוברת א' ע' 1: דער היי­יעהריגער חסידישער יום טוב י\"ט כסלו, וועלכער איז אויסגעפאַלען ש\"ק פ' וישלח איז געפּראַוועט געוואָרען בבית רבנו שבת, י\"ט כסלו און זונטאָג, כ' כסלו.\nש\"ק וישלח בעת די סעודות, האָט דער רבי שליט\"א פאַרבראַכט נאָר מיט איינצעלנע מקו­רבים און זונטאָג לעת ערב, נאָכדעם ווי א גרעסערער עולם אנ\"ש און תמימים האָבען איינטייל גענומען אין די טראַדיציאָנעלע סעודת י\"ט כסלו אין גרויסען ביהמ\"ד פון כ\"ק אדמו\"ר שליט\"א אויף 770 איסטערן פּאַרקוויי, זיינען אַריין צום רבי'ן אנ\"ש חסידים, רבנים ותמימים, און דער רבי האָט פאַרבראַכט במסיבת י\"ט כסלו אייניגע שטונדען.\nסיי בעת די סעודות ש\"ק און סיי בעת די התועדות זונטאָג, האָט דער רבי שליט\"א געזאָגט דברי חסידות און דערציילט סיפורים. כדרכו בקודש איז די לעצטע צייט, צו זאָגען זעהר בקיצור, בבחי' מועט המחזיק את המרובה, בלויז די נקודות פון די ענינים, וואָס יעדער פון זיי פאָדערט אַ לענגערן ביאור און הסבר. — ראה לקמן ע' 404 — נספח לשיחות יט כסלו תש\"ו."],["105","2","ראה אגרות­-קודש ח\"ד ע' רסח: \"בשנת תרט\"ז הי' — ל\"ע — עת צרה ליהודי מדינת רוסיא בגשמיות, והעיקר ברוחניות כו'\"."]]],[4301620176,"איז פופציג יאָהר זייט איך האָב גע­הערט, אין שנת תרנ\"ו, פון טאַטען — אדמו\"ר הרש\"ב נ\"ע — אויף י\"ט כסלו: \"יום זה קרוב להיות ראש השנה\"<sup data-n=\"106\">3</sup>.\nדער לשון \"קרוב\" איז, ווייל אויף זיך האָט דער טאַטע ניט געוואָלט זאָגען בודאות<sup data-n=\"107\">4</sup>.\nג. איך האָב אייך אַ סוד צו מגלה זיין, ח\"י אלול תרנ\"ה האָט מיר דער טאַטע אַריינגערופען און האָט מיר געלערנט (די הדרכה בדרכי החסידות), ער האָט מיר געזאָגט אַז ביי די רביים האָט זיך דאָס אָנגעהויבען צו צען יאָהר נאָר ביי מיר (כ\"ק אדמו\"ר שליט\"א) איז דאָס גיווען צו 15 יאָהר<sup data-n=\"108\">5</sup>, צוליב די נסיעות. און דער טאַטע האָט מיר מגלה סוד געווען, אַז אדמו\"ר הזקן האָט געהאַט מדי שנה בשנה די דריי חדשים, פון ח\"י אלול ביז י\"ט כסלו<sup data-n=\"109\">6</sup>, מסירת נפש אויף תיקון החב\"ד.\nח\"י תשרי חוהמ\"ס תרנ\"ו האָט מיר דער טאַטע אַריינגערופען, און האָט געזאָגט: היינט איז נשלם געוואָרען תיקון החכמה, ח\"י חשון האָט ער אָפּגעלייגט אויף כ' חשון<sup data-n=\"110\">7</sup>, (דאַמאָלסט האָב איך ניט געוואוסט דעם טעם<sup data-n=\"111\">8</sup>) האָט ער מיר געזאָגט אַז עס איז נשלם געוואָרען תיקון הבינה, י\"ט כסלו האָט ער געזאָגט היינט איז נשלם געוואָרען דעת, און האָט מיר אָנגעזאָגט צו האַלטען בסוד, אַז מען זאָל אפילו נישט דערקענען אויף מיר אַז איך האָב אַ סוד<sup data-n=\"112\">9</sup>.\nד. תרנ\"ו י\"ט כסלו האָט אאמו\"ר נ\"ע פאַרבראַכט, און האָט געזאָגט אַז אדמו\"ר האמצעי האָט געזאָגט<sup data-n=\"113\">10</sup> אַז פאַר לערנען חסידות אָן עבודת התפלה קריגט מען אַ שנעל אין נאָז פון טאַטען (אדמו\"ר הזקן), עס איז אַ חוצפה וקרוב הדבר לאמר שהעמיד צלם בהיכל, וביאר אאמו\"ר נ\"ע וואָס הייסט אַ רבי'ס אַ גלעט און וואָס איז אַ שנעל, ושאל ר' הענדל<sup data-n=\"114\">11</sup>: מיט וואָס דאַווענט מען? והראה אאמו\"ר באצבעו על לבו, ואמר: מיט דעם.\nה. אַז מען הערט חסידות פון",[["106","3","ראה מכתב כ\"ק אדמו\"ר מהורש\"ב נ\"ע מיום ד' ט\"ז כסלו תרס\"ב (אגרות­-קודש ח\"א ע' רנט): \"וקרוב הדבר אשר היום הזה הוא ר\"ה לדא\"ח\". וראה שיחת י\"ט כסלו תרס\"ד (ספר השיחות תורת שלום ס\"ע 43 ואילך): \"און אַזוי האָב איך אויך גישריבען אַמאָל. . אַז י\"ט כסלו איז ר\"ה פון חסידות כו'\"."],["107","4","להעיר שבהעתקת מכתב הנ\"ל (בהערה הקודמת) בשיחת כ' כסלו תרצ\"ב (לקו\"ד ח\"ד תשנט, ב) וב\"היום יום\" בתחילתו — נשמטו התיבות \"וקרוב הדבר\"<sup data-n=\"e9\">*</sup>."],["108","5","ראה גם ספר השיחות תש\"ד ע' 144. תש\"ה ע' 78. ע' 111 ואילך. ע' 124 ואילך."],["109","6","ראה גם שיחת יום ב' דחג הסוכות שנה זו (לעיל ע' 6)."],["110","7","ע\"ד חגיגת יום הולדת כ' מר­חשון תרנ\"ו — ראה רשימת היומן של רבינו מיום הנ\"ל — נדפס בסה\"מ תש\"ט ע' 86 ואילך."],["111","8","להעיר אשר כבר משנת תרנ\"ד ואילך התחיל רבינו לחגוג יחד עם אביו כ\"ק אדמו\"ר מהורש\"ב נ\"ע את יום הולדת כ' מר­חשון. — רשימת היומן של רבינו מיום י\"ט מר­חשון תרפ\"א — \"התמים\" חוברת ג ע' לב [קלב, ב]."],["112","9","להעיר מג' הדרגות בבעל סוד — ראה ספר השיחות תש\"ג ס\"ע 91 ואילך."],["113","10","ראה גם שיחת ליל שמחת תורה תש\"ז ס\"ב (לקמן ע' 72)."],["114","11","המשפיע החסיד והעובד ר' חנוך הענדל קוגל מפּלעשעניץ. ראה אודותו ספר השיחות תרפ\"ח­תרצ\"א ע' 32. וש\"נ."],["e9","*","ראה גם ד\"ה לכה דודי תשי\"ד ס\"ב (סה\"מ מלוקט ח\"א ע' מד) ובהערה 11, ושם שכ\"ק אדמו\"ר מהוריי\"צ אמר לכ\"ק אביו אדמו\"ר מהורש\"ב נ\"ע: \"מה שאצלך בדרך אפשר נעשה אצלי דבר ודאי\". עיי\"ש בארוכה."]]],[4301620177,"עמיצען וועלכער טוהט אין עבודת התפלה, קען זיין, אַז דער מקבל זאָל פאַרשטיין אַ זאַך וואָס דער משפיע פאַרשטייט נישט אין זיינע אייגענע רייד.\nאַז מען איז מקבל חסידות פון איינעם וואָס טוהט ניט אין עבודת התפלה איז דאָס סקילה ברוחניות.\nאצל אדמו\"ר האמצעי הי' תקנות אַז פון איינעם וועלכער טוט נישט אין עבודת התפלה זאָל מען נישט הערען קיין חסידות<sup data-n=\"115\">12</sup>, ור' הענדל הי' זוכר שלפעמים אַז מען פלעגט קומען אין אַ שטאָט טרעפען איינעם זאָגענדיק חסידות, פלעגט מען פרעגען: פון אים מעג מען הערען חסידות?\nו. אַ חסידישער רב פון סמיליאַן איז געקומען צום מהר\"ש און האָט זיך באַקלאָגט אויף די וואָס הערען פון איהם חסידות אַז זיי הערען נישט, און עס קומט ניט אַראָפּ בפועל. וענה לו אדמו\"ר מוהר\"ש: און וואָס טוהט זיך מיט דיר אַליין, אַ פיש שמעקט פון קאָפּ. — ער איז געווען אַ חסידישער איד, האָט דאָס גע'פּועל'ט אויף אים.\nז. אַ הכנה צו עבודת התפלה הויבט זיך אָן פון קריאת שמע שעל המטה<sup data-n=\"116\">13</sup>, אויך תיקון חצות אויב מען איז שייך צו דעם.\n(שאל הרש\"ל שי': וואָס הייסט שייך צו דעם? וענה כ\"ק אדמו\"ר שליט\"א:) איך מיין מצד בריאות הגוף. (שאל הרמ\"ש שי': צי איז דער שלאָפן ניט קיין הפסק ניט נוגע? וענה כ\"ק אדמו\"ר שליט\"א:) מען שלאָפט אַנדערש, עס איז שוין גאָר נוגע.\n(הרש\"ל שי' סיפר אַז ער האָט גיזעהן פּראָסטע אידען ריכטען אָפּ חצות מיט אַ מנין. ואמר כ\"ק אדמו\"ר שליט\"א:) באַ אידען איז ניטאָ קיין פּראָסטע.\nח. היינט איז ראש השנה, דער אויבערשטער זאָל העלפען עס זאָל נמשך ווערן. (ואמר הרש\"ל שי': און וואָס איז מכח גשמיות? וענה כ\"ק אדמו\"ר שליט\"א:) אידישע גשמיות איז רוחניות.\nאַז מען זאָל זיין האַלב פון דעם ווי מען ווייסט ווי מ'דאַרף זיין וואָלט שוין אויך געווען...\nט. מ'האָט אַמאָל געפרעגט ביים אַלטן רבי'ן, פאַרוואָס חסידים זינגען ביים דאַוונען<sup data-n=\"117\">14</sup>, וענה: ביים דאַוונען דאַרף זיין עס זאָל \"דערנעמען\", ער זאָל נתעורר ווערען, און אַז עס דערנעמט זינגט זיך.\nוסיים כ\"ק אדמו\"ר שליט\"א: מען דאַרף זינגען אַ ניגון עס זאָל \"דערנעמען\". ביי אַ ניגון דאַרף מען ניט שרייען, דאָס איז אַ קול כסיל, נאָר זינגען אַ פּנימיות'דיגען ניגון, אַז עס זאָל דערנעמען.",[["115","12","ראה גם שיחת ליל שביעי של פסח תש\"ז (לקמן ע' 114)."],["116","13","ראה גם ספר השיחות תש\"ה ע' 115."],["117","14","ראה שיחת י\"ט כסלו תש\"ח (לקמן ע' 180)."]]],[4301620178,"<h3>כ' כסלו תש\"ו </h3>\nא. יעדער איד גלויבט באמונה פשו­טה, אַז די אַלע ענינים וואָס פּאַסירען אין חיי האדם והנהגותיו בדבר היותר קל איז אַלץ בהשגחה פרטית.\nמורנו הבעש\"ט זאָגט<sup data-n=\"118\">1</sup> אַז אפילו דאָס וואָס אַ שטרייעלע אין גאַס ווערט פאַרוואַנדעלט פון איין אָרט אויף אַן אַנדער אָרט איז דאָס בהשגחה פרטית צוליב אַ כוונה עליונה, וואָס דער מענטש בעדאַרף פון דעם אַפולע לערנען אין לעבען.\nב. אין דעם דורכשניטליכען אידי­שען אויסשפּראַך איז דער אויסשפּראַך מסירת נפש אויך כולל מסירת הגוף, אָבער אין אמת'ן איז מסירת הגוף און מסירת הנפש צוויי זאַכען.\nדי עבודה פון מסירות הגוף איז מכשיר זיין דעם גוף דורך דעם קיום המצות, אַז דער גוף זאָל משתוקק זיין טאָן אַלץ וואָס מען בעדאַרף טאָן אין קיום המצוות מעשיות און מדות טובות און ניט וועלען טאָן אָט דאָס וואָס מען טאָר ניט טאָן עפ\"י תורה, און מסירות נפש איז איבערגעגעבען דעם \"רצון\" צו אלקות, דאָס מיינט איבערגעבען דעם למעלה מן השכל צו אלקות.\nג. הוד כ\"ק אאמו\"ר הרה\"ק זאָגט אין אַ פאַרבריינגען­מסיבה:\nדער רבי — הכוונה רבינו הזקן — דער ליטווישער גאון מקובל און חקרן, איז געוואָרען אַ איבערגעגעבענער חסיד ניט דורך די התפעלות פון אופנים און שרפים, נאָר דורך דעם גילוי המוחין פון דעם מעזריטשער מגיד.\nד. רבינו הזקן האָט גיזאָגט לכ\"ק אחיו מהרי\"ל<sup data-n=\"119\">2</sup>: דער רבי — געמיינט דעם הרב המגיד — האָט זיך דאָ למטה אין עשי' הגשמיות געפירט מיט דעם סדר פון די ספירות אין עולמות הרוחניים למעלה, איז דער וואָס איז געווען קלאָר אין דעם סדר גילוי הספירות בעולמות העליונים, איז פון די עניני הנהגה פון רבי'ן — הרב המגיד — האָט ער געקאָנט וויסען דעם זמן פון שעות היום אָדער שעות הלילה, על דרך ווי משה רבינו אַז ער איז געווען אין הימעל האָט ער געוואוסט ווען עס איז יום ולילה<sup data-n=\"120\">3</sup>.\nה. די שעה קבועה וואָס הרב המגיד האָט קובע געווען אויף צו חזר'ן די מאמרי תורה פון מורנו הבעש\"ט, אויך די סיפורים פון מורנו הבעש\"ט, וואָס הרב המגיד פלעגט איבערגעבען צו רבינו הזקן, איז געווען אין אַ שעה קבועה ומסודרה בחול, בשבת קודש ובמועד. איידער הרב המגיד פלעגט אָנהויבן דעם לימוד אָדער דעם סיפור, פלעגט הרב המגיד זאָגען בקול תחנה ותפלה: אל הוי' ויאר לנו<sup data-n=\"121\">4</sup>. און לסוף הלימוד אָדער לסוף הסיפור בגמר השעה של לימוד, פלעגט הרב המגיד זאָגען: יהי רצון שיאיר ויתגלה אור חי' יחידה בחב\"ד שבנפש בגילוי ובהצלחה.",[["118","1","ראה ד\"ה הטה אלקי תרצ\"ד (ספר המאמרים קונטרסים ח\"ב רעט, א). שיחת יו\"ד שבט תש\"ט. שיחת יום שמחת תורה ה'שי\"ת ס\"א (לקמן ע' 300. ע' 378). כתר שם טוב (הוצאת קה\"ת, תשנ\"ט) הוספות סימן קעט ואילך. וש\"נ."],["119","2","ראה אודותו: ספר השיחות תרפ\"ח­תרצ\"א ע' 68 הערה 31. וש\"נ. לקמן ע' 22."],["120","3","ילקוט שמעוני תשא רמז תו. מדרש תהלים יט, ג. וראה גם רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 227."],["121","4","תהלים קיח, כז."]]],[4301620179,"מורנו הבעש\"ט און הרב המגיד איז געווען דרכם בקדש, אַז ספירת העומר פלעגט יעדער פון זיי, בזמן נשיאותו, סופר זיין בתור עובר לפני התיבה בבית הכנסת. ווען הרב המגיד האָט סופר געווען ספירת העומר במנין לפני העמוד אין תפלת ערבית, ליל התקדש הוד שבהוד, האָט רבנו הזקן דערפיהלט דעם גילוי חב\"ד שבנפשו. און פון דאַן אָן האָט רבינו הזקן געזעהן במוחש דעם קיום תפלת וברכת הרב המגיד — אל הוי' ויאר לנו; און תפלתו וברכתו פון הרב המגיד אַז באַ אים, רבינו הזקן, איז מאיר חב\"ד שבנפשו בהתגלות אין הצלחה מופלגה אין זמן במחשבה און אין שרייבען בסגנון קצר המחזיק את המרובה."],[4301620180,"<h3>ליל ש\"ק וישב, כו כסלו, שבת חנוכה תש\"ו, בסעודה<sup data-n=\"122\">1</sup>. </h3>\nא. בכלל זיינען די מאמרים פון חנוכה געזאָגט געוואָרען בש\"ק חנוכה און ניט בימות החול. אָבער אַמאָל פלעגט טרעפען, אַז הוד כ\"ק אאמו\"ר הרה\"ק פלעגט איבערזאָגן דעם זעלבן מאמר ביחידות מיט ביאורים אין די ימות החול פון חנוכה.\nב. הוד כ\"ק אאזמו\"ר הרה\"ק הצ\"צ פלעגט פאַרבריינגען אין איינעם פון די חנוכה טעג מיט די קינדער<sup data-n=\"123\">2</sup>. הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש פלעגט אויך אַזוי טאָן, אָבער ער פלעגט עס מאַכן זייער בקיצור.\nבכלל פלעגט ביי אים אַלץ זיין ב­קיצור. הוד כ\"ק אדמו\"ר הרה\"ק האמצעי פלעגט אויך פאַרבריינגען בקיצור.\nג. הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש פלעגט צייטנווייז איבערזאָגן דעם מאמר פון שבת אין דערוואָכן מיט אַ ביאור פאַר זיינע קינדער<sup data-n=\"124\">3</sup>, און ער פלעגט זאָגן אַ טעם פאַרוואָס ער חזר'ט דעם מאמר.\nד. בכלל אַ מאמר איז אַ הוראה מלמעלה. דינסטאָג<sup data-n=\"125\">4</sup> מיטוואָך איז דאָך שייך צו שבת. אָבער מען דאַרף האָרעווען דינסטאָג, מיטוואָך דאָנער­שטאָג און פרייטאָג, אַז עס זאָל זיין באַ בימים<sup data-n=\"126\">5</sup>, ער זאָל קומען אין די טעג, ניט אַז די טעג זאָלן קומען אין איהם. דאָס הייסט ער זאָל ווערן עלטער.\nה. הוד כ\"ק אאמו\"ר הרה\"ק פלעגט צינדן די חנוכה ליכט אין הויז פון זיין מוטער<sup data-n=\"127\">6</sup>, כבוד אמי זקנתי הרבנית רבקה<sup data-n=\"128\">7</sup>, און אויך פרייטאָג ערב ש\"ק פלעגט ער דאָרט צינדן די חנוכה ליכט<sup data-n=\"129\">8</sup>, הגם ער האָט ניט געגעסן און געשלאָפן דאָרט.\nאין די ערשטע יאָהרן נאָך די הסתלקות פון הוד כ\"ק אאזמו\"ר הרה\"ק",[["122","1","נדפס עם הערות וציונים מכ\"ק אדמו\"ר נשיא דורנו בקונטרס ברוך שעשה נסים (קה\"ת, תשי\"א) ע' 19 ואילך. בהוצאה זו ניתוספו הערות ומ\"מ מהמו\"ל הבאות בחצאי מרובעות."],["123","2","[ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 252. הועתק ב\"היום יום\" כח כסלו."],["124","3","ראה גם ספר השיחות תרפ\"ח­תרצ\"א ע' 217]."],["125","4","אולי געמיינט דינסטאָג באַנאַכט — צו מיטוואָך. זע אויך \"היום יום\" כג כסלו."],["126","5","[ע\"פ חיי שרה כד, א."],["127","6","ראה רשימות היומן חנוכה תרצ\"ג (\"רשימות\" חוברת קעא ע' 6)."],["128","7","ראה אודותה בהנסמן לעיל ע' 14."],["129","8","ב\"רשימות\" שם: \"שבעש\"ק לא הי' מחכה שם החצי שעה אלא חוזר מיד לביתו\"."]]],[4301620181,"מוהר\"ש פלעגט הוד כ\"ק אאמו\"ר הרה\"ק עסן פרייטאָג צונאַכט און אויך שבת בייטאָג אין הויז פון כבוד אמי זקנתי הרבנית רבקה, אין די שפּעטער­דיקע יאָהרען פלעגט ער דאָרטן עסן בלויז שבת בייטאָג.\nו. הוד כ\"ק אאמו\"ר הרה\"ק פלעגט צינדן די חנוכה ליכט ביים טיר צווישען איין חדר צום צווייטען, און האָט ניט ליב געהאַט אַז אימעצער — ניט פון די בני בית — זאָל זיין דערביי<sup data-n=\"130\">9</sup>. נאָכן אָנצינדן פלעגט הוד כ\"ק אאמו\"ר הרה\"ק בלייבן זיצן ביי די ליכטלאַך אַרום אַ האַלבע שעה<sup data-n=\"131\">10</sup>. נאָכדעם פלעגט הוד כ\"ק אאמו\"ר הרה\"ק גיין אַהיים און לערנען אַ שעה, אַ שעה און אַ האַלב אַ שיעור גמרא<sup data-n=\"132\">11</sup>. ניט דוקא פון ענין חנוכה, נאָר על סדר הש\"ס וואָס ער האָט געלערנט.\nז. ווען<sup data-n=\"133\">12</sup> הוד כ\"ק אאמו\"ר הרה\"ק פלעגט דאַרפן אַוועקפאָהרן פון דער­היים חנוכה, פלעגט ער אָנזאָגן כבוד אמי הרבנית<sup data-n=\"134\">13</sup>, אַז הגם זי וועט הערן חנוכה ליכט בענטשן פון אַן אַנדערן — מהגברים — פונדעסטוועגן זאָל זי אַליין באַזונדער אָנצינדן חנוכה ליכט<sup data-n=\"135\">14</sup>.\nח. בבית רבי פלעגט מען זיך נוהג זיין אָנצוהייבן בענטשן חנוכה ליכט פאַר זיך נאָך פאַר בר­מצוה אַרום אַ יאָהר — צוליב חינוך. איך געדיינק ניט אויף זיכער ווען איך האָב אָנגעהויבן בענטשן חנוכה ליכט פאַר זיך, אין יאלטא<sup data-n=\"136\">15</sup> אָדער תיכף נאָך יאלטא.\nט. אַמאָל האָט אַ חסיד משבח געווען אַ צווייטן חסיד פאַר הוד כ\"ק אאזמו\"ר הרה\"ק הצ\"צ — עס איז דערביי אויך געווען הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש — און געזאָגט אויף איהם אַז ער לערנט חסידות. האָט הוד כ\"ק אאזמו\"ר הרה\"ק הצ\"צ געזאָגט: בעסער ווי גאָרניט, אָבער וואָס האָט חסידות איהם געלערנט.\nאיינמאָל האָט הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש משבח געווען פאַר הוד כ\"ק אאזמו\"ר הרה\"ק הצ\"צ איינעם אַז ער טוט אין חסידות. האָט הוד כ\"ק אאזמו\"ר הרה\"ק הצ\"צ געענטפערט: נו, און וואָס האָט חסידות געטאָהן אין איהם.\nי. הוד כ\"ק אאמו\"ר הרה\"ק האָט געזאָגט, אַז ער האָט מער מקבל געווען פון הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש ביחידות ווי ברבים, נאָר ער האָט דאָס ניט פאַרשריבן, ווייל ער האָט זיך פאַרלאָזט אויף זיין זכרון, שפּעטער האָט איהם באַנג געטאָהן וואָס ער האָט דאָס ניט פאַרצייכנט.\nהוד כ\"ק אאמו\"ר הרה\"ק איז געווען אַ בעל­זכרון.\nיא. חסידות איז מטהר טמאים. וואָס טמאים איז, דאַרף מען זאָגן בחשאי.",[["130","9","נתבאר בשיחת ש\"פ מקץ, זאת חנוכה, תשט\"ז."],["131","10","ראה \"רשימות\" שם. \"היום יום\" כה כסלו."],["132","11","ב\"רשימות\" שם: ש\"הי' לומד גמרא בסמוך להם\". וראה גם שיחת ליל ב' דחנוכה תשמ\"ב (התוועדויות ח\"ב ע' 598 ואילך)."],["133","12","ראה לקו\"ש ח\"ל ע' 312. שיחת וא\"ו תשרי תשל\"ה."],["134","13","הרבנית הצדקנית מרת שטערנא שרה. ראה אודותה — ספר השיחות תר\"פ­תרפ\"ז ע' 13 הערה 12]."],["135","14","צ\"ע בברכה או לא."],["136","15","בשנת תרמ\"ו (ראה מפתח מאמרי מהורש\"ב ע' 7 [בהוצאת תשמ\"א — ע' נח. לקמן ע' 369. ע' 395. וראה ספר השיחות שם הערה 11. וש\"נ)."]]],[4301620182,"נאָר אַ נשמה חדשה<sup data-n=\"137\">16</sup> דאצילות<sup data-n=\"138\">17</sup> — הכוונה על הוד כ\"ק רבינו הזקן — האָט געקענט פותח זיין די מעיינות.\nיב. אויף אַן אסיפה וואָס איז פאָר­געקומען אין פעטערבורג האָט הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש געזאָגט צו איינעם אַ רב: עשו'ן האָט מען אויך גערופן הרב<sup data-n=\"139\">18</sup>.\nער האָט דאָס איהם געזאָגט ברבים.\nיג. הוד כ\"ק אאמו\"ר הרה\"ק האָט דערציילט, אַז אַמאָל<sup data-n=\"140\">19</sup> האָט איהם גע­זאָגט הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש: מען דאַרף זיך צוהערן וואָס די ליכט­לאך — נרות חנוכה — דערציילן.\nיד. מען דאַרף די ווערטער, ניט נאָר די ווערטער, נאָר אויך די פתגמים, פאַרצייכענען. אַ וואָרט איז ממש מחי'.",[["137","16","ראה ספר השיחות תש\"ה ע' 127. שיחות תש\"ז: יט כסלו. ליל שש\"פ. רשימה ש\"פ נצבים. כ\"ט אלול, ער\"ה תש\"ח (לקמן ע' 91. ע' 98. ע' 111. ע' 150. ע' 157). אגרות­-קודש ח\"ט ע' קנג. ע' קסא. ועוד."],["138","17","ראה שיחת יום ב' דחג הסוכות שנה זו (לעיל ע' 6). וש\"נ."],["139","18","ראה גם אגרות­-קודש ח\"י ע' שצד. ספר השיחות תר\"פ­תרפ\"ז ס\"ע 83. אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ח ע' ר. ועוד."],["140","19","בעת הדלקת נרות חנוכה (כ\"ה בקובץ ליובאַוויטש שנה שלישית חוברת א' ע' 3)]."]]],[4301620183,"<h3>פורים תש\"ו </h3>\nא. ווען דער אַלטער רבי איז גע­קומען קיין וויטעבסק האָט מען אים שוין געהאַלטן פאַר אַ גאון, עס איז ידוע אַז צו 13 יאָר איז שוין דער רבי געוועזן אַ גאון<sup data-n=\"141\">1</sup>.\nווען זיין פאָטער ר' ברוך איז מיט אים געקומען משדך זיין אים אין וויטעפסק — האָבן די גאוני וויטעבסק שוין געוואוסט פון זיין גאונות. ביז 17 יאָר האָט זיך דער אַלטער רבי ניט מגלה געווען. און בערך צום 18'טען יאָהר האָט ער שוין געהאַט חברים, וואָס ער האָט מיט זיי געלערנט, אַזוי אַז מען האָט שוין געוואוסט פון זיינע גאונות<sup data-n=\"142\">2</sup>.\nווען ער איז אַלט געוואָרן אַכצן יאָהר האָט ער אָנגעהויבן זוכן שלימות, האָט אים דאַן דער פעטער מהרי\"ל<sup data-n=\"143\">3</sup> געזאָגט: לערנען קענסטו אַביסל אָבער חסידות ווייסטו גאָרניט (כידוע אַז אביו ר' ברוך ודודו הרב יוסף יצחק האָבען פון אים מעלים גיווען<sup data-n=\"144\">4</sup>. כידוע אַז דאַן האָט מען שוין געוואוסט פון חסידות, נאָר עס איז געווען בסתר, כידוע פון די צדיקים נסתרים — אויך דער פעטער הרב ר'",[["141","1","\"לעונת בר מצוה נכתר מהגאונים בתואר רב תנא הוא ופליג\" — אגרות­קדש ח\"ט ע' נז. שלשלת היחס בתחלת \"היום יום\". ובספר השיחות קיץ ה'ש\"ת ע' 59 שבמסיבת הבר מצוה של אדה\"ז הסמיכוהו כל הגאונים והכתירוהו בתואר \"רב\". וראה בית רבי ח\"א פ\"א (א, ב). ספר השיחות שם ע' 175."],["142","2","נוסחא אחרת: ביז 17 יאָר האָט זיך דער אַלטער רבי ניט מגלה געווען, חוץ מיט זיינע חברים וואָס ער האָט מיט זיי גערעדט אין תורה, אין אַכצענטן יאָר האָט אים דער פעטער מהרי\"ל געזאָגט [ההמשך בפנים]."],["143","3","ראה אודותו בהנסמן לעיל ע' 19. וש\"נ."],["144","4","ראה ספר השיחות תש\"א ע' 102. תש\"ה ע' 132 ואילך. לקמן ע' 68. ע' 255. ועוד."]]],[4301620184,"יוסף יצחק ואביו ר' ברוך היו מהנסת­רים<sup data-n=\"145\">5</sup>), איז דאַן דער רבי אַוועק קיין מעזריטש<sup data-n=\"146\">6</sup>.\nצוריק קומענדיק פון מעזריטש, האָט מען אים געפרעגט וואָס האָט ער גע­נומען אין מעזריטש<sup data-n=\"147\">7</sup>. האָט דער אַלטער רבי געזאָגט אַז אין מעזריטש האָט ער גענומען אַ נייעם דרך<sup data-n=\"148\">8</sup>, אַז מ'דאַרף וויסן אַז מען איז אַן עם הארץ, אַן עם הארץ איז אַ גרויסע מדריגה<sup data-n=\"149\">9</sup>, אַן עם הארץ טוט יעדער זאַך מיט אַ פשיטות ניט וויסענדיק קיין טעם וסברא פאַר­וואָס עס דאַרף אַזוי זיין, און<sup data-n=\"150\">10</sup> פון די פשיטות קומט מען צו צו תמימות.\nאויך האָט ער גענומען אין מעזריטש דעם ענין פון ניגון. וואָס אַ ניגון איז אויף אַרויסגיין פון וואַנען מען איז, און צוקומען דאָרט וואו מען דאַרף זיין<sup data-n=\"151\">11</sup>.\nב. דעם ערשטען פורים וואָס דער רבי איז געווען אין מעזריטש, איז ווען ער איז צוריקגעקומען האָט ער שוין געהאַט אַרום זיך יונגעלייט לומדים מופלגים. האָבען זיי ביי אים געפרעגט וואָס ער האָט דאָרט געהערט, ואמר להם<sup data-n=\"152\">12</sup>: דער",[["145","5","ראה ספר השיחות תש\"ה ע' 127 ואילך. שיחת ב' ניסן תש\"ח (לקמן ע' 192). ועוד. וראה גם שיחת יום א' דחג השבועות שנה זו (לקמן ע' 46)."],["146","6","באגרות­-קודש אדמו\"ר הזקן ח\"ב ע' לב: \"שבהיותי בן עשרים שנה בערך במשך זמן שהייתי בויטעפסק נסעתי משם למעזריטש\". וב\"הקדמת הרבנים בני הגאון המחבר\" לשו\"ע אדה\"ז (הועתק בבית רבי ח\"א פ\"ב (ב, א)): \"וכאשר היותו בן עשרים לרדוף. . לא מצא בכל עיונו כדי המספיק למלאות כל עמקי משאלותיו ובפרט בידיעת סתרי התורה וסודותי'. . מאת ה' היתה לו זאת שהורוהו. . לעלות לפני ולפנים להיכל קדשו של. . מו\"ר דוב בער נ\"ע מ\"מ דק\"ק מיזעריטש\". ובאגרות­-קודש ח\"ט ע' נג שבא להה\"מ בשנת תקכ\"א. ושם ע' נז: \"וכבן עשרים ע\"פ עצת אחיו הצעיר — בעל שארית יהודה — הוא נוסע להגאון המקובל המגיד ממעזריטש\". בספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 266 (הגדה של פסח עם לקוטי טעמים ומנהגים פיסקא בדיקת חמץ (ע' ב). \"היום יום\" יא מנחם אב) שאדה\"ז הלך למעזריטש בפעם הראשונה ביחד עם אחיו מהרי\"ל, בשנת תקכ\"ד. בספר השיחות תש\"ה ע' 132: \"ווען דער אַלטער רבי האָט באַדאַרפט ווערן אַ בן עשרים, איז נאָך פסח אין יאָר תקכ\"ה, האָט דער אַלטער רבי מחליט געווען. . צו פאָרן אין דער פרעמד. . אחי הגאון מהרי\"ל איז אַ בעל שכל הישר האָט ער געזאָגט, אַז איך זאָל גיין אין מעזריטש\"."],["147","7","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לקמן ע' 24. ע' 27 ואילך. ע' 29. ס\"ע 31. ס\"ע 32 ואילך. ע' 40. ע' 44. ע' 48. ע' 52. ע' 64. ע' 91. ס\"ע 99 ואילך. ס\"ע 103. ע' 112­111. ע' 114. ס\"ע 123 ואילך. ע' 130. ע' 132. ע' 149. ע' 151. ע' 161. ע' 170. ע' 199. ע' 232. ע' 244 ואילך. ע' 290. ע' 296. ע' 401. וראה לקמן ע' 208."],["148","8","נוסחא אחרת: צוריק קומענדיק פון מעזריטש האָט מען אים געפרעגט: וואָס איז חסידות? האָט ער געזאָגט: חסידות איז כמה ענינים. ערשטנס אַז מ'דאַרף וויסן [ההמשך בפנים]."],["149","9","נוסחא אחרת: אַן עם הארץ טוט יעדער זאַך מיט קבלת­עול ניט וויסענדיג קיין טעם וסברא פאַרוואָס עס דאַרף זיין אַזוי. און אויך, באַ אַן עם הארץ איז דאָ פשיטות און תמימות, און אַז פון פשיטות קומט מען צו, צו אמיתיות."],["150","10","נוסחא אחרת: און דער אַלטער רבי האָט אויפגעטאָן (מיט זיין מס\"נ?) אַז פון פשיטות זאָל מען צוקומען צו תמימות."],["151","11","נוסחא אחרת: ושאלו אותו: מהו המעלה בזה, והשיב: אַז דורך א ניגון גייט מען אַרויס פון זיך און מען ציט זיך צו העכער וואו מען בעדאַרף זיין."],["152","12","נוסחא אחרת: דער רבי האָט אונז מבאר געוועזען דעם \"ידע\", און מיר האָבען אין דעם \"ידע\" דערהערט דעם \"לא ידע\"; און פון דעם קומט מען צו צום אמת'ן \"ידע\" דורך עבודה. און דאָס איז דער אמת'ער \"ידע\"."]]],[4301620185,"רבי<sup data-n=\"153\">13</sup> האָט אונז מבאר געוועזען דעם \"ידע\", און מען איז צוגעקומען צו דעם \"לא ידע\"<sup data-n=\"154\">14</sup>, און דורך דעם \"לא ידע\" איז מען צוגקומען צו דעם אמת'ן \"ידע\"<sup data-n=\"155\">15</sup>.\n(והתחיל ואמר:) מיר חסידי חב\"ד זיינען ב\"ה היינט אויף אַ גוטען שטאַנד, אָבער עס פעלט נאָך אַ סאַך. אַמאָליגע חסידים זייינען געווען פאַראיינציגט מיט די חסידות וואָס זיי האָבן געלערנט, זיי זיינען געווען איין זאַך. זיי האָבען קיין סאַך נישט געלערנט, ווינציגער פאַרשטאַנען; בלויז יחידים זיינען געווען קלאָר אין אַפולע חסידות ובריבוי השכלה, אבל רובם של החסידים האָבען נישט געוואוסט קיין סאַך חסידות, אָבער דאָס וואָס זיי האָבען געלערנט איז געווען איין זאַך מיט זיי, נישט קיין צוויי זאַכן<sup data-n=\"156\">16</sup>.\nמען איז געפאָרן צום רבי'ן איינמאָל אין יאָר, איינמאָל אין צוויי יאָר, איינ­מאָל אין דריי יאָר; מען האָט געהערט פון רבי'ן אַ וואָרט — האָט מען מיט דעם וואָרט געלעבט, ער איז מיט דער חסידות געווען איין זאַך. אין גאַס, אין קראָם, ביים עסען, ער האָט געלעבט מיט דעם.\nאָבער היינט מען פאַרשטייט אַ סאַך מער, מ'לערנט חסידות, אָבער דער חסידות לערנט אים גאָר ניט — ער מיט די חסידות זיינען צוויי זאַכן. עס קומט צום דאַוונען זשאַלעוועט ער ניט קיין קנאַק מיט'ן פינגער<sup data-n=\"157\">17</sup>, אַ קלאַפּ אין טיש — אָבער עס איז לא נגע ולא פגע<sup data-n=\"158\">18</sup>. און מ'דאַרף וויסן אַז דאָס איז היפך הכוונה.\nג. זייענדיק אויף יחידות בשנת תרנ\"ח, האָט מיר דער טאַטע דערציילט וואָס ער האָט געהערט פון זיידען בשם הצ\"צ, אַז די עבודה פון אַלטען רבי'ן איז געווען אויף מגלה זיין ביי יעדען דעם חב\"ד שבנשמה. אַז עס איז אַריינגע­קומען צו איהם אויף יחידות אַ פשוטער איד, האָט ער איהם אַ סמאָליע (כן הי' הלשון של כ\"ק אדמו\"ר מהר\"ש נ\"ע) געטאָן מיט זיין חב\"ד שבנשמה.\nדער אַלטער רבי צוריק קומענדיג פון מעזריטש<sup data-n=\"159\">19</sup> קיין וויטעבסק, וועלענ­דיג נעמען די לומדישע יונגעלייט, האָט ער פאַר זיי געזונגען אַ ניגון. כידוע אַז דער אַלטער רבי האָט געהאַט צען ניגונים<sup data-n=\"160\">20</sup>, און מיט דעם ניגון וואָס ער האָט פאַר זיי געזונגען זיינען זיי געקו­מען צו דביקות און זיינען אויסגעגאַנגען אַזוי ווי אַ ליכט, און דאַן האָט ביי זיי מאיר געווען דער אור התורה, און עס איז ביי זיי פאַרענטפערט געוואָרען אַלע שאלות וקושיות. ולאח\"ז בהמשך הזמן זיינען זיי אינמיטן איינגעשלאָפען גע­וואָרען.\nאון דאָס קען נאָר מאַכן אַ רבי, וואָס",[["153","13","הרב המגיד."],["154","14","ע\"פ מגילה ז, ב."],["155","15","ראה גם סד\"ה וקבל היהודים תשי\"א (סה\"מ מלוקט ח\"ג ע' עח). שיחת פורים תשי\"א (תורת מנחם — התוועדויות ח\"ב ע' 310)."],["156","16","ראה שיחת יום א' דחג הפסח שנה זו ס\"ב (לקמן ע' 29)."],["157","17","ראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 84. שיחת י\"ט כסלו תש\"ז. י\"ב תמוז תש\"ח (לקמן ע' 96. ע' 249). שיחת ש\"פ לך לך תשי\"א (תורת מנחם התוועדויות ח\"ב ע' 80)."],["158","18","ראה שיחת ליל ב' דר\"ה תש\"ח סוס\"ד. יום ב' דחג השבועות תש\"ט סוסכ\"א (לקמן ע' 161. ע' 332)."],["159","19","ראה הערה 7."],["160","20","ראה שיחת יום א' דחה\"פ שנה זו (לקמן ע' 29). ספר השיחות תרפ\"ח­תרצ\"א ס\"ע 181. אגרות­-קודש ח\"ג ע' תמד (הועתק ב\"היום יום\" כה תשרי). ועוד."]]],[4301620186,"ער איז אַ עצמי<sup data-n=\"161\">21</sup>. אַ עצמי קען מאַכן, מאיר זיין דעם חב\"ד שבנשמה.\nוכמעשה הידוע<sup data-n=\"162\">22</sup> מר' אייזיק<sup data-n=\"163\">23</sup> עם הצ\"צ במאמר על שלשה דברים העולם עומד שאמר הצ\"צ בתחלת קבלת הנשיאות, אותו המאמר ששמע מאדמו\"ר הזקן בהיותו ילד, כידוע<sup data-n=\"164\">24</sup> שהלך אַז הצ\"צ לבקר את הר' אייזיל, ויהב לי' ידי' ואוקמי'<sup data-n=\"165\">25</sup>, ואמר לו אז הפי' ע\"ז בקבלה<sup data-n=\"166\">26</sup>. ואמר אַז אח\"כ ר' אייזיק: 50 יאָהר אַז איך האָרעווע אין חסידות, און איך בין נאָך ניט צוגעקומען אפי' כאצבע קטנה; באַ אונז איז אורות געשאָנקענע און כלים ניט קיין אויס­געאַרבעטע, און באַ אים איז אורות עצמיים און כלים אויסגעאַרבעטע.\nד. כידוע איז ר' אייזיק געווען אַ גרויסער גאון, און זיין גאונות האָט גע'שם'ט ניט נאָר אין וויטעבסק און אין מינסק, נאָר מ'האָט אויך געזאָגט זיין תורה אין ווילנא. און ווען ער איז דאָס ערשטע מאָל צוריק געקומען פון ליאָזנא האָט מען ביי אים געפרעגט: וואָס האָסטו דאָרט געהערט, תורה האָסטו דאָך אַ סאַך. והשיב להם: געהערט האָב איך ווינציק נאָר געזען האָב איך אַ פולע, איך האָב געזען דעם אור התורה, די גילויים ווי עס איז געווען אין ביהמ\"ק<sup data-n=\"167\">27</sup>. ושאלו אותו: ווי אַזוי קען מען דאָס זען דעם אור התורה, והשיב להם: אין זוהר<sup data-n=\"168\">28</sup> שטייט עס איז פאַראַן עינין סתימין ואזנין אטומים<sup data-n=\"169\">29</sup> דערפאַר זעט מען ניט און מען הערט ניט, אַז מ'האָט ניט קיין בלינדע אויגן און מ'האָט ניט קיין טויבע אויערן — קען מען הערן און זען כעין האור בבית המקדש.\n(ואמר כ\"ק אדמו\"ר שליט\"א:) אויף זאָגען דעם וואָרט דאַרף מען זיין אַ ר' אייזיל. און מיר ווינטשן זיך היינט: הלוואי זאָלן מיר חאָטש נאָכזאָגן אַ וואָרט פון אַ אַלטען חסיד מיט אַ פנימיות און מיט אַ דערהער וואָס האַלטן דערביי ווייס נאָר דער אויבערשטער אַליין. וואָס באמת האָבען מיר גאָרניט און מיר זיינען גאָרניט, מען באַנוגענט זיך מיט דעם וואָס עס איז דאָ. אַ קבצן פרייט זיך ווען אַ גביר גיט איהם שלום עליכם.\nאַמאָל פלעגט מען זאָגען אַ וואָרט אויף די וואָס זאָגען תורה און טוען ניט אין עבודה, פאַרוואָס ביזטו מגנה תורה, עס איז תורה טהורה בכלי מאוסה, עס",[["161","21","ראה גם ספר השיחות תורת שלום ע' 189. ספר השיחות תרפ\"ח­תרצ\"א ע' 89. וש\"נ."],["162","22","רשימות היומן של רבינו ט' תמוז תרנ\"ח \"התמים\" חוברת ג ע' כב [קכז, ב] ואילך. אגרות­-קודש ח\"ד ע' תקז ואילך. רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 235. רשימת היומן סיון­מנ\"א תרצ\"ב (\"רשימות\" חוברת קעה ע' 3 ואילך). ספר השיחות תרצ\"ו­חורף ה'ש\"ת ס\"ע 3 ואילך. שם ע' 238. ספר השיחות קיץ ה'ש\"ת ע' 103 ואילך. תש\"א ס\"ע 146 ואילך."],["163","23","הרה\"ג והרה\"ח ר' יצחק אייזיק בר' מרדכי הלוי עפשטיין מהאמיל. מחסידי אדמו\"ר הזקן, אדמו\"ר האמצעי ואדמו\"ר הצ\"צ. אודותו — ראה ספר השיחות תרצ\"ו—חורף ה'ש\"ת ע' 4 וש\"נ. שם ע' 237 ואילך. ובארוכה — \"תולדות הרה\"ח ר' יצחק אייזיק\" (קה\"ת — אה\"ק, תש\"מ. תשמ\"ז). וראה לקמן ע' 132. ע' 313. ע' 410 ואילך."],["164","24","\"התמים\", אגרות­-קודש וספר השיחות קיץ ה'ש\"ת שם."],["165","25","ראה ברכות ה, ב."],["166","26","ראה ספר השיחות קיץ ה'ש\"ת שם."],["167","27","בנוסחא אחרת נוסף: און עס איז פאַר­ענטפערט געוואָרען די קשיות, און דאָס איז תורה לשמה."],["168","28","ראה זח\"א כח, א. ח\"ב קצו, א. ח\"ג רכב, א (ברע\"מ). ועוד. וראה גם שיחת חג השבועות תרצ\"ד סי\"ז. לקמן ע' 115."],["169","29","נוסחא אחרת: אודנין דלא שמעין."]]],[4301620187,"דאַרף זיין ווי דער טאַטע זאָגט: \"טאָפּאָראַ דאָ פּלאַחאַ\"<sup data-n=\"170\">30</sup>.\nה. דער רבי זייענדיק אין פּעטער­בורג אין פּעטעראָפּאָוואַלסקי קרעפּאָסט, זיינען געקומען צו אים דער בעש\"ט און דער מגיד איהם מבקר זיין און מחזק זיין<sup data-n=\"171\">31</sup>. האָט דער רבי זיי געזאָגט<sup data-n=\"172\">32</sup>: איך דאַרף ניט קיין חיזוק ווייל איך האָב אויף זיך גענומען מסירת הגוף<sup data-n=\"173\">33</sup>, נאָר מיט מיין מסירת הנפש וויל איך אויס'פּועל'ן אַז די אַלע וואָס וועלן גיין אין דעם דרך זאָלן מצליח זיין<sup data-n=\"174\">34</sup>, און דער דרך זאָל האָבן הצלחה ביז ביאת המשיח, און אויף דעם דאַרף איך האָבן חיזוק; און זיי האָבן אים צוגעזאָגט. און ווען דער רבי איז צוריק געקומען פון פּעטערבורג האָט ער געזאָגט, אַז איך האָב פון זיי אויף דעם בטוחות, נאָר איך האָב אַ בקשה אַז מיט די מנגדים זאָל מען זיך כלל ניט מתווכח זיין, און ניט מתפאר זיין זיך.\nוהתחיל לדבר כ\"ק אדמו\"ר שליט\"א, שכמו\"כ צריכים להתנהג: מ'דאַרף זיך מיט די מנגדים כלל ניט מתווכח זיין; מ'דאַרף זיך פירען אַזוי אַז מ'זאָל זעהן דעם דרך הטוב. אויב יענער לאָזט זיך — דאַרף מען טאָן אַ אידען אַ טובה. און אויב ער איז אַ שוטה אַ טיפש, און במילא שוין אויך דאָס וואָס עס שטייט ווייטער<sup data-n=\"175\">35</sup> (רשע וגס הרוח), דאַרף מען ניט. מיט אַ שוטה אַ פתי איז אפילו לאחר ק\"כ שנה אין ג\"ע אויך ניט באַקוועם צו זיין צוזאַמען.\nאין אַ עת צרה, ר\"ל, שרייט מען דאָך: טאַטע! זיידע! מען דאַרף זיך מכין זיין אויף זאָגען דעם אַלטען רבי'נס ניגון, און מען דאַרף זיך מצייר זיין ווי מען איז אין האַדיטש אויפן אהל און מען קלאַפּט אָן אין טיר און מ'זאָגט: רבי!<sup data-n=\"176\">36</sup>\nו. איך וויל ריידען צו די תלמידי התמימים ובפרט צו די תלמידים וואָס לערנען מיט אַנדערע. מ'וואָלט באַדאַר­פען ריידען אין דעם בארוכה, נאָר מ'וועט ריידען דברים קצרים.\nאַלע ענינים הן אין תורה הן אין יראת שמים הן אין הדרכה, דאַרפען זיין מיט אַ פנימיות, אָן רעש, אָן אַליאַרעם, אָן דעם \"אַהאַ\". דאָס ערשטע דאַרף מען טאָן מיט זיך אַליין — מען זאָל זיך אַליין מתקן זיין<sup data-n=\"177\">37</sup>; און דאָס וואָס מען וויל מתקן זיין באַ דעם תלמיד זאָל זיין אָן רעש. אפילו די קינדער וואָס קענען ניט עסען אין די היימען — זאָלען זיי ניט עסען, אָבער אָן דעם \"אַהאַ\", ניט מעיז זיין אביו ואמו. איר תלמידי התמימים ווייסט גאָרניט וואָס מען ערוואַרט נאָך צו זען דורך אייך — מען שטעלט אויף אייך אויס אַ גרויסען צעטעלע — איר מוזט אַלעס טאָן מיט אַ פנימיות, וועט דער אויבער­",[["170","30","{6} הקרדום (הגרזן) על העץ. ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 198. וש\"נ. לקמן ע' 188."],["171","31","ראה בית רבי ח\"א פט\"ז בהערה (לא, א). לקו\"ש ח\"ל ע' 170."],["172","32","במקומות שצויינו בהערה הקודמת איתא שרבינו הזקן שאל אותם למה מגיע לו שישב במאסר ומה תובעים ממנו."],["173","33","ביאור ענין \"מסירת הגוף\" — ראה שיחת כ' כסלו שנה זו ס\"ב (לעיל ע' 19)."],["174","34","ראה אגרות­-קודש ח\"ד ס\"ע רסד ואילך."],["175","35","אבות פ\"ד מ\"ז."],["176","36","נוסחא אחרת: כ\"ק אדמו\"ר שליט\"א אמר שהוא אומר זאת אז חסידים זאָלען נישט מיינען אַז זיי זיינען עלענד."],["177","37","נוסחא אחרת: יעדער דאַרף וויסען ווער ער איז. . אַ חסידישער יונגערמאַן ווייסט אַז מען דאַרף טאָן אין מדות וכו' נאָר מען לייגט אָפּ אויף מאָרגען, מען דאַרף ניט אָפּלייגן."]]],[4301620188,"שטער אייך העלפען איר וועט האָבען הצלחה אין אייער אַרבעט.\nדער אויבערשטער זאָל דערפרייען אַלע צו?ראָכענע הערצער. דער אויבערשטער זאָל העלפען אַז דאָס זאָל זיין דער לעצטער פורים אין גלות, און אַלע אידען זאָלען זיין אין ארץ ישראל ווי מ'דאַרף זיין, און עס זאָל זיין חי — געלעבט."],[4301620189,"<h3>שיחות חג הפסח </h3>\n<h4>סדר הראשון של חג הפסח תש\"ו </h4>\nווען דער אַלטער רבי איז געקומען דעם ערשטן מאָל פון מעזריטש<sup data-n=\"178\">1</sup> — וואָס אין דעם הילוך פון מעזריטש איז ער געווען גאָר באופן אחר — אין וויטעפסק מקום מגורו, איז געווען — ותהום כל העיר<sup data-n=\"179\">2</sup>. אַז מען האָט אים געפרעגט, וואָס האָט ער גענומען אין מעזריטש, האָט דער אַלטער רבי געענטפערט<sup data-n=\"180\">3</sup>, אַז אין מעזריטש האָט ער זיך דערוואוסט דריי זאַכן: וואָס דער אויבערשטער איז, וואָס אידן זיינען, ישראל אורייתא וקוב\"ה כולא חד<sup data-n=\"181\">4</sup>, און — וואָס אַ ניגון איז. דעם ערשטן פסח קומענדיג פון מעזריטש, ביי דעם צווייטן סדר, האָט ער זייער פיל געזונגען<sup data-n=\"182\">5</sup>.\nאח\"כ צוה כ\"ק אדמו\"ר שליט\"א לנגן, אחרי שניגנו איזה ניגונים חבדיי\"ם מקובלים, אמר כ\"ק אדמו\"ר שליט\"א: אין די ניגונים שפּיגלט זיך אָפּ דער חסידישער \"אני\".\n<h4>יום א' דחג הפסח תש\"ו בסעודה </h4>\nא. ווען דער אַלטער רבי איז געקו­מען דעם ערשטען מאָל פון מעזריטש האָט ער געזאָגט<sup data-n=\"183\">1</sup>, אַז אין מעזריטש האָט מען אים מגלה גיווען, וואָס ער איז און צוליב וואָס זיין נשמה איז אראָפּגע­קומען אויפ'ן מאַרק<sup data-n=\"184\">2</sup>. מען האָט אים מגלה גיווען אַז זיין נשמה איז חכמה דאצילות<sup data-n=\"185\">3</sup> און וואָס איז די כוונה פון זיין שליחות דאָ למטה. וויסענדיג וואָס ער איז און וואָס איז די שליחות פון זיין ירידת הנשמה למטה, האָט ער זיך אָפּגעשעמט און אָנגעהויבן זיך פירן בהתגלות<sup data-n=\"186\">4</sup>.",[["178","1","לפני חג הפסח תקכ\"ה (ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 265. ס\"ע 266)."],["179","2","ע\"פ רות א, יט."],["180","3","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["181","4","ראה זח\"ג עג, א."],["182","5","ראה שיחות יום א' דחה\"פ וליל א' דחה\"ש שנה זו (לקמן ע' 29. ע' 44)."],["183","1","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["184","2","ראה רשימה דש\"פ נצבים תש\"ז (לקמן ע' 150)."],["185","3","ראה שיחת יום ב' דחג הסוכות שנה זו (לעיל ע' 6). וש\"נ."],["186","4","ראה גם שיחת ליל שביעי של פסח תש\"ז (לקמן ע' 111)."]]],[4301620190,"ווען דער אַלטער רבי איז געקומען דעם ערשטען מאָל אין וויטעבסק איז געווען ותהום כל העיר<sup data-n=\"187\">5</sup>. אין וויטעבסק זיינען געווען פיל לומדים, גאונים, זיינען זיי נתפעל געוואָרן פון דעם אַלטען רבי'נס גאונות.\nדער אַלטער רבי האָט דערציילט, אַז ער אַליין האָט ניט פאַרשטאַנען, פאַר­וואָס ער האָט ניט געהאַט דערפון אַ הרגש גאוה, און ער האָט געקלערט, אפשר איז ער ביי זיך אַזוי הויך אַז דאָס איז ביי אים ניט תופס מקום, אָבער אַז ער איז נאָכדעם געגאַנגען אין מעזריטש און האָט זיך דערוואוסט אַז זיין נשמה איז חכמה דאצילות — איז דאָס ביי אים רעכט געוואָרן, ווייל חכמה דאצילות ווייס וואָס זי איז, און חכמה דאצילות דערהערט אַז די גאַנצע חיות העולמות איז מער ניט ווי אַ הארה בעלמא.\nבכלל ביז איצטער האָבען די רביים מעלים געווען צו דערציילן סיפורים, ווייל מ'האָט געוואָלט אַז ביי חסידי חב\"ד זאָל אַלץ זיין מצד המוחין, אפי' התעוררות המדות זאָל אויך זיין מצד המוחין, אָבער היינט<sup data-n=\"188\">6</sup>... אָבער...\nדאָס וואָס איך דערצייל איז אַלץ וואָס איך האָב געהערט פון טאַטן און דער טאַטע פון דער זיידע און נאָך העכער.\nבאַ די רביים איז גיווען אַ קביעות צו דערציילען סיפורים פון די התנהגות פון אַלטן רבי'ן בימי נערותו, דער אַלטער רבי האָט דערציילט צום מיטעלן רבי'ן און צום צמח צדק וואָס האָט מיט אים פּאַסירט בימי ילדותו און ווען ער איז געווען אַ אברך.\nדער צמח צדק זייענדיג אַלט 9 יאהר האָט שוין אָנגעהויבען פאַרשרייבען רשימות פון די סיפורים וואָס ער האָט געהערט.\nדער אַלטער רבי האָט דערציילט דעם מיטעלן רבי'ן און צמח צדק, אַז מימי ילדותו האָט ער קיינמאָל ניט געהאַט קיין קושיות אין תורה. ד. ה. זיין לערנען איז ניט געווען באופן של קושיות און תירוצים, נאָר ער האָט יעדען ענין אין תורה געלערנט גלייך כהלכתו. אויב ער האָט יע געהאַט אַ קשיא איז דאָס פאַרבליבן אַ קשיא, וואָס דאָס איז ניט געווען מצד חסרון המקבל נאָר מצד העלם המשפיע, וואָס דאָס גייט אַריין אין כלל — יתרץ קושיות ואבעיות.\nקומענדיג אַהיים — אין וויטעבסק — דעם ערשטן מאָל פון מעזריטש און וויסנדיג פון דעם גרויסן אחריות פון זיין נשמה שליחות, האָט דער אַלטער רבי מייקר גיווען כל רגע ורגע און האָט אָנגעהויבן טאָן און מקרב זיין אידען, ניט נאָר די וואָס זיינען שייך צו חב\"ד, און ניט נאָר די וואָס זיינען שייך צו מדות חג\"ת, נאָר אויך די וואָס זיינען שייך צו נה\"י, אידן וואָס זיינען שלמים בתורה ומצוה, גאָר פּשוטע אידן<sup data-n=\"189\">7</sup>, וואָס די פּשטות פון אַ פּשוטען אידן נעמט זיך פון פּשיטות הנשמה, וואָס פּשיטות הנשמה האָט אַ שרש אין פּשיטות העצמות<sup data-n=\"190\">8</sup>.\nוועלנדיג מקרב זיין אויך די פּשוטע אידן, האָט דער אַלטער רבי ממציא געווען דעם ענין פון ניגון, וואָס דורך ניגונים וועט ביי זיי נתגלה ווערען שרש",[["187","5","ע\"פ רות א, יט."],["188","6","ראה גם לקו\"ש ח\"כ ע' 387."],["189","7","ראה גם לקמן ע' 169. ע' 282. ע' 285. 291."],["190","8","ראה גם שיחת ליל א דחגה\"ס שנה זו (לעיל ע' 3). וש\"נ."]]],[4301620191,"נשמתם. דער אַלטער רבי איז דאָך געווען חכמה דאצילות, האָט ער מחבר געווען די עשרה ניגונים<sup data-n=\"191\">9</sup>, וואָס זיינען מסודר עפ\"י חכמה דאצילות<sup data-n=\"192\">10</sup>.\nדעם ערשטן פסח וואָס דער אַלטער רבי איז געקומען פון מעזריטש<sup data-n=\"193\">11</sup>, בעת דעם צווייטען סדר, זיינען זיך צונויפ­געקומען אַלע לומדים און גאונים פון שטאָט, האָט דאַמאָלסט דער אַלטער רבי געזונגען ניגונים, וואָס דורך די ניגונים האָט ביי יעדערן געלויכטן זיין שרש נשמה.\nוסיים כ\"ק אדמו\"ר שליט\"א: אָט דאָס איז אַ חסידישער ניגון, וואָס דאַרף מעורר זיין דעם גילוי הנשמה.\nב. ביי אַלטע חסידים איז געווען אַ קביעות צו לערנען חסידות און טאָן אין עבודת התפלה, דאָס איז ביי זיי געווען בפשיטות, אַז אָן דאַוונען קען מען קיין חסיד ניט זיין. מען מיינט ניט אָן דאַוונען כפשוטו ח\"ו, נאָר אַז מען איז זיך ניט עוסק אין עבודת התפלה. אַמאָל האָט מען ווייניגער געלערנט חסידות און ווייניגער געוואוסט, איך האָב געקענט אַלטע חסידים וועלכע האָבן געוואוסט נאָר געציילטע מאמרים, אָבער דאָס וואָס מען האָט געוואוסט האָט מען געלעבט אין דעם<sup data-n=\"194\">12</sup>, היינט לערענט מען מער און מ'ווייס מער, אָבער עס פעלט עבודת התפלה עס פעלט דער הרגש פנימי, ידיעה און חיות זיינען צוויי בעזונדערע זאַכן.\nג. רשב\"ץ<sup data-n=\"195\">13</sup> האָט אַלעמאָל מכיר טובה גיווען פאַר דעם זכות וואָס מען פלעגט איהם אַריינלאָזן צו די פאַר­בריינגעניש פון אַלטע חסידים. אַמאָל פלעגט מען דאָך ניט אַריינלאָזן צו די חסידישע פאַרבריינגעניש נאָר יונגע­לייט, אָבער די בחורים פון ישיבה — ווי עס איז ידוע אַז אין ליובאַוויטש איז געווען אַלעמאָל אַ ישיבה<sup data-n=\"196\">14</sup>, אויך די זיצער — פלעגט מען ניט אַריינלאָזן. רשב\"ץ, ווייל ער איז געווען אַ תלמיד און אַ מחונך פון החסיד ר' מיכל אַפּאָצ­קער<sup data-n=\"197\">15</sup>, פלעגט מען אים יאָ אַריינלאָזן.\nרשב\"ץ האָט דערציילט וואָס ער האָט געזען בעת אַ חסידישער פאַרבריינגען אין ליובאַוויטש וואו עס זיינען געזעסן ר' הלל פּאַריטשער<sup data-n=\"198\">16</sup> און ר' אייזיל האָמ­ליער<sup data-n=\"199\">17</sup>, בעת'ן פאַרבריינגען האָט ר' הלל זיך אָפּגערופן, אַז ער איז מקנא שלום יוסף'ן דעם בויער — בונה — פּלאָטניק.",[["191","9","ראה שיחת פורים שנה זו (לעיל ע' 24). וש\"נ."],["192","10","ראה שיחת פורים תש\"ז (לקמן ע' 101), שעשרת הניגונים הם כנגד העשר ספירות."],["193","11","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["194","12","ראה גם שיחת פורים שנה זו ס\"ב (לעיל ע' 24)."],["195","13","ראה אודותו לעיל ע' 12. וש\"נ."],["196","14","ראה אגרות­-קודש חלק ב ע' קז. \"רשימת המאסר\" — ספר השיחות תר\"פ­תרפ\"ז ע' 255."],["197","15","ראה \"התמים\" חוברת ע' עד [לח, ב] ואילך. ספר השיחות קיץ ה'ש\"ת ע' 91. תש\"א ע' 96 ואילך. שיחת י\"ב תמוז תש\"ז (לקמן ע' 137)."],["198","16","הרב ר' הלל בר' מאיר הלוי מאליסאוו, הידוע בשם \"ר' הלל פּאַריטשער\" (תקנ\"ה — יא מנ\"א תרכ\"ד). ראשי פרקים מתולדותיו — ראה פלח הרמון על ספר בראשית ועל ספר שמות — הוצאת קה\"ת בתחילתם. ספר השיחות תורת שלום ע' 13. 109. ספר השיחות תר\"פ­תרפ\"ז ע' 52 הערה 12. תרפ\"ח­תרצ\"א ע' 30 הערה 10. וש\"נ. תרצ\"ו­חורף ה'ש\"ת ע' 221. ע' 231 ואילך. ע' 236 ואילך. ע' 240 ואילך. ע' 276. ע' 351 ואילך. אגרות­-קודש ח\"ג ע' שכט ואילך. אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' קלב. לקמן ע' 259. ע' 410 ואילך."],["199","17","ראה אודותו לעיל ע' 25 הערה 23."]]],[4301620192,"ר' שלום יוסף איז געווען אַ אַלטער איד פון דעם אַלטן רבי'נס חסידים, נאָר זייער אַ פּשוטער, זיין פרנסה איז גע­ווען, וואָס ער איז געווען אַ בויער, אַ פּשוטער אַרבעטער. ווען ר' הלל איז נאָך געווען אַ יונגערמאַן, איז ר' שלום יוסף שוין געווען אַ שטאַרקער זקן. ר' שלום יוסף פלעגט אַ סאַך דאַוונען. איינמאָל האָט ר' הלל געזען ווי ר' שלום יוסף האָט שטאַרק געוויינט אין דאַוונען, האָט אים ר' הלל נאָכדעם געפרעגט, פאַרוואָס האָסטו געוויינט אין דאַוונען, האָט אים ר' שלום יוסף געענטפערט, איך האָב געהערט פון רבי'ן<sup data-n=\"200\">18</sup> אַז באַ יעדען איז זיין נשמה פון חכמה דאצילות, היינט אַז איך האָב אַ טראַכט געטאָן, חכמה דאצילות אין אַ ליידאַק<sup data-n=\"201\">19</sup>, וואָס פאַר אַ רחמנות עס איז אויף חכמה דאצילות צו זיין אין אַזאַ ליידאַק, האָב איך זיך פאַנאַנדערגעוויינט.\nבעת ר' הלל האָט געזאָגט ביים פאַרבריינגען אַז ער איז מקנא ר' שלום יוסף'ן, האָט ער זיך שטאַרק פאַנאַנדער­געוויינט. ווען רשב\"ץ האָט מיר איבער­דערציילט דעם סיפור האָט ער געזאָגט, אַז ר' הלל'ס געוויין איז געווען ע\"ד ווי געה בבכיה<sup data-n=\"202\">20</sup> וכו'.\nהאָט ר' אייזיל זיך אָפּגערופן: איך בין מקנא ר' הלל'ן, אַזאַ משכיל, אַזאַ ידען — ווי עס איז ידוע אַז ר' הלל איז געווען קלאָהר אין כתבי האריז\"ל אותיות­ווייז — און אַזאַ עובד, זאָל מקנא זיין די פשטות פון שלום יוסף'ן דעם בויער.\nויאמר ר' הלל לר' אייזיל, נו.. וענה ר' אייזיל: דאָס קען מען ניט מאַכן, אַז מ'האָט דאָס האָט מען דאָס, דאָס איז נאָר מצד געגועי הנשמה, וואָס אַ נשמה ציט לאלקות, און אויף דעם האָרעווען מיר אַז מיר זאָלן זוכה זיין צו דעם.\nד. (עס איז דאָ אַ וואָרט מקובל רבי מפי רבי, אַז) ווען דער אַלטער רבי האָט זיך דערוואוסט די אחריות פון זיין שליחות, האָט ער זיך ניט באַרואיגט ביז ער האָט שוין געהאַט אַ אייגענעם מנין, אַז ער האָט געהאַט אַ אייגענעם מנין יונגעלייט, האָט ער געוואוסט אַז ער האָט שוין עפּעס אויפגעטאָן אין זיין נייעם דרך.\nב\"ה, מיר אין אַמעריקא האָבען שוין אַ מקום מנוחה, אַזוי איז דאָך דער הו­האַ פון אַמעריקאַנער גשמיות'דיגן לעבן, דער רעש וכו', אָבער ב\"ה מיר האָבן שוין אַ מקום מנוח, אָבער מען דאַרף זיך דערמיט ניט מסתפק זיין, יעצט דאַרף מען ערשט אָנהויבן טאָן. ע\"ד ווי עס שטייט נאָכן מבול אַז \"ולא מצאה היונה מנוח לכף רגלה\"<sup data-n=\"203\">21</sup>, אין פלוג — ווי קומט מנוחה צו כף הרגל, מנוחה נעמט זיך דאָך מצד העונג, גילוי עצם הנפש, היינט ווי קומט מנוחה צו אַ פּאַדעשווע? נאָר דער ענין איז אַז די כוונה פון מנוחה איז אַז מ'זאָל אַראָפּקומען אין כף הרגל, היינו אין אַ בפועל ממש. די מעלה פון רגל איז דאָך וואָס דאָס איז מעמיד דעם גאַנצען ציור האדם, אַזוי קען ער דאָך אומפאַלען, נכשל ווערען, אָבער ע\"י הרגל איז דער ציור האדם על מקומו, אָבער די כוונה איז אַראָפּטראָגן די מדריגה פון מנוחה אין כף הרגל אין די נידעריגסטע מדרי­גה אין מעשה בפועל ממש, דאַמאָלסט איז דאָס מנוחה, אַז מען איז בערואיגט.",[["200","18","אדמו\"ר הזקן."],["201","19","{6} נבל."],["202","20","ראה ע\"ז יז, א."],["203","21","נח ח, ט."]]],[4301620193,"ה. דער טאַטע האָט אַמאָל גערעדט אין אַ המשך מאמרים דעם ענין פון חכמה דאצילות און האָט מבאר גיווען אַז די מציאות פון חכמה איז באַ מצד הביטול. וויפיל ער האָט דעם ענין מסביר גיווען איז נאָך אַלץ געווען ניט מובן כל צרכו.\nאין אַ משך זמן אַרום זיינען מיר געווען אין פּעטערבורג. דאַן איז אין פּעטערבורג געווען אַ גרויסער פּאַראַד, עס איז געגאַנגען אַ פּאָלק<sup data-n=\"204\">22</sup>, אַלע סאָלדאַטן אויסגעמושטירט אין שיינע קליידער מיט זייערע כלי זיין, באַ יעדע שורה איז געגאַנגען אַ פירער און אין שפּיץ איז געפאָרן אַ רייטער אויף אַ פערד, דער פערד איז געווען אויסגע­צירט און אויפ'ן פערד איז געזעסען אַ פאָניע, וואָס פאָניע קען רייטן אויף אַ פערד, און זיינען געגאַנגען מיט'ן גאַנצען נימוס פון חיל.\nהאָט דער טאַטע צו מיר געזאָגט, אַז דאָס איז אַ הסבר אויף דעם ענין פון חכמה דאצילות, דער סאָלדאַט ביז וואַנען ער איז געוואָרן אַ גוט אויס­מושטירטער סאָלדאַט האָט דאָך גענוג קלעפּ אַריינגעכאַפּט, אַז דער קנעפּל איז ניט גענוג אויסגעפּוצט האָט מען דאָך געשלאָגען און געגעבען קאַרצער, און וואָס פאַר אַ בעטרעף האָט דער סאָל­דאַט באַ זיין פירער, גאָרניט, ער איז דאָך באַ אים כעפרא דארעא, און דאָ זעט זיך דער סאָלדאַט אין אַ מציאות, איז דאָך זיין גאַנצער מציאות בא מצד הביטול, וכמו\"כ הוא בענין חכמה דאצילות שכל המציאות שלה בא מצד הביטול.\nדער טאַטע איז אַזוי געווען צוזאַ­מענגעבונדן מיט חסידות אַז וואָס ער האָט געזען, האָט ער ניט געזען די זאַך ווי עס ווייזט זיך כפשוטו, נאָר ווי דאָס איז אין עניני אלקות.\nאון דאָס איז אַ הוראה פאַר אַ עובד אַז וואָס ער זעט און וואָס ער הערט, זאָל ער דאָס דערהערען אין דעם אמת'ן ענין.\n<h4>סדר השני של חג הפסח תש\"ו </h4>\nא. הא לחמא עניא.\nווען דער אַלטער רבי איז געקומען דעם ערשטען מאָל פון מעזריטש<sup data-n=\"205\">1</sup> האָט מען איהם געפרעגט, וואָס האָט ער דאָרטן מקבל געווען פסח, האָט ער געענטפערט, אַז אין מעזריטש האָט ער גענומען, וואָס איז דער גאַנצער סדר פון גלות מצרים און די גאולה, די כוונה פון גלות און די כוונה פון גאולה, וואָס דאָס ליגט אין די דריי ווערטער פון: הא לחמא עניא.\nדי אידען אין מצרים איז זייער עבודה געווען אַ עניות'דיגע, ווייל זיי האָבען גענומען פון ה\"א פון שם הוי'. און דאָס איז דער פירוש פון: הא לחמא עניא, פאַרוואָס איז דאָס לחמא עניא, ווייל דאָס איז נאָר ה\"א פון שם הוי'.\nדאַרפען דאַרף מען אָנהויבן פון יו\"ד פון שם הוי', וואָס יו\"ד איז דער העלם העצמי, וואָס ער איז כולל אַלע גילויים, אָבער אַז מען נעמט נאָר פון ה\"א איז דאָס לחמא עניא.",[["204","22","{6} גדוד."],["205","1","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."]]],[4301620194,"ב. וכל המרבה לספר וכו' הרי זה משובח.\n(בשם אביו כ\"ק אדמו\"ר נ\"ע) אין פלוג וואָס איז דער ענין פון סיפור יציאת מצרים, אויב בלויז וואָס דאָרט איז געווען עבודה בפרך אין גשמיות און נאָכדעם איז מען דערפון בעפרייט געוואָרן, איז צוליב דעם אַליין וואָלט מען ניט קובע געווען דעם ענין הסיפור פון יציאת מצרים לדורות.\nעס איז פאַראַן דיבור און עס איז דאָ סיפור, דיבור קען זיין בקיצור אין עטלעכע ווערטער, וואָס די עטלעכע ווערטער קענען אַמאָל מכיל זיין די גאַנצע אריכות, אָבער סיפור מיינט דערציילען יענעם, אַז דער אַנדערער זאָל דאָס פאַרשטיין, אויב ער פאַרשטייט ניט מיט איינמאָל דאַרף ער זאָגען נאָך אַמאָל, אויב ער פאַרשטייט ניט מיט די ווערטער דאַרף ער אים זאָגען מיט אַנדערע ווערטער.\nדער עצם פון יעדען אידען איז דאָך זייער גוט און זייער הויך, מ'קען דאָך גאָר ניט איבערגעבען אין ווערטער ווי הויך יעדער איד איז מצד העצם, אָבער אין גילוי קען דאָך זיין, אַז מען איז ניט ווי מ'דאַרף, אָבער דורך דעם וואָס מען איז מרבה לספר ביציאת מצרים ווערט אויך דער \"זה\" אַ משובח<sup data-n=\"206\">2</sup>.\nאון דאָס איז דער פירוש וכל המרבה לספר ביציאת מצרים הרי זה משובח.\nג. הגיע זמן קריאת שמע של שחרית.\nעס איז פאַראַן קריאת שמע שעל המטה און עס איז דאָ קריאת שמע של שחרית, עס איז דאָ אַ גרויסער חילוק פון קריאת שמע של ערבית בכלל און קריאת שמע שעל המטה בפרט און קריאת שמע של שחרית<sup data-n=\"207\">3</sup>.\nאַז די רביים האָבען דערציילט ביציאת מצרים כל אותו הלילה, האָט אָנגעהויבן צו לייכטן ביי די תלמידים די מדריגה פון קריאת שמע של שחרית<sup data-n=\"208\">4</sup>.\nד. אראב\"ע וכו' עד שדרשה בן זומא.\nביי ראב\"ע איז געווען, ולא זכיתי, עס האָט ניט געלויכטען דער יציאת מצרים, בלילות אין גלות<sup data-n=\"209\">5</sup>, פאַרוואָס ווייל ראב\"ע איז געווען אַריינגעטאָן נאָר אין גליא שבתורה, וואָס הגם מצד גליא שבתורה איז אויך פאַראַן דער ענין פון גאולה, אָבער דאָס איז אַ גלות'דיגע גאולה. עד שדרשה בן זומא וואָס דאָס איז פנימיות התורה<sup data-n=\"210\">6</sup>, וואָס דאָס טוט אויף אַז דער ימי חייך זאָל זיין אַ כלי צו דעם כל ימי חייך להביא הלילות, ליכטיג מאַכן דעם גלות ביז דעם ענין פון להביא לימות המשיח, אַז ניט נאָר זאָל מען וויסן די כוונה פון גלות, נאָר אויך די כוונה פון גאולה זאָל לייכטן אין גלות<sup data-n=\"211\">7</sup>.\nה. צא ולמד.\nאַז דער אַלטער רבי איז געקומען פון מעזריטש האָט מען אים געפרעגט, וואָס האָסטו דאָרטען גענומען, האָט ער גע­ענטפערט<sup data-n=\"205\">1</sup> דאָרט האָט מען מיר גע­",[["206","2","ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 225 (הועתק ב\"היום יום\" יז ניסן). שם ע' 262. שיחת ליל ב' דחה\"פ תש\"ז (לקמן ע' 104 ואילך)."],["207","3","ראה גם ספר השיחות תש\"ד ע' 88. תש\"ה ע' 83."],["208","4","ראה גם רשימת היומן חג הפסח תרצ\"ב (\"רשימות\" חוברת לח ע' 6). ספר השיחות תרצ\"ו­חורף ה'ש\"ת שם. תש\"ג ע' 81. לקמן ע' 105. לקו\"ש ח\"ב ע' 540."],["209","5","ראה גם ספר השיחות תש\"ג ע' 71."],["210","6","ראה גם ספר השיחות תש\"ד ע' 89."],["211","7","ראה גם ספר השיחות תש\"ג ע' 72."],["205","1","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."]]],[4301620195,"לערנט אַז עס דאַרף זיין: צא ולמד, אַרויסגיין פון זיך און לערנען פון יענעם<sup data-n=\"213\">8</sup>, זען דעם אייגענעם חסרון און די מעלה פון יענעם.\nו. ויהי שם לגוי גדול עצום ורב.\nמערער ווי פופציג יאָר צוריק — אין יאָר תרנ\"א — האָט דער טאַטע זייער אַ סאַך גערעדט באַ די הגדה, עס איז געווען זייער אַ פריילעכער פסח.\n— עס איז אַ גרויסער עגמ\"נ וואָס מ'קען ניט ריידען באריכות דאָס וואָס מ'וואָלט געדאַרפט ריידען<sup data-n=\"214\">*8</sup> און מען מוז זיך פאַרלאָזן אויף אותיות הכתב, אָבער אין דבור איז דאָס גאָר אַנדערש מיט אַ אַנדער חיות.\nיסורי הגוף דאַרף אַ איד מקבל באהבה זיין, אָבער יסורי הנפש וואָס זיינען פאַרבונדען מיט יסורי הגוף — אויף דעם קען מען ניט מסכים זיין און מ'דאַרף ניט מסכים זיין, נו...\nאז מען שטעלט זיך אָפּ אין ציור המחשבה פון אַמאָל, איז מען ניט עלענד. הגם מען איז איצטער אויך ניט עלענד, מען געפינט זיך ב\"ה צווישען אידען, און אַזעלכע וואָס ווילען הערען און האָבען געגועים צו הערען אַ וואָרט. —\nדאַמאָלסט — אין יאָר תרנ\"א — האָט דער טאַטע געטייטשט \"ויהי שם לגוי גדול\", אַז אפילו אין מצרים האָבען אידען דערהערט אַז זיי זיינען אַ \"גוי גדול\". עס איז דאַן געווען אַ גאַנצע אריכות וועגען \"גדול עצום ורב\", און דער טאַטע האָט גערעדט אַ אריכות אין דעם ענין, אַז אין נשמות איז פאַראַן די מדריגה פון גדלות, עצמות און ריבוי, זייער אַ טיפער ענין אין חסידות, באַ מיר איז דאָ אַ הנחה פון דעם מאמר<sup data-n=\"215\">9</sup>.\nז. וירעו אותנו המצרים.\nפון די ווערטער איז משמעות ווי עס וואָלט זיך געוואנדען אין זייער בחירה, אין פלוג איז דאָך דער גלות מצרים און אַזוי אַלע גלות'ן מצד השגחה מלמעלה וואָס עס איז פאַראַן אַ כוונה אין דעם, וואָס די עניני הגלות דאַרפן דורכגע­פירט ווערן, היינט וואָס זאָגט ער \"וירעו אותנו המצרים\" כאילו עס איז תלוי אין זיי אַליין.\nנאָר דער ענין איז, וירעו איז מלשון ריעות, די מצרים האָבען זיך אָנגע­הויבען חבר'ן מיט די אידען<sup data-n=\"216\">10</sup>. און אַזוי אין יעדען גלות איז פאַראַן אַ סוג אידען וואָס חבר'ן זיך מיטען פּריץ; אפילו די וואָס מיינען אַז דורך דעם וואָס זיי וועלען זיין גוט מיט'ן פּריץ וועט דאָס בריינגען אַ טובה לכלל ישראל. דאָס איז אַ טעות, ניטאָ וואָס צו האָפען אויף דעם, ניט זיי ווילען טאָן און ניט זיי קענען טאָן.\nוואָס איז אָבער דער פועל יוצא פון דעם \"וירעו\", \"ויענונו ויתנו עלינו עבודה קשה\", אַז דער גלות ווערט נאָך שווערער וכו'.\nח. רבי יהודא הי' נותן בהם סימנים.\n(בשם כ\"ק אבי אדמו\"ר נ\"ע) וואָס איז דער ענין פון די סימנים און נאָך וואָס דאַרף מען סימנים (גם איזה שייכות יש בין רבי יהודה שהי' נותן בהם סימנים לרב יהודה שכולי תנויי בנזיקין הוה<sup data-n=\"217\">11</sup>),",[["213","8","ראה גם ספר השיחות תש\"ד ע' 91."],["214","*8","ראה גם ספר השיחות תשנ\"ב ח\"א ע' 292."],["215","9","לע\"ע אינו תח\"י."],["216","10","ראה גם ספר השיחות ה'תרצ\"ו­חורף ה'ש\"ת ע' 324."],["217","11","ברכות כ, א. וראה תענית כד, א. סנהדרין קו, ב."]]],[4301620196,"און דער טאַטע האָט גערעדט אין דעם אַ אריכות. — בקיצור, אַז אין קדושה איז דאָ אַ סדר, הויבט זיך אַן כח\"ב, חב\"ד, חג\"ת נהי\"מ; מכות איז דאָך קליפות, דאָרט איז אַ פאַרקערטער סדר, אַז באח\"ב וואָס דאָס מיינט כתר איז גאָר לבסוף.\nט. בתוך הסעודה ניגנו את הניגון הידוע<sup data-n=\"218\">12</sup> של ר' אשר ניקאָלאַייעווער<sup data-n=\"219\">13</sup> וסיפר כ\"ק אדמו\"ר שליט\"א<sup data-n=\"220\">14</sup>: דער מחבר פון דעם ניגון איז גיווען ר' משה חאַריטאָנאָוו<sup data-n=\"221\">15</sup>. הניגון (ב' בבות הרא­שונות) הביא ר' אשר הנ\"ל מה ששמע על החתונה במשפחת האָרענשטיין (חתונת ר' שלמה האָרענשטיין<sup data-n=\"222\">16</sup>), וכשבא אח\"כ ר' אשר לליובאַוויטש<sup data-n=\"223\">17</sup> למסור פ\"ש מהחתונה אמר לו כ\"ק אאמו\"ר נ\"ע שבטח יבא להנאות דשא בחו\"ל וכן הוה, ובא<sup data-n=\"224\">18</sup> ר' אשר הנ\"ל על פורים<sup data-n=\"225\">19</sup> תרס\"א לחו\"ל, וניגן את הניגון הנ\"ל כפי שתיקנו וסידרו ושכללו ר' משה<sup data-n=\"226\">20</sup> חאַריטאָנאָוו, ואמר כ\"ק אאמו\"ר נ\"ע: אין דעם ניגון שפּיגעלט זיך אָפּ די פאַרלוירענקייט פון אַ חסיד מצד מעשיו און זיין האָפען אויפן רבי'ן.\nוכשמסר אח\"כ ר' אשר הנ\"ל הדברים לר' משה חאַריטאָנאָוו<sup data-n=\"227\">21</sup>, אמר בהתרג­שות: דער רבי זעט, וויפיל פנימיות הלב דער ניגון האָט מיר געקאָסט.",[["218","12","תוי הניגון — בספר הניגונים ח\"א ניגון נט. — אודות ניגון זה ראה גם שיחת שבת חוה\"מ פסח שנה זו (לקמן ע' 35). שיחות שבהערה 14."],["219","13","ר' אשר בר' מאיר [גראָסמאַן] שו\"ב מניקולאַיעב. ממחונכי ר' הלל מפּאַריטש ומחסידי אדמו\"ר מוהר\"ש נ\"ע ואח\"כ אדמו\"ר מהורש\"ב נ\"ע. התעסק בהגהת התניא דהוצאת ווילנא תר\"ס. נפטר מרחשון ה'תר\"פ (?) [ספר השיחות קיץ ה'ש\"ת ע' 28 בהערה]. — ראה אודותו — שיחת עש\"ק שופטים שנה זו (לקמן ע' 54 ואילך)."],["220","14","בהבא לקמן — ראה (בשינויים) ספר השיחות תש\"א ע' 48 (הנחה אחרת בספר הניגונים ח\"א ע' נג). תש\"ב ע' 122 ואילך. שיחת ליל ב' דחה\"פ תש\"ז. תש\"ח. (לקמן ע' 106. ע' 206)."],["221","15","כן הוא גם לקמן בהעתקת שיחה זו. אבל בספר הניגונים שם: כשנסע אח\"כ הר' אשר לביתו לניקולאַיעוו ולמד הניגון לר' אהרן חאַריטאָנאָוו שו\"ב שהי' מנגן נפלא ומחבר ניגונים, הוסיף עליו ר' אהרן כנפים."],["222","16","עם מרת דבורה לאה בת הרבנית שיינא ברכה דוליצקא בת אדמו\"ר ר' יוסף יצחק בן אדמו\"ר הצ\"צ. החתונה התקיימה י\"ג סיון תרס\"א (ראה אגרות­-קודש אדמו\"ר מהורש\"ב ח\"ג ע' רנז)."],["223","17","כ\"ה ברשימת ההנחה. וצריך בירור, שהרי מיום ב', ד' כסלו תרס\"א עד יום ג', ה' אלול תרס\"א שהה כ\"ק אדמו\"ר מהורש\"ב בחו\"ל (ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 100. וש\"נ)."],["224","18","מכאן עד סוף השיחה נעתק בשינויים בספר הניגונים שם."],["225","19","כ\"ה ברשימת ההנחה. וצריך בירור שהרי החתונה התקיימה בחודש סיון תרס\"א כנ\"ל הערה 16."],["226","20","בספר הניגונים שם: ר\"א."],["227","21","בספר הניגונים שם: לר\"א חאַריטאָנאָוו שו\"ב."]]],[4301620197,"<h4>שבת חוה\"מ פסח תש\"ו בסעודת היום </h4>\nא. אחד מהמסובים לא אכל והרגיש בזה כ\"ק אדמו\"ר שליט\"א ואמר: עבודת חב\"ד איז אַז מען זאָל עסן, נאָר מען דאַרף קענען (ווי צו) עסן.\nב. ניגנו את הניגון של ר' אשר מניקאָלאַייעוו<sup data-n=\"228\">1</sup> ואח\"כ אמר כ\"ק אדמו\"ר שליט\"א:\nאיך האָב געהערט פון טאַטען, בשם אביו אאזמו\"ר מוהר\"ש, וואָס ער האָט געהערט פון צמח צדק, אַז ניגוני חב\"ד זיינען אחד משני פנים, אָדער זיי קומען פון חב\"ד אָדער זיי זיינען מגלה חב\"ד. אויף דעם ניגון וואָס מ'האָט יעצט געזונגען האָט דער טאַטע געזאָגט אַז דאָס איז פון די פרשה וואָס איז מגלה חב\"ד.\nדער טאַטע האָט דאָס גערעדט אין אַ געוויינליכען שבת באחת משבתי השנה, און האָט ממשיך געווען: אַז מען לערנט 2 שעה חסידות פאַר'ן דאַוונען, נאָכדעם גייט מען אין וואַסער, נאָכדעם שטעלט מען זיך דאַוונען, און מ'גיט אַ טראַכט מיט וואָס גייט מען דאַוונען, \"ווער\" גייט דאַוונען און מיט וואָס, און נאָכדעם אַז מען דאַווענט באריכות התפלה און מען זינגט דעם ניגון קען מען עפּעס אויפטאָן, דער עיקר פון עבודת התפלה איז עס זאָל זיין סיומא דתפלה, עס זאָל פּועל'ן אויף נאָכן דאַוונען.\nפאַראַן אַזעלכע וואָס האַלטן ביי די דרגא פון פאַרן דאַוונען, ד.ה. אַז דער פאַר'ן דאַוונען איז באַ זיי גוט, זיי לערנען חסידות ווי מ'דאַרף, נאָר דער דאַוונען אַליין איז אַ טרוקענער, ווער רעדט נאָכן דאַוונען, איז שוין גאָר אַ קאזיאל<sup data-n=\"229\">2</sup>. דער עיקר עבודת התפלה איז אַז עס זאָל פּועל'ן אויפ'ן גאַנצען טאָג.\nאון דער טאַטע האָט גערעדט אין דעם דרגות: פריער איז, אַז דער עסען נאכ'ן דאַוונען זאָל זיין ווי אַ דאַוונער עסט. נאָר דאָס איז אַ דבר הפשוט און ער האָט אין דעם ניט מאריך גיווען. דער מעלה פון דעם איז, אַז דער דאַוונען זאָל ביי אים דערהערט ווערען אין אַלע זיינע ענינים בכל היום, ער טוט זיך טאַקע זיינע ענינים וואָס ער דאַרף טאָן אָבער אין אַלע זיינע ענינים דער­הערט ער דעם דאַוונען און דאָס איז אים מעורר צו תפלת המנחה, נאָכדעם בערבית אַז עס ווערט פינסטער, גיט ער אַ טראַכט אַז עס איז ניט נאָר פינסטער אין גאַס, נאָר עס איז פינסטער באַ איהם אין האַרצען און עס איז פּוסט אין קאָפּ, און מיט די התבוננות הויבט ער זאָגען והוא רחום יכפר, וואָס רחמים פון סדר השתלשלות איז ניט מספיק, אָבער אַז עס איז \"והוא\" רחום, וואָס \"והוא\" איז עצמות, עס זאָל נמשך ווערען רחמים פון עצמות א\"ס, איז דאַמאָלסט הויבט אים אָן לייכטען, וואו לייכט זיך דאָס אין קריאת שמע שעל המטה, וואָס דעמאָלט איז נאָכדעם די שלאָף ניט ווי אַ שוטה שלאָפט וכו'.\nדער עיקר פון חסידות איז צו דערהערען דעם ענין. דערהערען וויפיל חיות עס ליגט אין אַ חסידישען ניגון, וויפל חיות עס ליגט אין אַ חסידישען וואָרט.\nדער ענין פון עבודת התפלה איז",[["228","1","ראה שיחת ליל ב' דחה\"פ שנה זו (לעיל ע' 34)."],["229","2","{6} תיש."]]],[4301620198,"היינט געוואָרען אַ ביסעל אויסגעוועבט, אַ ביסל פאַרשלאָפן<sup data-n=\"230\">3</sup>. הגם מאָנען דאַרף מען מאָנען ביי זיך, ביי יענעם דאַרף מען זעהן די מעלות, אָבער...\nג. איך האָב אַמאָל געהערט פון טאַטן אויף יחידות, אַז דער אַלטער רבי האָט מתקן געווען דעם ציור חב\"ד, ניט נאָר מתקן געווען נאָר ממשיך געווען אַז אפילו אַ ישובניק (העוסק בישובו של עולם) זאָל אויך דערהערען הפלאת חכמה עילאה, אָבער די תכלית הכוונה איז, אַז עס זאָל אַראָפּקומען אין אַ בפועל.\nדער טאַטע האָט דאַן געזאָגט, אַז מ'טוט בלויז אין לימוד החסידות אָן עבודת התפלה, איז דאָס קיין קאָפּ ניט, נאָר במחילה...\nעבודת התפלה איז שייך צו אַלעמען (ניט נאָר פאַר יחידי סגולה), נאָר מען דאַרף אַראָפּטרייסלען דעם שטויב און בלאָטע וואָס איז אָנגעוואַקסן, וואָס אין דאַוונען איז פאַראַן ב' תנועות, געגועים צו אלקות, אָדער דער געשמאַק, וואָס עס איז גוט, עס פעלט קיין זאַך ניט, ער בעט ניט אויף מזונות, אויף גשמיות, ער איז צופרידען דאָס וואָס ער האָט (היינו ההרגש מאלקות) און ער וויל אַז דאָס וואָס ער האָט זאָל ביי אים לייכטען.\nאַמאָל איז געווען אַז די וואָס האָבען געדאַוונט (באריכות) האָבען געוואוסט, און די וואָס האָבן געזען יענעם דאַוונען האָבן געהאַט געגועים צו דעם, היינט...\nאַ חסידישער דאַוונען איז אַזוי ווי אַ טרוקענע שטיקל האָלץ. אַ נאַסער האָלץ ווען ער הויבט אָן ברענען, שיפעט עס און עס פלאַקערט אויף מיט אַ גרויסען רעש, אָבער אַ טרוקן שטיקל האָלץ, ברענט שטיל, אָן רעש, און ווען דער פלאַם גיט עם אַ חאַפּ אָן, גיט ער זיך אַ טרייסעל, און דער פייער ברענט עם דורך. אַזוי איז אויך אין אַ חסידישן דאַוונען, שטיל אָן רעש, ווען דער פלאַם פון דאַוונען גיט עם אַ חאַפּ, גיט ער זיך אַ טרייסל, איבערברעכן זיך זיינע מדות, אָבער אַלץ אָן רעש וכו'.\nאיך האָב געהערט צוויי לשונות וועגען דאַוונען, אויסלעבן זיך (אין דאַוונען) און אויפלעבן.\nאַמאָל איז געווען דער חסידישער ווינקעל, מען פלעגט אַריינגיין אין ביהמ\"ד און אַוועקזעצן זיך אין אַ ווינקל און אָנהויבן זיך באַטראַכטן וואָס טוט זיך מיט אים, ווער גייט דאָס דאַוונען און פאַר וועמען מען גייט דאַוונען...\nהיינט, אַז מען שטייט אויף אינדער­פרי, הויבט מען זיך אָן אַיילען, מען דאַרף, מען דאַרף גיין אַהין, מען דאַרף דאָס, מען דאַרף העלפן דעם רבונו של עולם, און אויף עבודת התפלה פאַר­געסט מען.\nהי' ענין ע\"ד: חב\"ד חג\"ת נהי\"ם, די ממשלה אויף זיך.",[["230","3","ראה גם שיחת יט­כ כסלו ה'שי\"ת ס\"ג ואילך (לקמן ע' 384)."]]],[4301620199,"<h4>בכינוס הר\"מ ומנהלי ישיבות תומכי-תמימים ואחי-תמימים </h4>\n<h4>אשר בערי השדה ב[יום ד' ד]חוהמ\"פ תש\"ו<sup data-n=\"231\">1</sup> </h4>\nיעצט קען מען זאָגן אַז די שליחות פון קומען אין אַמעריקא האָט ב\"ה מצליח געווען.\nעס איז יעצט ניט די צייט צו ריידן וועגן דעם באריכות, נאָר מען דאַרף געבן אַ הלל ושבח דעם אויבערשטן, וואָס ער האָט מצליח געווען די שליחות.\nאיר זייט דאָך טעטיק אויפן געביט פון חינוך הכשר און האָט ב\"ה מצליח געווען, נאָר וויפיל איר טוט ניט אין דעם, איז נאָך אַלץ ניט גענוג. מען דאַרף קלאָר מאַכן פאַר אייך די אחריות, וואָס די השגחה העליונה האָט אַרויפגעלייגט אויף אייך. איר זייט די נבחרים פון דער השגחה עליונה וועלכע גיט אייך די נויטיגע כחות אויף דורכפירן די שליחות, נאָר איר דאַרפט זיך ניט נאַרן ניט אין דער שליחות און ניט אין די כחות.\nפון צייט צו צייט דאַרפט איר זיך פאַרזאַמלען און צוזאַמענריידן זיך וואָס איר האָט צו טאָן פאַר דעם חינוך הכשר, און ווי אַראָפּצובריינגען בע\"ה אייערע החלטות מן הכח אל הפועל.\nמען דאַרף טאָן מיט אַ פנימיות — איך מיין דאָ ניט פנימיות בדרכי החסידות — נאָר טאָן מיט כחות פנימיים. מען האָט געעפנט אַ טיר, דאַרף מען זיין אַ נכנס בפנים.\nדאָס איז אין עצם. און די התגלות והתפשטות דאַרף זיין בכל לשון שאתה שומע. עס זיינען דאָך דאָ קינדער און יוגענט וועלכע פאַרשטייען ניט קיין אידיש, דאַרף מען זוכן עצות ווי צו בריינגען אויך זיי צו תורה ויראת שמים און ווי צו בריינגען תורה ויראת שמים צו זיי. מען דאַרף שטרעבן צו מאַכן די אַמעריקאַנער אידישע קינדער פאַר לומדים, אָבער פריער — פאַרשטייט זיך — דאַרף מען אַראָפּנעמען די לבושים המלוכלכים און אָנטאָן זיי לבושים נקיים.\nאַז עס געפינט זיך אין אַ שטאָט אַ יונגערמאַן אַ בן­תורה, דאַרף זיך דאָרטן דערהערן אַז עס איז דאָ אַ איד אין שטאָט. אַ ודאי זיינען ב\"ה פאַראַן מערער אידן, כן ירבו, אָבער דאָס זיינען כחות­הנעלמים­אידן וועלכע מען דאַרף שייערן און רייניגן ביז עס ווערט ביי זיי נתגלה דער טוב.\nאיר דאַרפט נעמען די יוגענט אין אייערע הענט. איר דאַרפט שאַפן פאַר זיי שיעורים און מסיבות! איר דאַרפט זיי באַקענען מיט דעם לעזע­מאַטעריאַל וועלכע איז שוין ערשינען דורך דעם \"מרכז לעניני חינוך\" און מען דאַרף זוכן בע\"ה צו ערמעגלכן דעם ערשיינען פון נאָך — פאַר דעם יוגענט צוגעפּאַסטע — שריפטן.\nדער אויבערשטער זאָל אייך אַלעמען מצליח זיין אין אייער שליחות בכלל, און יעדן איינעם אין וואָס ער דאַרף בפרט.",[["231","1","נדפס בסה\"מ תשי\"א ע' 239. פירוט התאריך \"יום ד' דחוהמ\"פ\" ע\"פ הנרשם בכותרת בהנחה בלתי מוגה."]]],[4301620200,"<h4>ליל שביעי של פסח תש\"ו בסעודה </h4>\nא. איך האָב געהערט פון טאַטן וואָס ער האָט געהערט פון זיידן, בשם הצ\"צ, אַז דער אַלטער רבי האָט געזאָגט לנכדו הרב\"ש<sup data-n=\"232\">1</sup>: דו האָסט מיך מחיי געווען, מיט דעם וואָס דו האָסט זיך איינגעהערט צו די טעמי הנגינה<sup data-n=\"233\">2</sup> און האָסט זיי איינ­גע'חזר'ט.\n— דער אַלטער רבי האָט געהאַט באַזונדערע טעמי הנגינה צו יעדען טייל פון קרה\"ת<sup data-n=\"234\">3</sup>, עס איז ניט געווען גלייך די טעמי הנגינה פון גאַנץ תורה צו די טעמי הנגינה פון אז ישיר, און די טעמי הנגינה פון עשרת הדברות אין יתרו איז ניט געווען גלייך צו די טעמי הנגינה פון עשרת הדברות אין משנה תורה<sup data-n=\"235\">4</sup>. —\nדער למען תספר באזני בנך ובן בנך<sup data-n=\"236\">5</sup> — האָט דער אַלטער רבי ווייטער געזאָגט צו רב\"ש — מיינט מען ניט נאָר אַ אייניקל, נאָר עד סוף כל הדורות, נאָר מען קען דאָך ניט איבערגעבן בע\"פ נאָר צו אַ אייניקל, אָדער אַ אור­אייניקל, וואָלט איך זייער וועלן, אַז די ניגונים וואָס דו האָסט געהערט פון מיר, וואָס דאָס איז ווי מלכות דאצילות זינגט, זאָל מען זיי זינגען עד סוף כל הדורות.\nנאָך אזויפיל יסורים און מנגדים וואָס דער אַלטער רבי האָט געהאַט, וואָס די מנגדים אין עוה\"ז זיינען ניט בערך צו די מנגדים וואָס ער האָט געהאַט מצד שרשי הקליפות, וואָלט ער וועלען, אַז די אַלע כוונות וואָס ער האָט מכוון געווען, און די ניגונים וואָס ער האָט מסדר געווען, זאָל מען זיי זינגען עד סוף כל הדורות, און וואו אַ איד וועט זיך געפינען און באַ וועלכען מצב ער וועט זיך געפינען וועט דער ניגון אים מעורר זיין צו תשובה, וואָס תשובה מיינט מען ניט אויף אַ חטא ועון<sup data-n=\"237\">6</sup>, נאָר תשובה אויף דעם גילוי, אַז ער דערהערט גילוי מיינט ער דאָך אַז ער האָט שוין עפּעס, דאַרף ער וויסען אַז דאָס איז ניט מער ווי אַ גילוי.\nדער אַלטער רבי האָט זייער מחבב געווען דעם רב\"ש<sup data-n=\"238\">7</sup>. נאָך די הסתלקות פון אַלטען רבי'ן, איז דער רב\"ש כל ימיו געווען צובראָכן באַ זיך און ער האָט זיך ניט געקענט טרייסטן<sup data-n=\"239\">8</sup>. דער צמח צדק האָט איינמאָל געזאָגט צו רב\"ש, וואָס קענסטו ניט קומען צו זיך, דער זיידע זיצט אין גן עדן און איז מגלה פנימיות התורה, וענה הרב\"ש: איך וואָלט דאָס וועלן הערן...\nב. דער צמח צדק פלעגט בחיי דעם אַלטן רבי'ן, בחיי דעם מיטעלן רבי'ן, און אויך שפּעטער בעת נשיאותו פאַרבריינגען מיט חסידים<sup data-n=\"240\">9</sup>.",[["232","1","ר' ברוך שלום, בנו בכורו של הצ\"צ. ראה אודותו: ספר השיחות שבהערה הבאה. וש\"נ."],["233","2","ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 253. תרצ\"ו­חורף ה'ש\"ת ע' 54. 253. וש\"נ."],["234","3","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת שם."],["235","4","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת שם ע' 54: דער זיידע פלעגט לייענען די עשרת הדברות פון ואתחנן מיט אַ אַנדער ניגון ווי די עשרת הדברות פון יתרו. . דער זיידע פלעגט לייענען די פיהר פסוקי אז ישיר ישראל, באר חפרוה, וממתנה, ומבמות הגיא, מיט אַ ניגון מיוחד, אָבער אַנדערש ווי אז ישיר פון שירת הים."],["236","5","בא י, ב."],["237","6","ראה לקו\"ת דרושים לר\"ה ס, ד. סה\"מ תרח\"ץ ע' יג. וש\"נ."],["238","7","ראה גם ספר השיחות תש\"ג ע' 88."],["239","8","ראה גם ספר השיחות קיץ ה'ש\"ת ע' 151. תש\"ג ע' 89."],["240","9","ראה גם שיחת ליל ש\"ק פ' לך לך שנה זו (לעיל ע' 12)."]]],[4301620201,"דער צ\"צ האָט אָנגעהויבן פאַר­בריינגען מיט חסידים זייענדיג אַלט 15 יאָהר, שפּעטער בעת נשיאותו פלעגט ער פאַרבריינגען זייער בקיצור און בהתיישבות.\nדער סדר פון דעם פאַרבריינגען איז געווען, אַז ער פלעגט אָנהויבן מיט אַ סיפור המעשה און נאָכדעם פלעגט ער מבאר זיין דעם בכן, ווי דאָס דאַרף פּועל'ן אין כחות חב\"ד, חג\"ת, נה\"י, און קבלת עול מלכות שמים דאַרף מען אַליין קריגן.\nדער צמח צדק האָט געזאָגט: אַ סיפור דאַרף פועל'ן בענינים הנ\"ל, און אויב דאָס פועל'ט ניט איז דאָס מסיבת א' מג' טעמים: א) ווייל דער שומע פאַר­שטייט ניט, ב) ער וויל ניט פאַרשטיין, והג) ווייל דער מקבל איז אַ כלי מאוסה. דער זיידע — געמיינט אדמו\"ר הזקן — איז דאָך געווען אַ טוב עין<sup data-n=\"241\">10</sup>, האָט ער געגעבען אַ כח אויסצו­וואַשן די כלי מאוסה דורך — אַ ניגון.\nוסיים כ\"ק אדמו\"ר שליט\"א: דאָס איז אַלץ אויב עס איז אדעתא דנפשי'.\nג. איך בין מכיר אין דעם חסד עליון, וואָס עס איז ב\"ה דאָ הצלחה אין מיין נסיעה אַהער, מ'האָט ב\"ה אין אַ קורצע צייט אַ פולע אויפגעטאָן.\nדי וואָס זעהן מיך און איך אַליין וואונדערן זיך פאַרוואָס מען זעט ניט אויף מיר שמחה בהתגלות. באמת האָט מען דאָך געדאַרפט זיין שש ושמח, אַז במשך אַזאַ קורצער צייט האָט מען גע­מאַכט ליכטיג אַ סאַך אידישע הערצער, מען האָט ב\"ה פאַרפלאַנצט אַ נטיעה פּנימית, אַ פּנימיות'דיגע נטיעה, אַ אור זרוע וואָס בריינגט און וועט בריינגען פירי פירות. מען האָט דאָך געמאַכט ליכטיג אַז אין די מדינה זאָל מען אויך דערהערען דעם אמת, וואָס די ליכטיג­קייט האָט גע'פועל'ט אין אַלע סוגי בני אדם, אפילו די וואָס ווילען ניט אַריינ­גיין אין די אַרבעט און טוען אַלע השתדלות'ן אויף ניט אַריינגיין אין דעם און דרייען מיטן קעפּל אויף ניט, זיינען אויך געוואָרען אַנדערש, וואָס לפי ערכם זיינען זיי נשתנה געוואָרען מהקצה אל הקצה,\n— איך בין כלל ניט גענאַרט, מ'האָט ב\"ה אַ פולע אויפגעטאָן. האָט דאָך געדאַרפט זיין אַלע טאָג שמחת תורה, די שמחה פון תורה בהתגלות, נאָר וואָס דען, מען איז זייער צובראָכן.\n50 יאָהר אַז מען ווייקט זיך אין אידישע יסורים, אין פערשידענע צייטען און פערשידענע שליחות'ן, צוזעהענדיג דעם שעבוד הגוף, ניט שעבוד הגוף נאָר שבירת הגוף, זעענדיג וואָס פאַר אַ טוב אידען זיינען ווערט, איז דערפון איז מען זייער צובראָכן און עס קען ניט זיין די שמחה בהתגלות<sup data-n=\"242\">11</sup>.\nדער אויבערשטער זאָל העלפן, אַז אידן זאָל ווערן גוט, אַ פּנימיות'דיגן גוט, און עס זאָל נמשך ווערן דער גילוי המשיח בפועל, ניט נאָר בכח נאָר בפועל, ס'איז שוין דורכגעווייטאָגט, און אַלע אידן זאָלן גיין אין ארץ ישראל, און עס זאָל טאַקע זיין ארץ ישראל.",[["241","10","ע\"פ משלי כב, ט. וראה שיחת יום א' דחה\"ס תש\"ח (לקמן ע' 168)."],["242","11","ראה גם שיחת ליל אחש\"פ שנה זו (לקמן ע' 41)."]]],[4301620202,"<h4>ליל אחרון של פסח תש\"ו בסעודה </h4>\nא. אַז דער אַלטער רבי איז געקומען דעם ערשטן מאָל אין וויטעפּסק פון מעזריטש, האָט ער דערציילט<sup data-n=\"243\">1</sup> וואָס ער האָט געהערט פון מעזריטשער מגיד, אַז ביי דעם בעש\"ט האָט די מסכת אהבת ישראל געהאַלטן כמה מאות פרקים. ביי אברהם אבינו האָט די מסכת ע\"ז געהאַלטן ד' מאות פרקי<sup data-n=\"244\">2</sup>, און ביי דעם בעש\"ט האָט די מסכת אהבת ישראל געהאַלטען כמה מאות פרקים. אברהם אבינו האָט מנחיל געווען צו אידן אהבת המקום — אהבת השי\"ת, און דער בעש\"ט האָט מנחיל געווען צו אידן אהבת ישראל, ליב האָבען אַ אידן ווייל ער איז אַ איד<sup data-n=\"245\">3</sup>. אַז אַ איד געפינט זיך בקצה העולם<sup data-n=\"246\">4</sup>, וועמען ער קאָן גאָר ניט<sup data-n=\"247\">5</sup>, נאָר דער אויבערשטער ווייסט פון אים און ער ווייסט פון אויבערשטן — דאַרף מען אים ליב האָבן.\nדעם וואָרט האָט מען גערעדט פסח ת\"ש<sup data-n=\"248\">6</sup> און מען האָט דאַמאָלסט געזאָגט אַז ביי דעם בעש\"ט האָבען אייז­\"ליכטלעך\" אויך געברענט און היינט זיינען אויסמושטירטע חסידים קאַלט און פינסטער.\nדי מעשה מיט די אייז­\"ליכטלעך\" איז אַזוי, דער בעש\"ט האָט זייער ליב געהאַט ליכטיגקייט, דער בעש\"ט האָט ליב געהאַט ליכטיג און וואַרעם, אפילו זומער פלעגט ער הייסען הייצען דעם אויווען, עס זאָל זיין וואַרעמער און נאָך וואַרעמער, און האָט זייער ליב געהאַט ס'זאָל זיין ליכטיג.\n— אַמאָל פלעגט מען ברענען חלב'נע ליכטלעך, וואָס דאָס איז געווען אַ עשירות, און עס איז געווען אַזעלכע \"סטאַציקעס\" פון געפלאָכטענע וואַקס­ענע ליכטלעך וואָס דאָס איז געווען נאָר ביי עשירים —\nאיינמאָל זיינען די תלמידים געזעסען אין ביהמ\"ד און געוואַרט אויף דעם בעש\"ט, וועלכער האָט געדאַרפט באַלד אַריינקומען, אָבער זיי זיינען געווען זייער פאַר'דאגה'ט וואָס זיי האָבן ניט קיין \"סטאַציקעס\" אָנצוצינדען, אין גאַס איז געווען אַ גרויסער וויוג (זאַווירוכע) און מען האָט ניט געקענט קריגען קיין ליכט.\nדי תלמידים האָבען געוואָלט פאַר'­משכנ'ען זייערע קאַפּאָטעס אָבער מ'האָט ניט געקענט קריגען קיין ליכט, והי' הדבר לפלא גדול אצל התלמידים. דער­ווייל איז דער בעש\"ט אַריינגעגאַנגען, האָבען די תלמידים אים דערציילט אַז מען קריגט ניט קיין ליכט, ואמר הבעש\"ט: אָבער ליכטיג דאַרף דאָך זיין. וציוה הבעש\"ט להתלמידים, אַז מען זאָל אָפּהאַקען פון דאַך די אַייז­\"ליכטלעך\" וואָס היינגט נאָך און מ'זאָל דאָס אָנצינ­",[["243","1","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["244","2","עבודה זרה יד, ב."],["245","3","ראה שיחת יום ב' דחג השבועות שנה זו. פורים תש\"ז. רשימה ש\"פ נצבים תש\"ז. ט\"ז אד\"ר תש\"ח. יו\"ד שבט תש\"ט (לקמן ע' 49. ע' 100. ע' 151. ע' 185. ע' 300). אגרות­-קודש ח\"ט ע' קסא. ע' קסה. ע' רטז. ע' שכט. ספר השיחות תש\"א ע' 93. תש\"ג ע' 12. תש\"ה ע' 117 ואילך."],["246","4","ראה לקו\"ש ח\"א ע' 201."],["247","5","ראה שיחת י\"ט כסלו תש\"ז סט\"ז (לקמן ע' 96). אגרות­-קודש ח\"ה ע' פט (הועתק ב\"היום יום\" טו כסלו). לקו\"ש שם."],["248","6","ראה שיחת ש\"פ תבא, ח\"י אלול, ה'ש\"ת (ספר השיחות קיץ ה'ש\"ת ע' 174). לקו\"ש חט\"ו ע' 384."]]],[4301620203,"דען. האָבן די תלמידים אַזוי געטאָן און די אַייז­\"ליכטלעך\" האָבען געברענט.\nווען דער זיידע מהר\"ש האָט דערציילט די מעשה אויף יחידות צום טאַטען האָט ער מסיים געווען: ניט נאָר וואָס די אייז איז ניט צוגאַנגען, נאָר עס האָט געמאַכט ליכטיג און וואַרעם.\nב. איך דערמאָן זיך יעצט וואָס איך האָב איבערגעלעבט דעמאָלט ווען איך האָב גערעדט די ווערטער אין ת\"ש, אַז איך האָב אַ טראַכט געטאָן מיט וואָס פאַר אַ באַגאַזש מען איז געקומען און וואו געפינט מען זיך, איך האָב געוואוסט מיין שליחות, אָבער ווי אזוי... מער ניט וואָס יעדער איד איז דאָך אַ מאמין בפנימיות מוחו ופנימיות לבו, אַז אין אַלץ איז דאָ אַ כוונה עליונה וכו'.\nיעצט ב\"ה אַז מ'זעט די הצלחה אין די אַרבעט, וואָס מ'האָט במשך די קורצע צייט אַפולע אויפגעטאָן און די כוונה עליונה אין די שליחות האָט זיך דורכגעפירט, און דורך וועמען, דורך צובראָכענע מענטשען, וואָס די עלטע­רען זיינען צופרידען... האָט מען דאָך געדאַרפט זיין שש ושמח, נאָר מען איז פאַריאָגט<sup data-n=\"249\">7</sup>. בלשון העולם, אַז איינער פרעגט דעם אַנדערן: ברודער וואָס מאַכסטו? ענטפערט ער: אַזוי איז ניש­קשה, נאָר מ'איז פאַריאָגט.\nמ'איז פאַריאָגט פון די צרות היום יום, דאָ איז ביי דעם אַ פּריזיוו, ביי דעם איז אַ אַפּעראַציע ר\"ל, אַ יולדת, איז מען כסדר פאַריאָגט, אַז מ'קען ניט זיין בשמחה<sup data-n=\"250\">8</sup>.\nג. אין איינעם פון די שפּאַצירן וואָס איך בין געגאַנגען מיט'ן טאַטן, האָט דער טאַטע מיר געזאָגט: די נשמה זעט, שכל שטעלט זיך פאָר, און האַרץ לעבט איבער.\nעס האָט זיך דעמאָלסט גערעדט וועגען חסידישען חינוך, וואָס עלטערען מעגען דאָך האָבען אידישען נחת פון קינדער, עלטערען פון קינדער און קינדער פון עלטערען פון חסידישן חינוך וכו'. דער טאַטע האָט מיר דעמאַלסט געזאָגט: איך בין מהלל ומשבח צום אויבערשטן פאַר דיין חינוך.\nווען איך האָב נאָר אָנגעהויבען צו ריידען, אַלס אַ קינד פון 3 יאָהר בערך, פלעגט דער טאַטע מיר פרעגן, וואָס געדענקסטו?<sup data-n=\"251\">9</sup> — איך זאָל זיך מצייר זיין — האָב איך געזאָגט איך געדיינק דעם זיידן — מהר\"ש נ\"ע — ווי ער האָט געטראָגען 2 גאָלדענע קייטלעך אויפ'ן וועסט — כידוע שהמהר\"ש נ\"ע נשא תמיד 2 שעונים בכיסו — דעם ט\"ק וואָס האָט אַרויסגעזען זיך פון וועסט, האָט דער טאַטע מיר געזאָגט אַז איך זאָל זיך דאָס מצייר זיין. ער האָט ביי מיר מפתח געווען דעם חוש הציור. אַז איך האָב געלערנט ביי מיין ערשטען מלמד ר' יקותיאל<sup data-n=\"252\">10</sup> ודרכו הי' שאחר הלימוד פלעגט ער דערציילען סיפורי מעשיות שהי' בהם עניני הפלאה, שגם לגדולים הי' זה הפלאה ומכ\"ש לילדים, פלעג איך זיך דאָס מצייר זיין. אח\"כ למדתי אצל המלמד ר' ניסן<sup data-n=\"253\">11</sup>. וכמו\"כ בכל ענין בלימוד דא\"ח ציירתי",[["249","7","ראה שיחת ליל שביעי של פסח שנה זו (לעיל ע' 39)."],["250","8","ראה לקמן סעיף ד."],["251","9","ראה לקמן ס\"ע 64. ע' 109. ע' 230. ע' 239. ע' 306. ע' 336 (וראה ע' 333)."],["252","10","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 111. ע' 119. לקמן ע' 89 ואילך. ע' 239. ע' 352. ע' 361. ע' 394."],["253","11","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 120. לקמן ע' 43. ע' 65 ואילך. ע' 89. ע' 128. ע' 161. ע' 240. ע' 254. ע' 392 ואילך. רשימות היומן — חורף תרצ\"ה."]]],[4301620204,"לעצמי הענין. דער טאַטע האָט מיר אַמאָל געזאָגט: דער כח הציור האָט דיר געראַטעוועט. און דורכדעם איז ביי מיר נתפתח געוואָרען דער חוש הציור (עד שיש כמה דברים שהנני זוכר שאינני יודע אם ראיתי בעצמי הדבר או שזהו מה שציירתי לעצמי ממה ששמעתי).\nאויפן יסוד פון אהבת ישראל פון בעש\"ט שטעל איך זיך פאָר וואָס פאַר אַ גרינגע אַרבעט מלאך מיכאל האָט יעצט אויף מלמד זכות זיין אויף אידן, אַמאָל פלעגט מלאך מיכאל דאַרפען זוכען הרי הרים צו געפינען אַ זכות אויף אידן, ווי עס איז ידוע די מעשה, וואָס מלאך מיכאל האָט געדאַרפט בריינגען דעם וואָגען, די פערד און די בלאָטע, און אַרויפלייגען אויפ'ן משקל לזכות את ישראל.\nאָבער היינט אַז ער בריינגט די הערצער פון מס\"נ, אפילו פון אַזעלכע וואָס זיינען ניט שומרי שבת און ניט קיין מניחי תפילין ר\"ל, וואָס דאָס זיינען זיי דאָך ניט שולדיג, דאָס איז דאָך נאָר מצד עם הארצות און פון די וועלכע זיינען מסית ומדיח. וואָס באמת ווען די פירער וואָלטען תשובה געטאָן וואָלטען דאָך די אידען גאָר אַנדערש אויסגעזען, אָבער אפילו ביי די, איז דאָך: וואָס מיר זיינען זיינען מיר, אָבער אידען זיינען מיר; אָט דער מס\"נ וואָס עס האָט זיך געפונען ביי זיי צו קעמפען און פאַרטיידיגען דאָס איז דאָך מצד העצם, אַז דער שונא האָט געוואָלט אַז ולא<sup data-n=\"254\">12</sup> יזכר שם ישראל עוד ח\"ו, האָט דאָס זיי אָנגערירט אין עצם און זיינען געגאָנגען אויף מס\"נ. האָט דאָך מלאך מיכאל אַ גרינגע שטיקעל אַרבעט, מען האָט דאָך די אידען אויסגעפּרואווט אויף אַלע אופנים. שוין גענוג געשפּילט זיך, שוין צייט די גאולה ע\"י משיח זאָל קומען בקרוב.\nד. אַ בעטלער איז שטענדיג פאַר­נומען מיט בעטלעריי, ער קען גאָר ניט הנאה האָבען פון דעם וואָס ער האָט, ער דאַרף כסדר בעטלען, און דאַרף מאַכען דעם פנים אַזוי אַז עס זאָל ניכר זיין בפניו אַז ער איז אַ בעטלער, אַז ניט וועט מען אים ניט געבען, און קען גאָר ניט הנאה האָבען פון דעם וואָס ער האָט יע. כמו\"כ אַ גביר, איז דער גביר וואָס גיט, גייט איהם ניט איין זיין עשירות, פון דעם וואָס יענעם פעלט; און דער גביר וואָס גיט ניט, גייט ניט איין זיין רייכטום, ווייל מען מאָנט ביי אים כסדר.\nמען דאַרף כסדר בעטלען, דאָ דאַרף איינער געזונד, דאָ דאַרף איינער פרנסה, דאָ אַזאַ זאַך. מען איז כסדר פאַרנומען אין בעטלעריי, קען מען ניט הנאה האָבען פון דעם וואָס מען האָט ב\"ה<sup data-n=\"255\">13</sup>. אָבער מען בעט דאָך אַ טאַטען פאַר זיינע קינדער, אַ טאַטע וואָס קען געבען, וויל געבען און דאַרף געבען. זאָל דער אויבערשטער געבען, אַז די אידען זאָל ווערען באמת גוט.",[["254","12","ע\"פ תהלים פג, ה."],["255","13","ראה לעיל סעיף ב."]]],[4301620205,"<h4>כ\"ח ניסן תש\"ו<sup data-n=\"256\">1</sup> </h4>\n<h4>להבחורים קודם נסיעתם לשיקאגא<sup data-n=\"257\">2</sup> </h4>\n(כשנכנסו שאל: ווען פאָרט איר? וענו: היום. ואמר:) אייער פאָרען קיין שיקאַגאָ איז אַ צווייענדיקע זאַך: איר פאָרט פאַר זיך, און ווייזען אַ \"סאַמפּעל\"<sup data-n=\"258\">3</sup> וואָס אַ תלמיד פון תומכי-תמימים איז. א תלמיד פון תומכי-תמימים דאַרף זיך פירן עפ\"י חסידות, נישט נאָר עפ\"י תורה, נאָר אַ תלמיד פון תומכי-תמימים דאַרף זיך פירן עפ\"י חסידות אויך. איך האָב געהאַט אַ ביסל נחת רוח פון אייך, נאָר מען דאַרף האָבן מער. איך האָב געהערט אַז איר חזר'ט מאמרים, איך האָב געהאַט אַ נחת רוח פון דעם. מען דאַרף טאַקע חזר'ן, אָבער דאָס איז ניט גענוג, מען דאַרף טאָן. אויב מען חזר'ט אַן עבודה'דיקן מאמר דאַרף מען טאָן אין עבודה. מען דאַרף לערנען און זיין איבערגעגעבן צום לערנען און טאָן אין לערנען. מען מיינט נישט אין אַנדערע זמנים, אין זמן פון רוען דאַרף מען רוען, נאָר מען דאַרף טאָן אין לערנען בפועל ממש. מען דאַרף וועלן לערנען און קענען לערנען.\nאיר פאָרט ניט מיט אייגענע כוחות, מען גיט אייך כוחות.\nאיך וויל אייך אויפמערקזאַם מאַכן און בענטשן אייך, די תלמידים פון אייערע ישיבה, און די יוגענט פון שיקאַגאָ. זייט מצליח אין אייערע שליחות. פאָרט געזונט און זייט געזונט בגו\"ר.",[["256","1","ברשימה שתח\"י:. . 55:1."],["257","2","ע\"ד הישיבה בשיקאגא ונסיעת בחורים לשם — ראה לעיל ע' 3. וש\"נ."],["258","3","דוגמא."]]],[4301620206,"<h3>ליל א' דחג השבועות תש\"ו בסעודה </h3>\nא. ביז דעם יאָר תרנ\"ד, פלעגט דער טאַטע דאַוונען יעדען טאָג און שבת אין קליינעם זאַל<sup data-n=\"259\">1</sup>. דאָנערשטאָג ביינאַכט פלעגט ער אויף זיין אויך אין מנין (קליינעם זאַל), און אַמאָל פלעגט ער דאַן פאַרבריינגען מיט חסידים.\nדאָס איז געווען אַ דאָנערשטאָג ביינאַכט וואָס פאַר שבועות אין יאָר תר\"נ אָדער תרנ\"א — איך געדיינק ניט גענוי דעם יאָר, אָבער דאָס איז געווען אין יענעם יאָר וואָס איך האָב שוין געלערנט ביי ר' ניסן דער מלמד<sup data-n=\"260\">2</sup> (ר' ניסן איז געווען אַ גרויסער בעל שמועה, ער האָט געדיינקט אַפולע סיפורים און פלעגט די סיפורים פאַרצייכענען בכתב. ער האָט געהערט סיפורים פון זיין שווער<sup data-n=\"261\">3</sup> און עלטער שווער<sup data-n=\"262\">4</sup> וואָס איז געווען אַ חסיד ביים אַלטן רבי'ן. ר' ניסן האָט געהאַט אַ חוש אין סיפורים און",[["259","1","ראה קונטרס חנוך לנער ע' 12: התחל מערבית ליל ר\"ה תרנ\"ד קבע מקום תפלתו בביהכ\"נ במקום שהתפלל כ\"ק אביו אדמו\"ר מהר\"ש — עד אז התפלל במקומו המיוחד לו בביהכנ\"ס עוד בחיי אביו. וראה ספר השיחות תרצ\"א ע' 148. וש\"נ."],["260","2","ראה שיחת ליל אחש\"פ שנה זו (לעיל ע' 41). וש\"נ."],["261","3","ר' פסח מלמד — ראה רשימת היומן של רבינו מיום כ' אייר תרנ\"ו (לקמן ס\"ע 422 ואילך). ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 120. ע' 160. קיץ ה'ש\"ת ע' 69. וראה לקמן ע' 161."],["262","4","ראה רשימת היומן וספר השיחות קיץ ה'ש\"ת שם. לקמן ע' 240."]]],[4301620207,"האָט מייקר געווען אַ סיפור מער ווי אַ מאמר חסידות).\nיענעם דאָנערשטאָג ביינאַכט האָט דער טאַטע פאַרבראַכט און האָט געזאָגט: איך האָב משעבד געווען מיין צייט צום טאַטן דעם רבי'ן\n— אַמאָל פלעגט ער זאָגן: דעם טאַטן דעם רבי'ן, און אַמאָל פלעגט ער זאָגן: דעם רבי'ן דעם טאַטן (הכוונה צו די תורה ששמע ממנו) —\nאיך האָב געמיינט אַז איך האָב גע­מאַכט אַ גוטן אויסבייט<sup data-n=\"263\">5</sup>, איך בין מוחל... אַז מ'נעמט אַ ענין פון מוחין, דאַרף מען אַליין האָבן אַ חיות אין דעם, אָבער אַז מען הערט אַ סיפור גיט מען חיות.\nוסיפר אַז כ\"ק אאמו\"ר נ\"ע: אַז ווען מען האָט דעם רבי'ן (אדמו\"ר הזקן נ\"ע) מגלה געווען אין מעזריטש, ווער ער איז, האָט ער אָנגעהויבען טאָן, און האָט זיך מתגלה געווען אין נגינה<sup data-n=\"264\">6</sup>.\nדאַמאָלסט האָט דער טאַטע געזאָגט, אַז עס איז דאָ ג' אופנים אין ניגונים: אַ ניגון וואָס מען זינגט אין דאַוונען, אַ ניגון וואָס מאַכט דאַוונען און אַ ניגון וואָס מאַכט אַ דאַוונער.\nדער טאַטע האָט דאַמאָלסט דער­ציילט, אַז שבועות תר\"מ האָט דער זיידע (אדמו\"ר מהר\"ש נ\"ע) געזאָגט דעם טאַטען: ברי לי אַז דו וועסט האָבן אַ זון.\nאַז דער אַלטער רבי איז געקומען פון מעזריטש<sup data-n=\"265\">7</sup> און איז נאָכדעם געווען אין מינסק; האָט מען אים געפרעגט: וואָס האָט איר דאָרט מקבל געווען פאַר אַ חידוש אין תורה?\nהאָט ער זיי געענטפערט: וואָס מען האָט געקענט אויפטאָן אין תורה — האָט מען אויפגעטאָן, נאָר איר וועט אין דעם קיין טעם ניט האָבען. אָבער, ניט נאָר האָט מען אויפגעטאָן אין תורה, נאָר מען האָט געלערנט ווי מכבד זיין אַ בן תורה, און ווער איז אַ בן תורה, אַ איש פשוט<sup data-n=\"266\">8</sup>.\nדער טאַטע האָט אַמאָל געפרעגט דעם זיידן מהר\"ש: וואָס איז דער ענין פון פשיטות העצמות, עצמות איז דאָך פשוט. האָט אים דער זיידע מהר\"ש געענטפערט: עצמות איז פשוט, אָבער עצמות פילט מעלת העצמות, פשיטת העצמות מיינט דער עצם אַליין. האָט דער טאַטע דערציילט, אַז מיט דעם וואָרט האָט ער געדאַווענט אַ משך זמן רב.\nדער טאַטע איז דאָך געווען אַ רבי, דאָס וואָס מען האָט יעצט דערציילט איז דאָס דער טאַטע ווי ער איז געשטאַנען בדרגת חסיד.\nאיך האָב דאַמאָלסט געהערט אַ סאַך הויכע ענינים פון טאַטן אָבער איך האָב נאָך ניט געקענט אַלץ פאַרשטיין וואָס איך האָב געהערט, וואָס קען אַ צען יאָריג קינד פאַרשטיין.\nב. דער טאַטע האָט אַמאָל געזאָגט אין אַ פאַרבריינגען שבועות: \"וכל העם רואים את הקולות וגו'\"<sup data-n=\"267\">9</sup>, אין מתן תורה איז געווען רואים את הנשמע ושומעים",[["263","5","כנראה הכוונה מה שהקדיש את זמנו לשמיעת דרושים ולא לסיפורי חסידים. (המו\"ל)."],["264","6","ראה שיחת ליל א' ויום א' דחגה\"פ שנה זו (לעיל ע' 27. ע' 29)."],["265","7","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["266","8","ראה שיחת יום א' דחג השבועות שנה זו (לקמן ע' 46)."],["267","9","יתרו כ, טו."]]],[4301620208,"את הנראה<sup data-n=\"268\">10</sup>, ביי וועמען איז דאָס געווען, ביי \"וכל העם\", אנשים פשוטים. די לומדים און גאונים — זיי האָבן ערוואַרט צו הערן ביי מ\"ת אַ חידוש, אַ פלפול, וואָרום עס זיינען דאָך געווען לומדים פאַר מתן תורה אויך, ווי חז\"ל זאָגן<sup data-n=\"269\">11</sup>: \"אברהם כו' יושב בישיבה כו' היו במצרים ישיבה עמהם\" — לומדים און מצרים, נאָר מצרים'דיגע לומדים, אַז זיי זיינען געקומען צו מ\"ת האָבען זיי געמיינט אַז זיי וועלן הערן אַ חידוש, אַ פלפול.\nווער האָט דערהערט, אַז דורך תורה קען זיין רואים את הנשמע און שומעין את הנראה — די אנשים פשוטים, \"וכל העם רואים\". און די לומדים זיינען געבליבן פּעטאַכעס<sup data-n=\"270\">12</sup>...\nמען האָט אַמאָל געהערט ווערטער וואָס אפילו אין דער היים האָט מען עס ניט געקענט ריידן בגלוי נאָר בסתר.\nג. אַמאָל אין רוסלאַנד זיינען חסי­דים געווען רייך אין גשמיות און אין רוחניות, מען האָט געבעטן אויף גשמיות אָבער קיין סאַך האָט מען ניט פאַרלאַנגט, און עס האָט ניט געפעלט מער ווייניגער, זיינע יענעמס. און רוחניות האָט מען אַודאי געהאַט, מען איז געלעגען אין עבודה און מען האָט געהאַט אַ חיות אין דעם, משא\"כ במדינה זו חסר לגמרי ענין עבודה הרוחניות.\nדי סיבה אויף דעם איז די היגע סביבה, דער יעוז בהוותו<sup data-n=\"271\">13</sup>, עס איז אַלץ ווייניג, נאָך און נאָך, איך בין דאָך ניט קיין אַרומלויפער, איך זיץ ביי זיך אין חדר, דאַכט זיך וועמען זע איך, וועמען הער איך, מ\"מ בין איך צובראָכן פון דעם מצב אַרום, די הגברת החומר על הצורה וואָס איז דאָ ביי די היגע אידן, הגם זיי האָבן מעלות, זיי גיבן אויף הצלה און אויף פערשידענע החזקות, אָבער...\nהיינט שטעל איך מיר פאָר די צו­בראָכנקייט פון אַ בן תורה ושומר מצוות און בפרט אַ חסידישן איד וואָס גייט אין גאַס און זעט צו דעם אַרום, וואָס פאַר אַ צובראָכענקייט עס פועל'ט אויף אים וכו', עס איז אַ רעכטער עונש...\nד. פונדעסטוועגן האָבען די היגע אידן אַ סאַך מעלות, דעם דרך ארץ פנימי וואָס זיי האָבן פאַר אַ בן תורה און זיי זיינען חובבי תורה און שעמען זיך ניט דערמיט, אדרבא זיי יחוס'ן זיך דערמיט און זיינען מקרב בני תורה מיט אַ דרך ארץ פנימי, און אַ אמת דערהערן זיי און אַ שקר דערפילן זיי.\nבני תורה בכלל און תלמידי התמימים בפרט האָבן דאָ געקענט אַ סאַך אויפטאָן אויף מכניס זיין אור, הגם מען האָט ב\"ה אַ סאַך אויפגעטאָן, אָבער עס קומט גאָר ניט צו דעם וואָס מען האָט געקענט אויפטאָן, עס איז גאָר באין ערוך.\nמילא די ראשי ישיבות האָבען אויף זיך אַ שטאַרקען עול, און האָבען גענוג עגמ\"נ, בפרט דער וואָס איז טאַקע מסור ונתון, איז פאַראַן ווייניג נחת, עגמ\"נ פון ב\"ב, עגמ\"נ פון בעלי בתים אין שטאָט, און דער גרויסער חוב וואָס ליגט אויף זיי און נאָכאַלעמען מאָנט מען נאָך ביי זיי, אָבער די תלמידי התמימים האָבען דאָך געקענט אַ סאַך אויפטאָן.\nוויפיל הונדערטער תפילין מען האָט געקענט אָנטאָן אידן, איך מיין ניט",[["268","10","ראה מכילתא עה\"פ. וראה לקו\"ש ח\"ו ע' 120 הערות 6­5; ע' 122­121."],["269","11","יומא כח, ב."],["270","12","שוטים."],["271","13","ע\"פ תהלים נב, ט."]]],[4301620209,"שלעפּן אידן פון גאַס און אָנטאָן זיי תפילין, מען דאַרף קיינעם ניט מכריח זיין, בכלל דאַרף ניט זיין די עבודה בהכרח, נאָר מען דאַרף יענעם מאַכן אַזוי זיס און געשמאַק אַז ער זאָל אַליין וועלן, מען קען זייער אַ סאַך אויפטאָן מיט די היגע אידן.\nמען דאַרף אויך ניט צופרידענשטעלן מיט דעם וואָס מען האָט ב\"ה שוין אויפגעטאָן, נאָר דער דערהער דאַרף זיין וואָס מען האָט נאָך ניט דערטאָן, וואָס איז נאָך שלא בערך וואָס מען האָט אויפגעטאָן. און דערפאַר זיינען זיי ווערט שמיצלעך, ניט בכעס חלילה, נאָר ווי אַ טאַטע שמייסט זיין קינד נאָכדעם ווי ער האָט אים פאַרהערט און האָט גוט געוואוסט — אַזוי, אויב דאָס האָסטו געקענט ניט­ווילענדיגערהייט, היינט ווי אַזוי וואָלסטו אויפגעמאַכט ווען דו ווילסט נאָך<sup data-n=\"272\">14</sup>.\nה. ווען איך בין געווען נאָך גאָר אַ קליינער אינגעל, האָט דער טאַטע מיר געזאָגט שבועות ביינאַכט: היינט דאַרף מען אויף זיין אַ גאַנצע נאַכט און זאָגען תיקון. היינט גיט מען זייער אַ סאַך, מען זאָל נאָר אַזויפיל וועלען נעמען וויפיל מען גיט היינט ביינאַכט<sup data-n=\"273\">15</sup>.",[["272","14","ראה גם שיחת יום ב' דחג השבועות שנה זו (לקמן ע' 50)."],["273","15","ראה גם ספר השיחות תורת שלום ע' 3."]]],[4301620210,"<h3>יום א' דחג השבועות תש\"ו בסעודה </h3>\nא. הרש\"ל שי'<sup data-n=\"274\">1</sup> שאל ע\"ד מה שסיפר כ\"ק אדמו\"ר שליט\"א אתמול<sup data-n=\"275\">2</sup> בשם אדמו\"ר הזקן נ\"ע שבמעזריטש למדו איך לכבד \"בן­תורה\" וכו' אם זהו מצד מעלת הנשמות על התורה?\nוענה כ\"ק אדמו\"ר שליט\"א: אויב פשט, דאַרף מען דאָך אַליין פאַרשטיין...\nב. אין יאָר תרנ\"ו האָט דער טאַטע געזאָגט דעם מאמר ועשית חג שבועות<sup data-n=\"276\">3</sup>, והקשה<sup data-n=\"277\">4</sup> מהו ועשית<sup data-n=\"278\">5</sup>, וואָס איז שייך צו מאַכען דעם חג שבועות<sup data-n=\"279\">6</sup>, והתירוץ ע\"ז שבועות הו\"ע מעלת תיקוני המדות.\nג. דער אַלטער רבי, נאָך פאַר מעזריטש, ווען ער איז נאָך געווען אַ יונגער אינגל, איז ער געווען אַ גרויסער מנגן. ער פלעגט זינגען די ניגונים וועלכע ער פלעגט הערען פון די אורחים, עוברים ושבים, וואָס פלעגן אַריינקומען צו זיין טאַטן ר' ברוך, וואָס זיי זיינען געווען די צדיקים נסתרים שלוחים פון בעש\"ט נ\"ע. דער אַלטער רבי האָט דאַן ניט געוואוסט פון בעש\"ט און האָט ניט געוואוסט אַז זיין טאַטע ר' ברוך איז אַ בעל שם'סקער איד<sup data-n=\"280\">7</sup>. דאַמאָלסט איז געווען די צייט פון איבערגאַנג פון צדיקים נסתרים צו התגלות, דער בעש\"ט ענינו איז געווען להתגלות. די אורחים צדיקים נסתרים וואָס פלעגן קומען צו ר' ברוך'ן אין הויז זיינען געווען שלוחים פון בעש\"ט צום",[["274","1","ראה אודותו לעיל ע' 9."],["275","2","לעיל ע' 44."],["276","3","נדפס בסה\"מ תרנ\"ו ע' שנ."],["277","4","סה\"מ שם ע' שנא."],["278","5","שתלוי בעשיית האדם (סה\"מ שם)."],["279","6","והלא שבועות הוא זמן מתן תורתינו אשר מ\"ת הי' בבחי' אתעדל\"ע שלמעלה מאתדל\"ת (סה\"מ שם)."],["280","7","ראה גם שיחת פורים שנה זו (לעיל ע' 23)."]]],[4301620211,"קינד (היינו אדמו\"ר הזקן נ\"ע) בנוגע הוראות צו זיין חינוך וכדומה<sup data-n=\"281\">8</sup>.\nדער אַלטער רבי קליינערהייט האָט זייער ליב געהאַט פעלד<sup data-n=\"282\">9</sup>. ער איז געווען אַ איש שדה. ווען ער פלעגט אַרויסגיין פון חדר וואו ער האָט געלערנט, פלעגט ער ניט גיין אַהיים, נאָר פלעגט אַוועק­גיין אין פעלד און דאָרטן פלעגט ער ווייטער לערנען.\nשפּילן זיך איז באַ אים ניט שייך געווען, ער האָט קיינמאָל ניט געשפּילט. ער פלעגט זאָגן: אַז מען גיט אַ קוק אויפן הימל און מען דערמאָנט זיך אַז \"השמים כסאי\"<sup data-n=\"283\">10</sup>, און אַז מען גיט אַ קוק אויף די ערד וואָס \"והארץ הדום רגלי\", היינט ווי קען מען זיך שפּילן...\nאיז זייענדיק אין פעלד פלעגט ער זיך אָפט אויסזינגען. עס איז דאָ זינגען, און אויסזינגען זיך<sup data-n=\"284\">11</sup>. דער אַלטער רבי האָט געזאָגט, אַז פנימיות הנפש קען זיך אויסזינגען אין אַ ניגון.\nאין יאָר תרנ\"ד, ביי אַ פאַרבריינגען, האָט דער טאַטע געזאָגט, אַז עס איז הונדערט יאָר, זינט דער אַלטער רבי האָט געזאָגט דעם וואָרט: אַ ניגון קען אַרויסשלעפּען פון די טיפסטע בלאָטע.\nדער טאַטע האָט דאַמאָלסט מבאר געווען דעם ענין פון מאה שנים.\nד. איך האָב געהערט פון טאַטן, וואָס ער האָט געהערט פון זיין טאַטן דער זיידע מהר\"ש, וואָס ער האָט געהערט פון הר' אייזיק וויטעפּסקער<sup data-n=\"285\">12</sup>, אַז איינער פון די גדולי המתנגדים האָט געפרעגט דעם אַלטן רבי'נס חסידים, וואָס האָט אייער רבי אויפגעטאָן און מחדש געווען? האָבען זיי געענטפערט: דער רבי האָט אויפגעטאָן אַנשטאָט רעדען טראַכטען. וואָס מיינט דאָס? אַנשטאָט רעדען מעלות עצמו, טראַכטען וועגען מעלות פון דעם אויבערשטען.\nדער אַלטער רבי האָט מבאר געווען צום צמח צדק ב' ענינים די מעלת העצמות און די מעלת הנשמות, וואָס אין חסידות איז מבואר, אַז ביידע זיינען דרכי עבודה אין עבודת ה'.\nה. דער רבי און די רביים האָבען געגעבען און גיבען אַלע מיני כלי­זיין און תכסיסי מלחמה צו חסידים, זיי האָבען פאַרזאָרגט חסידים מיט אַלץ און זיי געגעבען כחות. חסידים זיינען קלוגע, וואָס איז דער וואונדער אַז חסידים זיינען קלוגע, נאָך די גרויסע כחות וואָס די רביים האָבען אויף מדריך זיין חסידים, איז דאָך אפילו אַ שוטה גמור געקענט ווערען אַ חכם עתיק, נאָר מען דאַרף טאָן. אויב נאָך די אַלע כחות וואָס די רביים האָבען געגעבען צו חסידים טוט מען ניט, איז דאָס טאַקע אַ פאַרברעך, אַסאַך ערגער ווי מ'וואָלט גאָר ניט געגעבען. אַז מען האָט דיר יע געגעבען",[["281","8","ראה גם שיחת ליל ש\"ק חוה\"מ סוכות תש\"ז ס\"ו (לקמן ע' 68)."],["282","9","ראה גם אגרות­-קודש ח\"ו ס\"ע תיז ואילך. ספר השיחות קיץ ה'ש\"ת ע' 129. תש\"ד ע' 118. לקמן ע' 68."],["283","10","ישעי' סו, א."],["284","11","ראה גם שיחת י\"ב תמוז שנה זו (לקמן ע' 52)."],["285","12","הרה\"ח ר' יצחק אייזיק (בהרד) בהרב ר' ישעיה מתמיד (תלמידו של בעל סדר הדורות). נולד בסמילאוויטש שנת תקכ\"ח. רב באסטראוונע ואח\"כ בוויטעפּסק, נפטר שם בן צ\"ח שנה בשנת תרכ\"ו. בעה\"מ שו\"ת פני יצחק (ע\"פ רשימת רבינו — ויכוח מינסק. ספר השיחות קיץ ה'ש\"ת ע' 78 בהערה). — ראה אודותו \"התמים\" חוברת ד ע' כח [קעט, ב] ואילך. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ס\"ע 295 ואילך. קיץ ה'ש\"ת שם. שיחת י\"ב תמוז תש\"ח (לקמן ע' 250)."]]],[4301620212,"אַזעלכע כחות דאַרף מען דאָך טאַקע טאָן.\nו. דער זכור ימות עולם<sup data-n=\"286\">13</sup> פון חסידים איז זייער אַ רייכער. אַז מען רעדט חסידות איז דאָך אין למעלה הימנו, אַז מען רעדט אין עבודה, איז דאָך דאָס די זעלבע זאַך, וואָרום חסידות אָן עבודה איז דאָך גאָרניט, עבודה אָן חסידות נו..., אָבער אַז מען רעדט וועגן דעם זכור ימות עולם פון חסידים מאַכט דאָס אַ שינוי אין לעבן, און אַז מען בריינגט אַראָפּ דעם עבר אין הוה מאַכט דאָס אַ ליכטיגן הוה.",[["286","13","ע\"פ האזינו לב, ז."]]],[4301620213,"<h3>יום ב' דחג השבועות תש\"ו </h3>\nא. ביים טאַטן זיינען געווען מנהגים גלויים און מנהגים נסתרים, אַזעלכע ענינים וואָס ער האָט געטאָן בסתר, אַז קיינער האָט גאָרניט געוואוסט און גאָרניט מרגיש גיווען, וואָרום עס איז דאָ אַ סוד וואָס הגם מען ווייסט עס ניט, אָבער מען איז מרגיש אַז עס איז דאָ עפּעס אַ דבר הנעלם, אָבער ביי דעם טאַטען האָט מען גאָרניט מרגיש געווען<sup data-n=\"287\">1</sup>, ווייל ער האָט ניט געוואָלט, אַז מען זאָל נמשך ווערען נאָך ענינים חיצונים, ער האָט געמאָנט אמת.\nדער טאַטע האָט געזאָגט, אַז חסידות האָט אַ ראַמעלע<sup data-n=\"288\">2</sup> וואָס דאָס איז עבודה; און עבודה מוז זיין באמת, וואָרום אויב ניט איז דאָס קיין עבודה ניט. עס איז דאָ שקר אין רע און עס איז דאָ שקר אין טוב, אַז מען נעמט אָן אַ דרגא אין עבודה וואָס איז לעילא מדרגי' איז דאָס שקר.\nכאן הפסיק כ\"ק אדמו\"ר שליט\"א לדבר הענין מפני האורחים מזקני אנ\"ש שבאו להחדר, וציוה כ\"ק אדמו\"ר שליט\"א ליתן להם ספסלים לישב, ואמר בשחוק קל: אין אַמעריקא איז אַ באָרד אַ יחוס, בפרט אַ סיווער באָרד<sup data-n=\"289\">3</sup>.. .\nאח\"כ חלקו משקה להאורחים ואמר: לחיים.\nב. ווען דער אַלטער רבי איז געקו­מען פון מעזריטש<sup data-n=\"290\">4</sup>, האָבען די גאוני וויטעפּסק ביי אים געפרעגט וואָס ער האָט מקבל געווען אין מעזריטש — זיי האָבען געוואוסט אַז דער אַלטער רבי איז אַ גאון, אַ גאון הגאונים, און זיי פלעגן מיט אים אָפט ריידן אין לערנען.\n— דער ווילנער גאון איז געווען אַ פאַר­זיך'דיגער און פלעגט אויסמיידען צו ריידען מיט יעדען, ער האָט מייקר געווען דעם זמן און פלעגט שרייען: וואָס האָט איר צו מיר, לאָזט מיר אַליין. ער פלעגט זשאַלעווען די צייט און ניט געוואָלט מען זאָל אים מבלבל זיין פון חידושי תורה, און פלעגט ריידען מיט איינעם נאָר ווען ער האָט גערעכענט צו מקבל זיין פון אים אַ נייעס אין חידושי תורה. ווען מען האָט געדרוקט די שו\"ת צמח צדק, האָט דער זיידע מהר\"ש",[["287","1","להעיר מג' הדרגות בבעל סוד — ראה ספר השיחות תש\"ג ס\"ע 91 ואילך."],["288","2","מסגרת."],["289","3","ראה גם שיחת ט\"ו מנחם­אב תש\"ז (לקמן ע' 147)."],["290","4","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."]]],[4301620214,"געהייסן משמיט זיין אַ בלעטל פון כת\"י וואו דער צמח צדק בריינגט אַראָפּ דעם גר\"א און שרייבט דאָרט אַז זיין התמדה אין לערנען איז געווען אַזוי גרויס, אַז ער איז בלויז געשלאָפן צוויי און אַ האַלב שעה אין מעת לעת<sup data-n=\"291\">5</sup>. האָט דער זיידע מהר\"ש געזאָגט: אָט דאָס איז אַ פלא פאַר אַ גאון? —\nהאָט דער אַלטער רבי געענטפערט, אַז אין מעזריטש האָט ער מקבל געווען, וואָס דער אויבערשטער איז און וואָס אַ איד איז, דעם יוקר פון אַ אידען ביים אויבערשטן און די טייערקייט פון אויבערשטן ביי אַ אידן. פריער איז אויך געווען אהבת ישראל, אָבער דאָס איז געווען מצד יוקר התורה, מען האָט ליב געהאַט אַ אידן מצד זיין ידיעת התורה, איז במילא געווען צוויי זאַכן: דער איד און זיין ידיעת התורה. חסידות האָט אויפגעטאָן — אהבת ישראל, ליב האָבן אַ איד ווייל ער איז אַ איד<sup data-n=\"292\">6</sup>. ביי מתן תורה האָט דער אויבערשטער בוחר געווען אין אידן, עם סגולה לה' אלקיך<sup data-n=\"293\">7</sup>, איז דאָך געווען די בחירה אין די אידן מצד העצם, ווייל זיי זיינען אידן, און אַזוי דאַרף זיין אהבת ישראל מצד ווייל ער איז אַ איד.\nלגבי דעם אויבערשטן זיינען דאָך אַלע כעמי הארצים, איז דאָך במילא ניט שייך קיין יחוסים, נאָר מען דאַרף ליב האָבן דעם וואָס דער אויבערשטער האָט בוחר געווען<sup data-n=\"294\">8</sup>, וואָס צוליב אים האָט דער אויבערשטער באַשאַפען אַלע עולמות און געגעבען די תורה, און דאָס איז אַ איד בעצם.\nדער בעש\"ט האָט ליב געהאַט אַ אידישן גוף, און האָט געזאָגט, אַז ווען ער האָט אָנגעהויבען וויסן אַז ער איז אַ חשוב למעלה האָט ער גלייך אָנגעהויבן בעטן אַז דער אידישער גוף זאָל געזונט זיין.\nדער בעש\"ט פלעגט זאָגען יעדן טאָג אַ ברכה, אַז אידן זאָלן זיין געזונט פשוט אין גוף, און דאָס איז אהבת ישראל עפ\"י חסידות.",[["291","5","באגרות­-קודש אדמו\"ר הצ\"צ ח\"ב ע' קז: \"הגר\"א ישן ג' חצאי שעה בלתי רצופי' וגם באותן ח\"ש שפתיו מרחשן כו'\" (מובא בהקדמת בני הגר\"א (המבלבה\"ד) לביאור הגר\"א לשולחן ערוך — שקלאוו תקס\"ג).\nוביומנו של הרה\"ח ר' ברוך שניאור שניאור­סאהן<sup data-n=\"e10\">*</sup> בן הרב לוי יצחק נכדו של אדמו\"ר הצ\"צ ש\"ביום ש\"ק [פ' תשא תרע\"ה] אמרתי לו\" (לאדמו\"ר מהורש\"ב): \"שמעתי מאביו כ\"ק דודי אדמו\"ר מהר\"ש נ\"ע. . שהגר\"א מווילנא הי' ישן ג' חצאי שעות במעת­לעת, והי' בסירוגין. ועל כ\"ק רבינו הזקן שהי' יכול לישן ולא לישן כלל. . ואמר כ\"ק [מהורש\"ב] שליט\"א שלאו דוקא על הגר\"א מוילנא כיוון זה, כי זה מצאנו בכי\"ק אדמו\"ר הצמח צדק נ\"ע, והי' כתוב סתם הגר\"א, והי' זה על ר' אברהם מקאליסק ז\"ל, תלמיד המגיד ממעזריטש נ\"ע\"."],["292","6","ראה שיחת ליל אחש\"פ שנה זו (לעיל ע' 40). וש\"נ."],["293","7","ע\"פ יתרו יט, ה. ואתחנן ז, ו. פ' ראה יד, ב. תבוא כו, יח."],["294","8","ראה אגרות­-קודש ח\"ג ע' תכה. הועתק ב\"היום יום\" כח ניסן."],["e10","*","ע\"ד רשימותיו של ר' ברוך שניאור — ראה ספר השיחות תש\"ה ע' 4: \"הרב\"ש האָט מיר דאן איבערגעגעבן די רשימות וואָס זיינען געווען ביי אים פאַרצייכנט, וועגן אַלץ וואָס ער האָט געהערט און געזען ביי הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש און ביי הוד כ\"ק אאמו\"ר הרה\"ק. ער פלעגט אַזוי מדייק זיין אין פאַרצייכענען, אַז צווישן די רשימות זיינען אויך געווען אַזעלכע פאַרצייכענונגען: אין דעם און דעם טאָג בין איך אַריינגעגאַנגען צום פעטער כ\"ק אדמו\"ר און ער האָט מיר געזאָגט גוט יום טוב\"."]]],[4301620215,"דער טאַטע האָט אַמאָל גערעדט אַז עס איז דאָ אהבת ה', אהבת התורה און אהבת ישראל. און האָט אויסגעפירט, אַז אָנהויבן דאַרף מען פון אהבת ישראל.\nג. שבועות איז מתן תורה און קבלת התורה. דער אַלטער רבי האָט געזאָגט: מיר זיינען ניט געווען זשעדנע<sup data-n=\"295\">9</sup> אין גאונים, און מיר האָבען אויך געוואוסט פירוש המלות, אָבער דעם אמיתית'­דיגען פירוש המלות פון מתן תורה און קבלת התורה האָבען מיר געהערט אין מעזריטש.\nד. שבועות איז קבלת התורה און שמירת התורה. יעדען שבועות ווערט נמשך אַ המשכה חדשה אין תורה, וואָס די המשכה חדשה איז אַ המשכה עצמית — ניט אַ גילוי פון סדר השתלשלות, נאָר המשכה עצמית.\nה. די תמימים דאַרפען וויסען דעם צד הזכות וואָס זיי האָבען, וואָס מ'האָט זיי איבערגעגעבען די אַרבעט פון הרבצת תורה, מ'האָט ב\"ה אַסאַך אויפ­געטאָן. די וואָס מיינען אַז זיי האָבען ניט קיין כחות אויף דעם — זיינען טועים, די וואָס מיינען אַז זיי טוען דאָס בכח עצמן איז אויך ניט אמת, מען גיט זיי כחות און מען האָט ב\"ה אויפגעטאָן, אָבער קיין צופרידנקייט דאַרף ניט זיין. אַז מען איז צופרידען נעמט עס צו די תשוקה צו די ווייטערדיגע עבודה. מען דאַרף דער עיקר דערהערן, וואָס מ'האָט נאָך ניט געטאָן. אָט אַזוי ווי אַ טאַטע גיט אַ קניפּ אין באַק זיין אינגל נאָכ'ן פאַרהערן, זאָגנדיג: אויב דו מאַכסט יע אַזוי גוט, איז אַז דו וואָלסט וועלן וואָלסטו דאָך געמאַכט נאָך בעסער<sup data-n=\"296\">10</sup>.\nו. איך וויל ניט זאָגן מיט דעם לשון, אַז מיר האָבן געהאַט ליכטיקערע אויגן, נאָר מיר האָבן זיך מער דערגרונטעוועט צו דעם תוך פון די היגע אידן. פריער האָט מען געמיינט, אַז מיט די היגע אידן קען מען שוין גאָרניט אויפטאָן, דער אמת איז ניט אַזוי, ביי די היגע אידן איז פאַראַן די תמימות און דרך ארץ פנימי פאַרן אמת.\nאַז מען רעדט מיט זיי וועגען שמירת שבת דערנעמט עס זיי און זיינען זיך מתנצל מצד הפרנסה.\nאַז זיי קומען אַהיים פון ביהמ\"ד דערציילען זיי מיט אַ התפעלות, אַז אין ביהמ\"ד איז געווען אַ חזן אָדער אַ בעל קורא, אוי האָט ער געדאַוונט, אוי האָט ער געלייענט, עס איז געווען אַ געשמאַק צו הערן, איז דער סיפור מאַכט ליכטיקער די היים.\nז. ברכה (ד' ענינים<sup data-n=\"297\">11</sup>).",[["295","9","קמצנים."],["296","10","ראה גם שיחת ליל א' דחג השבועות שנה זו (לעיל ע' 46)."],["297","11","חסר."]]],[4301620216,"<h3>יום ה' בצהריים, כ\"א סיון תש\"ו<sup data-n=\"298\">1</sup> </h3>\nבכלל צ\"ל התגברות הצורה על החומר בכל הענינים, הן בהתעסקות בעניני הכלל וגם בענינים כאלו אשר עושים במס\"נ צ\"ל התגברות הצורה על החומר.\nוסיפר כ\"ק אדמו\"ר שליט\"א אשר<sup data-n=\"299\">2</sup> פעם הי' אצל אאמו\"ר נ\"ע, אשר היו צריכים להתראות עם איש א' בפּעטער­בורג, והוא הי' דר מחוץ לעיר. זמן ה­התראות הוקבע על ליל ש\"ק אשר דוקא אז הייתי צריך להתראות אתו. שם לא הי' האָטעל'ס, רק בתי מרזח, והוכרחתי לבוא לשם בערש\"ק ושלמתי להם כמובן עבור הש\"ק ועוד יותר עבור ההליכה, כי הי' רחוק משם מהלך איזה שעות, ואח\"כ בלילה הלכתי לשם ע\"י לוי' ושהיתי שם איזה שעות, ודברנו מה שדברנו.\nכ\"ז הי' בלי הרגש, הן אצל המשלח — אף שהי' דער טאַטע, און זיינער אַ קינד אַ בן יחיד, והוא הלא ידע בוודאי וואָס הייסט זיין קינד און אַ בן יחיד, ומ\"מ הי' בלא הרגש, ניט באַ עם און ניט באַ מיר. נאָר ווייל אַזוי האָט מען געדאַרפט טאָן האָט זיך געטאָן, ווייל עס איז געווען התגברות הצורה על החומר.\nאט אַזוי איז געווען אין ליובאַוויטש, און אַזוי איז דער דרך החסידות.\nדאָס לערנט אונז דער דרך החסי­דות, דאָס איז אפילו באַ יונגעלייט, און בפרט אַז מען ווערט עלטער און בפרט אַז מען איז אַן עלטערער דאַרף זיין די התגברות הנשמה על החומרי. מען רעדט מיט דעם נוער מיט די יונגע, איז הגם פון אָנהויב דאַרף מען דאָך ריידן זייער שפּראַך בההברה הַה ?ַה, אָבער מען דאַרף מיט זיי ריידן ביז וואַנען זיי זאָלן זיך אויסצולערנען ריידן ווי אַ מענטש.\nכמו\"כ גם בענין המעמד, אף שצרי­כים לממון לבד ענין ההוצאה, ולבד מה שצריכים על ענינים כאלה וואָס מען וויל ניט אויסזאָגן און מען דאַרף ניט אויסזאָגן און מען קען ניט זאָגן, מ\"מ העיקר צ\"ל הצד הרוחני שבזה והגשמיות הוא בדרך ממילא.\nאיך בעט אייך זעט עס זאָל זיין התגברות הצורה על החומר, און אויף דעם זייט איר שלוחים, און איך גיב אייך מיינע כחות און די כחות פון מיינע עלטערן.\nפאָרט געזונטערהייט, און פאָרט בשמחה ובטוב לבב.\nפאָרט געזונט און זייט געזונט און קומט געזונט.",[["298","1","\"בעת כניסתנו לקבל ברכת הפרידה\". — מרשימת הרה\"ח ר' אליהו (ייאכיל) סימפסאָן (נולד ר\"ח תמוז תרמ\"ט. נפטר נר ה' דחנוכה תשל\"ז). מהחוזרים בליובאַוויטש. משנת תרפ\"ג רב בניו יאָרק. ממייסדי \"אגודת התמימים\" בארה\"ב. ומפעילי אגודת חסידי חב\"ד בארה\"ב. משנת ה'ש\"ת ואילך — ממזכירי רבינו."],["299","2","ראה בארוכה שיחת יום שמח\"ת תש\"ח (לקמן ע' 177 ואילך)."]]],[4301620217,"<h3>חג הגאולה י\"ב תמוז תש\"ו </h3>\nא. אמר: לחיים, דער אויבערשטער זאָל העלפען אַז דער אור החסידות זאָל דאָ מאיר זיין ווי אין די \"אַלטע היים\". דער אויסדרוק \"אַלטע היים\"<sup data-n=\"300\">1</sup> האָט אַ אמת'ן פשט, דער פשט פון \"אַלטע היים\" מיינט שרש ומקור הנשמה קודם ירידתה למטה. בכלל די כוונה פירט זיך אויס, און וועט זיך אויספירען, נאָר אַמאָל גיט דער טאַטע אַ שמיץ, זאָל דער אויבער­שטער העלפען אַז עס זאָל זיין בחסד וברחמים מתוך שמחה.\nב. אין סדר השתלשלות החסידות — מעת שנתיסדה ע\"י אדמו\"ר הזקן — פאַרנעמט נגינה זייער אַ חשוב'ן אָרט. ווען דער אַלטער רבי איז געקומען דאָס ערשטע מאָל פון מעזריטש<sup data-n=\"301\">2</sup> האָט ער גלייך אָנגעפאַנגען מיט ניגונים<sup data-n=\"302\">3</sup>. דער אַלטער רבי איז געווען אַ מנגן נפלא, ניט נאָר וואָס ער האָט געוואוסט די כללי הנגינה, נאָר ער האָט אויך געוואוסט דעם \"ענין\" פון נגינה.\nווען דער רבי דער צמח צדק איז נאָך געווען אַ קינד האָט ער געפרעגט ביים זיידען — דעם אַלטן רבי'ן, וואָס איז אַ איד? והשיב לו אדמו\"ר הזקן: אַ איד איז, וואָס קען מגלה זיין, זיין שרש הנשמה.\nדער ענין פון עבודת החסידות איז קענען זיך, און טאָן מיט זיך. ניט נאָר קונה זיין מדות טובות, וואָס מדות טובות מיינט ניט נאָר מדות טובות ווי ע\"פ דיני התורה, נאָר מדות טובות ווי ע\"פ חסידות. דאָס איז טאַקע גאַנץ גוט, אָבער דאָס איז נאָך ניט אַ חסיד — עבודה פון אַ חסיד איז קענען \"זיך\", און דאָס איז — דורך אַ ניגון. אַ ניגון ווייזט אים וואו ער איז, ווי ער דאַרף זיין און וואו ער קען זיין. וואָס דאָס איז ע\"י התגלות העצם — עצם הנשמה. ניגון איז אַ פתח ושער וואָס עי\"ז קען מען צוקומען צו דעם וואו מ'דאַרף זיין. נגינה מיינט מען ניט נאָר זינגען, נאָר מען מיינט \"אויסזינגען זיך\"<sup data-n=\"303\">4</sup>, וואָס די התגלות העצם זינגט זיך אויס אין אַ ניגון.\nאין נגינה איז פאַראַן ניגונים של שמחה און ניגונים של מרירות. וואָס די ביידע, שמחה און מרירות, האָבען זייערע זמנים ידועים וקבועים, יעדע אין זיין צייט, נאָר בכלל איז דער ענין פון נגינה — התגלות העצם.\nג. דער ענין פון אַ חסיד איז לערנען. מען דאַרף לערנען חסידות, ע\"ד ווי דער לימוד הנגלה אַזוי דאַרף זיין דער לימוד החסידות<sup data-n=\"304\">5</sup>, דער טאַטע האָט מייסד געווען תומכי-תמימים מ'זאָל וויסען וואָס הייסט לערנען און ווי אַזוי מ'דאַרף לערנען אַז דער אור התורה זאָל אים בעלייכטן. מען דאַרף דאָס דערנאָך אַראָפּטראָגן אין עבודת הלב, נישט קיין אָפּגעהאַקטע קעפּ.",[["300","1","ראה גם שיחת י\"ט כסלו תש\"ז (לקמן ע' 96) הערה 46. י\"ט כסלו תש\"ח סי\"א (לקמן ע' 184)."],["301","2","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."],["302","3","ראה גם שיחת פורים ושיחת יום א' דחגה\"פ שנה זו (לעיל ע' 24. ע' 29)."],["303","4","ראה שיחת יום א' דחג השבועות שנה זו ס\"ג (לעיל ע' 47)."],["304","5","ראה שיחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע שמח\"ת תרנ\"ט בשעת הקפות — בקשר לקריאת שם הישיבה \"תומכי­תמימים\" — נעתקה באגרות­-קודש ח\"י ע' ד. ע' שסח. ספר השיחות תרפ\"ח­תרצ\"א ס\"ע 75 ואילך. ועוד."]]],[4301620218,"חסידות איז ניט מיט מקיפים, מען איז מסתפק במועט, מען איז דאָך אַ איד, ער איז אַ חסיד, מתנהג במדות חסידות, ער דאַווענט, שבת איז ער אַביסל מאריך בתפלה, ער גיט אַ קרעכץ אַ חסידישן קרעכץ, ער גיט אַ טאַנץ, ניט דאָס איז אַ חסיד, עס מוז זיין עבודה ויגיעה.\nד. ווען מען וואָלט געוואוסט דרכי החסידים, וואָלט מען געוואוסט, אַז אַ ניגון דאַרף מען זינגען ניט געאיילט. אַ ניגון מיינט ניט הויך געשריען, אַ ניגון דאָס איז חיות. אַמאָליגע חסידים ביי אַ פאַרבריינגען, אַ התועדות, פלעגן זינגען אַ ניגון, האָט דאָס זיי אינגאַנצן גענומען. נאָכדעם איז מען געגאַנגען אַ טאַנץ, ניט סתם אַ טאַנץ, נאָר אַ מוחין'דיקער טאַנץ מיט אַלע כחות הנפש, די פיס האָבען זיך אַליין געהויבען. ניגון איז אַ הכנה צו עבודה, דאָס איז נאָך ניט עבודה, נאָר אַ הכנה צו אמת'ער עבודה.\nה. דורך די צייט האָט זיך שוין ב\"ה אַ פולע אויפגעטאָן, אָבער דאָס איז נאָך ניט דאָס וואָס עס דאַרף זיין, ווען איך האָב געדאַרפט פאָרן אַהער אין די מדינה האָב איך געוואוסט די גרויסע סכנה וואָס דאָ איז דאָ און אויך איצטער איז נאָך זייער שווער.\nזייט זיך משער אַז ביי 60 יאָר אין מיין לעבען האָב איך זיך בעדאַרפן איבער­ברעכן ווי אַ קליינער אינגל, אָבער בחסד השי\"ת, פירט זיך אויס מיין שליחות.\nאיצטער דאַרף מען מאַכן אין די מדינה, ליובאַוויטש. מ'דאַרף האָבען אריכות ימים אָבער מ'דאַרף מייקר זיין יעדע רגע. די היגע געבאָרענע האָבען מעלות נשגבות מעלות נפלאות, נאָר זיי מיינען אַז אַמעריקע איז אַנדערש<sup data-n=\"305\">6</sup>.\nדי תלמידים וואָס קומען איצטער אהער אין די מדינה, דאַרפען וויסען וואָס זייער עבודה איז דא. זיי דאַרפען ניט וועלען זיך אָפּזונדערען אין אַ באַזונדערע סביבה נאָר אדרבה מקרב זיין אַנדערע. מ'דאַרף ניט זיין בהרמת רוח, פילן זיך פאַר אַ מנהיג אַ פירער וכו'. די וואָס קענען ניט די שפת המדינה, דאַרפען ניט וועלן קענען די שפת המדינה. מילא די היגע געבאָרענע וואָס קענען די שפת המדינה דאַרפען דאָס אויסניצען אויף מקרב זיין אידישע קינדער און משפיע זיין אויף זיי. די תלמידים וואָס קומען איצטער אָן אַהער, דאַרף זייער עבודה זיין אויף מאַכען דאָ ליובאַוויטש. יאָ! מ'דאַרף האָבען אייגע­נע ד' אמות, אָבער מ'האָט שוין אַמאָל גערעדט אַז ד' אמות מיינט ניט נאָר ד' אמות, די ד' אמות קענען זיין טויזענ­טער וויאָרסטען.\nו. איר תלמידי התמימים דאַרפט אָנפאָנגען טאָהן אין עבודה. איר דאַרפט וויסען אַז דער טאַטע איז אחר כתלינו<sup data-n=\"306\">7</sup>.\nאַ הונגעריגער, וואָס ער עסט, עסט ער מיט אַ חיות, ווייל ער ווייסט אַז דאָס עסען, וואָס ער זאָל זיין, איז אים מחי', אַ מאכל איז דאָך משביע. דאָ אין אַמע­ריקאַ איז מען צו גיך זאַט געוואָרען.\nמ'דאַרף האָבען עבודה ויגיעה, האָרעווען אויף פאַרשטיין אַ וואָרט. ע\"ד ווי אין נגלה איז פאַראַן די קושיא און דער תירוץ און פון דעם קומט צו אַ נייער ענין, כמו\"כ צ\"ל בלימוד החסידות לערנען מיט אַ געשמאַק האָבען אַ חיות",[["305","6","ראה ספר השיחות תש\"ג ע' 147. תש\"ה ע' 77. ב' דחול המועד פסח תש\"ח (לקמן ע' 212). אגרות­-קודש אדמו\"ר מהוריי\"צ ח\"ז ע' שלו. ח\"ח ע' קיח. ע' קכה. ח\"ט ע' ד. ח\"י ע' שצב. לקו\"ש ח\"ו ע' 364. ועוד."],["306","7","ע\"פ שה\"ש ב, ט."]]],[4301620219,"אין אַ וואָרט חסידות, מען דאַרף זיך גריבלען אין אַ וואָרט חסידות.\nדער טאַטע האָט אַמאָל באַ אַ פאַר­בריינגען שמח\"ת גערעדט ביחוד לראשי ישיבות. האָט זיך איינער אָנגערופן — איך וויל ניט פורש זיין בשמו — וואָס וועט זיין מיט מיר, האָט דער טאַטע אים געענטפערט: דאָס פרעגט מען ניט ברבים. ואמר הנ\"ל: הייסט דאָס אַז מען דאַרף גיין אין קאַמער<sup data-n=\"307\">8</sup>, ואמר לו: יע.\nמ'דאַרף אָנהויבן אָפט פאַרבריינגען צווישען זיך און אָן משקה<sup data-n=\"308\">9</sup>, זינגען אַ ניגון און ריידען דברי התעוררות. הרה\"ח ר' הענדל<sup data-n=\"309\">10</sup> פלעגט פאַרבריינגען זייער אַ סאַך, וסדרו הי'<sup data-n=\"310\">11</sup> אשר תיכף אחר חג הפסח הי' קונה סאָטקע<sup data-n=\"311\">12</sup> יי\"ש, און צו יעדער פאַרבריינגען פלעגט מען אַרויף שטעלן אויפן טיש די סאָטקע מיט גלעזלעך, און אַזוי האָט מען דאָס אַראָפּגענומען פון טיש. ביז ערב פסח פלעגט ער דאָס מבער זיין אין חמץ. און ער פלעגט דאַן זאָגען, יה\"ר כשם שאני מבער את הסאָטקע יי\"ש מביתי כן תבער את כל החמץ שיש לי — דעם אייגענעם חמץ.\nז. דער אויבערשטער זאָל העלפן אַז די אַלע וואָס טוען יעדער אין זיין עבודה זאָל האָבען הצלחה בכל עניניו הכללים והפרטים, די וועלכע פאָרען אויף מנוחה זאַלען קומען געזונטערהייט און טוען זייער אַרבעט.\nח. לסיבת ה\"קאַלט סיסטעם\"<sup data-n=\"312\">13</sup>, הורשה ליכנס לכולם ואפילו הילדים הקטנים, ורצה הרש\"ל שי' לצוות להתלמידים הקטנים שיצאו, ואמר כ\"ק אדמו\"ר שליט\"א: מ'דאַרף ניט, יעצט זיינע זיי אַריין געגאַנגען, מיט דער צייט וועלען זיי זיין דאָ.",[["307","8","בחדר היחידות."],["308","9","ראה גם לקמן ע' 79."],["309","10","ראה אודותו לעיל ע' 17. וש\"נ."],["310","11","ראה ספר השיחות תר\"פ­תרפ\"ז ע' 29. תרפ\"ח­תרצ\"א ס\"ע 32 ואילך. תש\"ד ע' 84."],["311","12","מדה קטנה ביותר."],["312","13","{6} מערכת מזוג­אויר שהותקן בדירת רבינו בתקופה זו."]]],[4301620220,"<h3>רשימת ד\"ק ששמעתי מכ\"ק אדמו\"ר שליט\"א </h3><h3>עש\"ק פ' שופטים, כ\"ו מנחם-אב תש\"ו </h3>\nא. בשעה 1 אחר הצהרים נכנסתי להיכל כ\"ק אדמו\"ר שליט\"א, ובפנים מאירות שאלני: וואָס מאַכט מען, געלויבט השי\"ת אַז מען זעהט זיך, און וואָס הערט זיך.\nכ\"ק אדמו\"ר שליט\"א מספר: ווען החסיד ר' אשר ניקאָלאַיעווער<sup data-n=\"313\">1</sup> איז גע­קומען אין ליובאַוויטש, און ווען ער האָט דערהערט אַז כ\"ק אאמו\"ר איז ניט בקו הבריאות, איז ער תיכף צוריקגעפאָרען אַהיים בכדי ניט צו מטריח זיין את כ\"ק אאמו\"ר. (כמדומה לי שהתענית הידוע<sup data-n=\"314\">2</sup> של החסיד ר' אשר הנ\"ל, איז געווען מסיבת חלישות הבריאות של כ\"ק אאמו\"ר, וקבל עליו תענית שבוע שלימה, בהיותו בביתו. ונסע מביתו לליובאַוויטש ובא ביום הרביעי. בבואו,",[["313","1","ראה אודותו לעיל ע' 34 הערה 13."],["314","2","ראה גם רשימת היומן י\"ט כסלו תרצ\"ג (\"רשימות\" חוברת קסב ע' 9). ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 307. שיחת צום גדלי' תשנ\"ב (התוועדויות תשנ\"ב ח\"א ע' 32)."]]],[4301620221,"לא אמר לו כ\"ק אאמו\"ר להפסיק התענית, ורק שיתנהג בסדר בשינה, שלא הי' מדייק בזה, ועוד דברים, ובכניסת הש\"ק אמר לו כ\"ק אאמו\"ר שיתפלל ערבית, והזהירו שישתה הרבה, צונן וחמין).\nב. כ\"ק אדמו\"ר שליט\"א התאונן שמרגיש חלישות, אפיסת כח כפשוטו. ואמר: אין חדש אלול דאַרף מען דאָך ווערן אַ אַנדערער, כידוע פתגמו של החסיד הרג\"ד<sup data-n=\"315\">3</sup> בעת התוועדותו עם החסידים, שהי' מסיים: נו, מען דאַרף דאָך ווערן גאָר אַ אַנדערער<sup data-n=\"316\">4</sup>.\nוהמשיך דיבורו הק': מען דאַרף זיין געזונט מיט בריאות הגוף, גוף בריא. כ\"ק אאמו\"ר אמר פעם, אַז חכמה דאצילות איז מקנא אַ נשמה ווי זי איז יורד און באַלעבט אַ גוף בריא; די השגה וואָס חכמה דאצילות איז משיג, קאָן זי אָבער ניט האָבן דאָס וואָס אַ נשמה קאָן האָבן דורך ירידתה בגוף<sup data-n=\"317\">5</sup>. ובקשני למסור פ\"ש להתמימים, אַ אלול'דיקן גרוס. מען דאַרף אַז תלמידי התמימים משאַנחאי<sup data-n=\"318\">6</sup>, זאָלן משפיע זיין אויף די היגע תמימים אַז מען זאָל לערנען חסידות ווי מען בעדאַרף צו לערנען.\nג. כ\"ק אדמו\"ר שליט\"א ממשיך לספר: שכ\"ק אאמו\"ר הי' מספר לו הרבה סיפורים לבד מה שסיפר ברבים, הי' מספר לו ביחידות הרבה סיפורים. ושמע פעם מכ\"ק אאמו\"ר, אַז עצמות האָט געשוואָרען, אַז צו אַ משכיל זאָל ער זיך ניט מתגלה זיין, נאָר דורך עבודה, מיט דעם לימוד החסידות בעבודה, איז זיך מתגלה עצמותו. ופעם אמר כ\"ק אאמו\"ר אַז אַ משכיל איז מורד אין עצמות (ומבאר כ\"ק אדמו\"ר שליט\"א, שמורד גרוע מפוגם, מורד הוא ענין של זדון)<sup data-n=\"319\">7</sup>.\nד. וממשיך כ\"ק אדמו\"ר שליט\"א: שבור הנני על אודות ירידת המצב בהוה. ומספר: פעם יצא כ\"ק אדמו\"ר הזקן ואמר בניגון הידוע, \"אני לדודי\", אַז דער \"אני\" גיט זיך איבער צו דעם \"דודי\" איז \"ודודי לי\"<sup data-n=\"320\">8</sup>. ובזה הדיבור האָט ער דורכגעברענט די מדות פון די וואָס האָבן געהערט; עס איז געבליבען מדות וואָס דערהערען שכל, וויילע מדות דאַרפן דאָך זיין, אָבער זיי דאַרפן זיין שכליים. וזה המאמר הנ\"ל ישנו באריכות גדולה בכתבי כ\"ק אדמו\"ר האמצעי.\nה. כ\"ק אדמו\"ר שליט\"א הואיל להמ­שיך: בכלל יש אצלי אוצרות פון רשימות ושיחות מכ\"ק רבוה\"ק שנאמרו ביחיד וברבים, שצריכים לגלותם ולהוציאם.\nו. עס איז געווען אַ זמן ביי חסידים, שזה שלא למד חסידות בשביל להתפלל לא הרשו לו לשמוע חזרה.\nכשהי'<sup data-n=\"321\">9</sup> כ\"ק אאמו\"ר בגיל 17 או 18 שנה, הי' מאריך ביותר בתפלה, ואחר התפלה פלעגט ער בלייבען אָן כחות,",[["315","3","החסיד ר' גרשון דובער מפּאַהאַר. ראה אודותו לעיל ע' 5. וש\"נ."],["316","4","ראה לעיל שם. וש\"נ."],["317","5","ראה גם אגרות­-קודש ח\"ט ע' קס ואילך."],["318","6","בקיץ תש\"ו הגיע קבוצה תלמידי תומכי­תמימים משאַנגהאַי — ראה ספר תולדות חב\"ד בארצות הברית ע' קפב ואילך. על מצבם שם וההשתדלות להביאם לארה\"ב — ראה אגרות­-קודש ח\"ח ע' תרמ. ח\"ט ע' ג. וש\"נ. חי\"ג ע' תטז. על מסיבות קבלת הפנים שנערכו לכבודם — ראה אגרות­-קודש שם ע' קמד ואילך. ע' קמז."],["319","7","ברשימת ההנחה: הכוונה כי פוגם נוגע בהתפשטות ומורד הוא נוגע בהעצמות."],["320","8","שה\"ש ו, ג."],["321","9","ראה גם שיחת ליל ש\"ק פ' נח תש\"ז ס\"ג (לקמן ע' 82). וש\"נ."]]],[4301620222,"ואמר המלמד שלו ר' שלום<sup data-n=\"322\">10</sup> לכ\"ק אביו אאזמו\"ר מוהר\"ש שצריכים לראות שיקצר בתפלה. ענה לו ע\"ז כ\"ק אאזמו\"ר מוהר\"ש, וואָס קאָן איך אים זאָגן, אַז ער — כ\"ק אאמו\"ר — בתפלתו מרגיש האמת, דער גוף זיינער פילט דעם אמת, שגופו כלי להאמת. והרבנית הזקנה מרת רבקה<sup data-n=\"323\">11</sup>, סיפרה זאת פעם לכ\"ק אדמו\"ר שליט\"א, ואמרה אַז פון זינט זי האָט געהערט די ווערטער פון כ\"ק מוהר\"ש האָט זי געקראָגן פאַר אים — כ\"ק אאמו\"ר — אַן אַנדער דרך ארץ.\nכ\"ק אדמו\"ר שליט\"א מבקש לעורר את התמימים יחיו על ענין עבודת התפלה, אין הכוונה אריכות התפלה בכל יום, כ\"א לעתים צריכים להאריך בתפלה.\nז. מספר כ\"ק אדמו\"ר שליט\"א: שבעת האחרונה הי' חלוש ביותר ל\"ע, ובשמעו כי תלמידי התמימים נגנו ניגונים, האָט ער זיך פשוט אָפּגעלעבט, ער האָט דערהערט ליובאַוויטש.\nפעם אמר כ\"ק אאמו\"ר, אַז חיזוק הכחות הוא ע\"י התורה.\nולבסוף מבקש כ\"ק אדמו\"ר שליט\"א למסור אַ פנימיות'דיקן גערוס לכל וכו'.",[["322","10","הר\"ר שלום מקאדין. מלמד של אדמו\"ר מהורש\"ב נ\"ע והרז\"א — ראה חנוך לנער ע' 10. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 226. ע' 239. ע' 272. לקמן ע' 82. ס\"ע 353."],["323","11","ראה אודותה לעיל ע' 14. וש\"נ."]]],[4301620223,"<h3>יום א', ה' אלול תש\"ו<sup data-n=\"324\">1</sup> </h3>\n[בשעה שביעית ורבע, כשנכנסתי לפנים להיכל כ\"ק אדמו\"ר שליט\"א לשאול רשיון להכניס אנשים ליחידות כדרכי מימים ימימה, רמז לי שכוונתו שאשאר ושאל אצלי:] ווי אלול'ט זיך? וואָס הערט זיך אלול'דיג?\nואמר כ\"ק אדמו\"ר שליט\"א:\nאכן, צריך כוחות בגשמיות. (וסיפר): מלפנים היתה כל עיר ועיר נחשבת לפי מספר הבתי­כנסיות ובתי­מדרשות של החסידים אשר בעיר. היינו שעיר שהיו בה שתיים או שלוש בתי­כנסיות של אנ\"ש היתה נחשבת עיר קטנה ואם היו בה ארבע או חמש בתי­כנסיות של החסידים היתה נחשבת לעיר גדולה.\nכאשר נכנסו לביהכנ\"ס שמעו כיצד זה אומר ברוך שאמר והיה העולם בנעימות, והשני אומר פסוקי דזמרה וברכת יוצר אור בהתלהבות. בכלל, שבת­קודש היתה אצלם יום המנוחה. בימי השבוע היה כל אחד, בעל­עסק או מלמד וכד', עסוק בענינו, אבל שבת­קודש הרי הוא יום המנוחה. ובכן, המתינו עד אחרי התפילה, כלומר ששמעו את כל התפילה, ענו את כל האמן'ס, שמעו קריאת התורה עד סיום התפילה ואחרי הכל התחילו להתבונן עם מה מתפללים ועם מי מתפללים. כך שמעתי מכ\"ק אאמו\"ר בב' הנוסחאות וכבר רשום אצלי ביאורים וחילוקים בין ב' ענינים הללו בענינים יסודיים וסיפורי ענינים באריכות בזה<sup data-n=\"325\">2</sup>.\nוסיים: יש הרבה מה לעשות ואכן, דרושה הצלחה בעבודה, אבל צריך גם כוחות בגשמיות. . .",[["324","1","מרשימת הרה\"ח ר' אליהו (ייאכיל) סימפ­סאָן ממה ששמע מרבינו בתקופה ששימש כגבאי של רבינו. ראה אודותו לעיל ע' 51."],["325","2","ראה גם לעיל ע' 17. ע' 35. לקמן ע' 80. ע' 93."]]]]});
